window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-obstetricia-obs-2"]={"block":"medcurso:medcurso-obstetricia-obs-2","label":"Medcurso · OBS 2","count":417,"questions":[{"id":"medcurso-obstetricia-obs-2-343764","number":"343764","sourceNumber":"343764","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Diante de um quadro de trabalho de parto prematuro, qual conduta não deve ser\ntomada?","options":{"A":"Prescrever sulfato de magnésio em gestações abaixo de 32 semanas.","B":"Prescrever corticoterapia para gestantes com 36 semanas de gestação.","C":"Encaminhar a gestante para um centro de referência em prematuridade.","D":"Prescrever uterolíticos em gestações abaixo de 34 semanas, se não houver contraindicação."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-281142","number":"281142","sourceNumber":"281142","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Identifique a associação correta do ponto de referência fetal e da linha de orientação.","options":{"A":"I - lambda e sutura sagital.","B":"II - glabela e sutura metópica.","C":"III - bregma e sutura sagital.","D":"IV - glabela e linha facial.","E":"V - pés e sulco interglúteo."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-251881","number":"251881","sourceNumber":"251881","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primigesta, com 39 semanas de gestação, encontra-se em trabalho de parto há seis\nhoras. Nas últimas três horas, manteve a\ndilatação cervical de 6 cm, sem que houvesse\nmodificações no colo uterino, que se encontra medianizado e esvaecido em 50%. Quando a\npaciente foi internada, apresentava três contrações moderadas em 10 minutos. Nas últimas duas\nhoras, tem apresentado dinâmica uterina de duas contrações fracas em 10 minutos. A descida do\npolo cefálico vem se processando de forma progressiva e agora observa-se que o polo cefálico está\nno plano zero de De Lee. Com base no quadro clínico, o diagnóstico e a conduta são:","options":{"A":"Fase ativa prolongada, distócia funcional; deambulação e, se necessário, ocitocina.","B":"Fase de latência prolongada; administrar ocitocina e realizar amniotomia.","C":"Período de latência prolongada; administrar ocitocina e realizar amniotomia.","D":"Desproporção céfalo-pélvica relativa; indicar operação cesariana."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-217730","number":"217730","sourceNumber":"217730","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Qual dos itens abaixo, liberado a partir dos lisossomas, é capaz de iniciar o trabalho de\nparto?","options":{"A":"Ácido araquidônico.","B":"Fosfatidilinositol.","C":"Fosfolipase A.","D":"Fosfatidilglicerol."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-183199","number":"183199","sourceNumber":"183199","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primigesta de 28 anos apresenta-se em trabalho de parto a termo. Pelvimetria clínica é\nrealizada. Ela tem uma pelve ovalada, com o diâmetro ântero-posterior do estreito pélvico maior do\nque o diâmetro transverso. O feto se encontra em variedade de posição occipito-direita-posterior.\n\nQual é o tipo mais provável de pelve?","options":{"A":"Ginecoide.","B":"Androide.","C":"Antropoide.","D":"Platipeloide.","E":"Androgênica."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-183207","number":"183207","sourceNumber":"183207","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"De acordo com os estudos de Zhang et AL. (2010), um novo padrão de evolução do\ntrabalho de parto foi modernamente estabelecido. Considerando os resultados obtidos pelos\nautores estudando mais de 60.000 parturientes com desfechos neonatais normais, qual o novo\nponto de corte estabelecido para marcar o início da FASE ATIVA do trabalho de parto?","options":{"A":"2 cm.","B":"3 cm.","C":"4 cm.","D":"5cm.","E":"6 cm."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-183168","number":"183168","sourceNumber":"183168","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primigesta de 20 anos com idade gestacional de 38 semanas encontra-se com\ncontrações regulares e dolorosas, 4 em 10\nminutos durando 50-60 segundos. FCF =144 bpm. Ao\ntoque, colo com 3 cm de dilatação e 90% de apagamento, apresentação cefálica em OEA, plano 0\nde DeLee, bolsa íntegra. Recebe analgesia peridural para alívio da dor. Uma hora depois, FCF=148\nbpm, sem desacelerações. Dinâmica uterina inalterada. Colo dilatado 5 cm, apagado 100%,\napresentação cefálica em plano +1 de DeLee, bolsa integra. Paciente se manifesta muito satisfeita\ncom o alívio da dor, está deambulando e com liberdade para escolha da posição. Acompanhante a\nlado. Qual é o próximo passo na assistência?","options":{"A":"Iniciar puxos dirigidos.","B":"Iniciar ocitocina para incrementar o padrão contrátil.","C":"Nenhuma intervenção, o trabalho de parto está progredindo normalmente.","D":"Realizar cesariana por parada de progressão do trabalho de parto.","E":"Romper a bolsa e interromper a peridural para aumentar as contrações e permitir dilatação mais\nrápida."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-182667","number":"182667","sourceNumber":"182667","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primigesta, com 39 semanas de gestação, encontra-se em trabalho de parto há seis\nhoras. Nas últimas três horas, manteve a\ndilatação cervical de 6 cm, sem que houvesse\nmodificações no colo uterino, que se encontra medianizado e esvaecido em 50%. Quando a\npaciente foi internada, apresentava três contrações moderadas em 10 minutos. Nas últimas duas\nhoras, tem apresentado dinâmica uterina de duas contrações fracas em 10 minutos. A descida do\npolo cefálico vem se processando de forma progressiva e agora se observa que o polo cefálico está\nno plano zero de De Lee. Com base no quadro clínico, o diagnóstico e a conduta são,\nrespectivamente:","options":{"A":"Fase ativa prolongada, distócia funcional; deambulação e, se necessário, ocitocina.","B":"Fase de latência prolongada; administrar ocitocina e realizar amniotomia.","C":"Período pélvico prolongado; realizar amniotomia e administrar ocitocina.","D":"Desproporção céfalo-pélvica relativa; indicar operação cesariana."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-159047","number":"159047","sourceNumber":"159047","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Sobre a rotura prematura das membranas ovulares, é CORRETO afirmar que:","options":{"A":"A confirmação diagnóstica é feita exclusivamente pela ultrassonografia, através da avaliação da\nquantidade de líquido amniótico.","B":"Em vigência de corioamnionite, a conduta é resolutiva, independente da idade gestacional.","C":"Em gestações a termo, a paciente deve ser internada para avaliar o bem estar fetal a cada 48\nhoras e a conduta deve ser expectante se não houver sinais de infecção.","D":"A tocólise está sempre indicada, mesmo em vigência de infecção, visando o ganho de peso\nfetal."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-159072","number":"159072","sourceNumber":"159072","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"São utilizados como agentes mecânicos no amadurecimento cervical, EXCETO:","options":{"A":"Método de Krause.","B":"Dilatador higroscópico","C":"Descolamento das membranas.","D":"Relaxina."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-159081","number":"159081","sourceNumber":"159081","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Sobre a amniotomia é INCORRETO afirmar:","options":{"A":"Quando realizada com o pólo cefálico encaixado na pelve materna, reduz a possibilidade de\nacidentes com o cordão umbilical.","B":"Após a amniotomia deve-se auscultar os BCFs antes, durante e após a contração.","C":"Entre as principais indicações estão a prova de trabalho de parto, a necessidade de avaliação\ndo líquido amniótico e instalação de\nmonitorização fetal interna.","D":"Na suspeita de vasa prévia, devemos realizar a amniotomia como conduta inicial."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-108719","number":"108719","sourceNumber":"108719","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Uma paciente é admitida na fase ativa do trabalho de parto. Ela não fez pré-natal, mas\nafirma estar com 41 semanas de gestação. Ao exame para verificar o colo e a posição fetal você\ntoca a face e o nariz do feto. Qual das seguintes opções mais frequentemente se associa com\napresentação de face?","options":{"A":"Hidrocefalia;","B":"Anencefalia;","C":"Prematuridade;","D":"Oligoâmnio."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-108724","number":"108724","sourceNumber":"108724","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A perda sanguínea média em parto um parto vaginal não complicado é estimada em\nquantos mililitros (ml) aproximadamente?","options":{"A":"150 ml;","B":"550 ml;","C":"850 ml;","D":"1.000 ml."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-84501","number":"84501","sourceNumber":"84501","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O exame vaginal (toque bimanual) de uma paciente em trabalho de parto revela, após\ntrês exames sucessivos, o polo cefálico no\nII/III Plano de Hodge, variedade de posição em\noccipito-ilíaca esquerda anterior, com bossa serossanguinolenta, apesar de aumento da dilatação.\nAs metrossístoles encontram-se dentro dos padrões de normalidade e os batimentos caradíacos\nfetais mantêm-se em 134 bpm. Qual a conduta mais adequada para o caso relatado?","options":{"A":"Infusão endovenosa de ocitocina.","B":"Aplicação intramuscular de metilergonovina.","C":"Extração fetal por via alta (cesariana).","D":"Aplicação de fórcipe de alívio.","E":"Conduta expectante."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-66999","number":"66999","sourceNumber":"66999","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante com diagnóstico confirmado de rotura prematura de membranas com 25\nsemanas de gestação. A conduta deverá ser:","options":{"A":"Acompanhamento ambulatorial a cada 15 dias, depois internação quando completar 28\nsemanas;","B":"Por se tratar de feto inviável, o risco materno de adquirir infecção grave e morte, justifica-se\norientar a paciente para interromper a gestação\nimediatamente antes que surjam complicações;","C":"Manter a paciente internada e realizar reposição do líquido amniótico por amnioinfusão até\ncompletar-se 28 semanas e interromper a gestação com esta idade gestacional;","D":"Conservadora nos seguintes termos: internação; pesquisa de infecção com exames laboratoriais\ne exame clínico da paciente;\nantibioticoterapia; corticoterapia; repouso; hidratação; interromper a\ngestação ao alcançar 32 semanas ou antes se surgirem sinais de infecção ou SFA."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-67001","number":"67001","sourceNumber":"67001","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"São drogas utilizadas na inibição do trabalho de parto prematuro, EXCETO:","options":{"A":"Atosiban;","B":"Nifedipino;","C":"Salbutamol;","D":"Ibuprofeno;"},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-67010","number":"67010","sourceNumber":"67010","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante com rotura prematura de membranas com 35 semanas de gestação, sua\nconduta seria:","options":{"A":"Internação, antibioticoterapia, corticoterapia e interrupção de gestação após 48 horas;","B":"Internação, antibioticoterapia, interrupção da gestação com 37 semanas;","C":"Internação, antibioticoterapia, interrupção imediata da gestação;","D":"Internação, corticoterapia, interrupção imediata da gestação."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-50101","number":"50101","sourceNumber":"50101","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Todas são condições que contraindicam o uso do misoprostol para preparo do colo\nuterino, EXCETO:","options":{"A":"Sofrimento fetal agudo;","B":"Infecção ativa por herpes;","C":"Oligoâmnio severo;","D":"Placenta prévia;"},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-50030","number":"50030","sourceNumber":"50030","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Frente a uma gestante de 27 semanas de gestação, confirmada rotura de membranas,\nque apresente febre e taquicardia fetal, a melhor\nconduta será:","options":{"A":"Cesariana de imediato;","B":"Corticoide por 48 horas para maturação fetal, antibióticos para controle da infecção e indução do\nparto após 48 horas;","C":"Devido ao risco materno-fetal pela coriamnionite, o melhor será iniciar antibioticoterapia e\ninterrupção imediata da gestação com via de parto de indicação obstétrica;","D":"Corticoide por 48 horas para maturação fetal, antibióticos para controle da infecção e cesariana\napós 48 horas;"},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-50033","number":"50033","sourceNumber":"50033","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Estará indicada a inibição do trabalho de parto na seguinte situação:","options":{"A":"Gestação de 33 semanas, dinâmica uterina 3/10/45, colo dilatado 3 cm, bolsa íntegra, diabetes\ngestacional confirmado com polidrâmnio;","B":"Gestação de 36 semanas, com dinâmica uterina 3/10/45, colo dilatado 3 cm, bolsa íntegra,\nvitalidade fetal preservada;","C":"Rotura prematura de membranas de 35 semanas, em trabalho de parto prematuro, na ausência\nde infecção;","D":"Trabalho de parto prematuro de 32 semanas, colo dilatado 2 cm, dinâmica uterina 2/10/30,\noligoâmnio acentuado;"},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-37138","number":"37138","sourceNumber":"37138","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Durante avaliação do trabalho de parto, o obstetra percebe a fontanela posterior às 2\nhoras. Trata-se da seguinte variedade de posição:","options":{"A":"occipto-transversa","B":"occipto-direita anterior","C":"occipto-posterior","D":"occipto-esquerda anterior","E":"occipto-esquerda posterior"},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-37140","number":"37140","sourceNumber":"37140","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Durante a assistência ao trabalho de parto, você faz o diagnóstico de distócia de ombro\ntomando as seguintes condutas, exceto:","options":{"A":"Manobra de McRoberts","B":"Manobra de Woods","C":"Manobra de Rubin","D":"Manobra de Zavanelli","E":"Manobra de Budin"},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-37143","number":"37143","sourceNumber":"37143","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O parto está indicado na rotura prematura de membranas nas seguintes situações,\nexceto:","options":{"A":"Acima de 34 semanas.","B":"Na suspeita de infecção amniótica.","C":"Na confirmação da maturidade fetal após 28 semanas.","D":"Quando o peso fetal for maior que 1500 g.","E":"Se houver TP com dilatação maior que 4 cm."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-37144","number":"37144","sourceNumber":"37144","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A inibição do trabalho de parto não estará indicada a partir da seguinte idade\ngestacional:","options":{"A":"Após 28 semanas","B":"Após 32 semanas","C":"Após 34 semanas","D":"Após 36 semanas","E":"Após 37 semanas"},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-29408","number":"29408","sourceNumber":"29408","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A inibição do parto prematuro pode ser realizado com as seguintes drogas, exceto:","options":{"A":"terbutalina","B":"nifedipino","C":"atosiban","D":"sulfato de magnésio","E":"aminofilina"},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-29409","number":"29409","sourceNumber":"29409","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O intervalo em que está indicada a indução da maturação pulmonar fetal, segundo as\núltimas evidências é de:","options":{"A":"entre 22 e 28 semanas","B":"entre 24 e 28 semanas","C":"entre 26 e 34 semanas","D":"entre 24 e 34 semanas","E":"entre 28 e 34 semanas"},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-341064","number":"341064","sourceNumber":"341064","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante, 26 semanas, com obesidade grau 2, nega comorbidades. Tercigesta e\nprimípara, vem para consulta de pré-natal com ultrassonografia morfológica de 2º trimestre,\nevidenciando feto único vivo, cefálico, placenta grau 0, peso estimado no percentil 95, ILA sem\nalterações. Ausência de alterações na morfologia fetal. Uma das maiores preocupações no parto\nnormal de fetos, em casos como esse, é a distocia de ombros. Indique a manobra utilizada na\ntentativa de desprendimento do ovoide córmico.","options":{"A":"McRoberts.","B":"Leopold.","C":"Ritgen.","D":"Jacob Dublin."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-343203","number":"343203","sourceNumber":"343203","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Uma gestante dá entrada na maternidade em trabalho de parto. Ao toque colo dilatado\n4 cm, bolsa rota, apresentação cefálica.\nAberto o partograma de Friedmann, o Obstetra deve traçar\na linha de ação:","options":{"A":"2 horas após a linha de alerta.","B":"2 horas antes da linha de alerta.","C":"4 horas após a linha de alerta.","D":"4 horas antes da linha de alerta."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-343205","number":"343205","sourceNumber":"343205","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Considere as seguintes características do toque obstétrico: I. Dilatação do colo. II.\nAltura da apresentação. III. Flexão cefálica\nfetal. IV. Apagamento do colo. São avaliados no Índice\nde Bishop:","options":{"A":"I e II, somente.","B":"I, II e III, somente.","C":"II e IV, somente.","D":"I, II e IV, somente."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-313457","number":"313457","sourceNumber":"313457","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante em acompanhamento pré-natal de alto risco por antecedente de\nprematuridade, com idade gestacional de 27\nsemanas, sem queixas, apresenta na atual gestação\ncolo com comprimento de 28 mm e presença de ?sludge? ao ultrassom. O tratamento\nrecomendado no momento é:","options":{"A":"Nifedipina.","B":"Anti-inflamatório.","C":"Antibiótico.","D":"Antialérgico."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-307059","number":"307059","sourceNumber":"307059","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Jovem, 25 anos de idade, gestante de 35 semanas, sem comorbidades, primigesta,\nvem ao pronto-atendimento da maternidade\ncom queixa de dor abdominal a cada 3 minutos. Nega\nfebre ou perda de líquido por via vaginal. Ao exame: abdome com tônus uterino preservado,\ndinâmica uterina presente, rítmica e de moderada intensidade, a cada 3 minutos, com duração de\n40 segundos cada contração. Altura uterina: 32cm. Batimentos cardíacos fetais: 144bpm em\nquadrante inferior esquerdo. Toque vaginal: 4cm de dilatação, bolsa íntegra, polo cefálico ainda\nalto. Paciente encaminhada para realização de cardiotocografia, tendo, no meio do exame, evoluido\ncom ruptura de bolsa e perda de líquido amniótico via vaginal; com desaceleração importante dos\nbatimentos cardiofetais. Confirmada, em toque vaginal, a principal suspeita diagnóstica, indique a\nconduta nesse momento:","options":{"A":"Retirar imediatamente a mão no toque vaginal e seguir para cesariana.","B":"Manter a mão no toque vaginal e encaminhar a paciente com urgência para interrupção da\ngestação por cesárea.","C":"Encaminhar a paciente para ultrassonografia para avaliação de perfil biofísico fetal.","D":"Modificar o decúbito, ofertar glicose e reavaliar o ritmo cardíaco fetal."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-276001","number":"276001","sourceNumber":"276001","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Observe o partograma abaixo e assinale a resposta INCORRETA.","options":{"A":"Ocorreu parada secundária da dilatação.","B":"Este quadro pode ser compatível com desproporção céfalo-pélvica.","C":"Não observamos sinais de sofrimento fetal.","D":"Há indicação de cesariana após horas de trabalho de parto.","E":"Este retrato da evolução do parto pode ser encontrado em casos de diabetes gestacional\ndescompensado com fetos grandes para a idade gestacional."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-280443","number":"280443","sourceNumber":"280443","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em mulheres, o tipo mais raro de bacia é","options":{"A":"ginecóide.","B":"andróide.","C":"platipelóide.","D":"antropóide."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-280448","number":"280448","sourceNumber":"280448","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em um parto normal com feto em apresentação pélvica, após a saída do tronco fetal, o\nmesmo é rebatido em direção ao abdome materno. Essa manobra leva o nome de","options":{"A":"Bracht.","B":"McRoberts.","C":"Mauriceau.","D":"Zavanelli."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-278133","number":"278133","sourceNumber":"278133","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em relação à anatomia da bacia obstétrica considere as seguintes assertivas. I. Estreito\nsuperior: sínfise púbica ao promontório. II. Estreito médio: ao nível das espinhas ciáticas. III.\nEstreito inferior: entre borda superior da sínfise púbica e espinhas ciáticas. IV. Conjugata\ndiagonalis: borda superior da sínfise púbica ao promontório. Estão CORRETAS:","options":{"A":"I e II.","B":"I e III.","C":"II e III.","D":"II e IV."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-278663","number":"278663","sourceNumber":"278663","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante de 37 semanas, com queixa de perda de líquido amniótico há 3 horas. Ao\nexame especular, visualizada pequena quantidade\nde líquido em fundo de saco vaginal e o obstetra\nficou em dúvida se houve amniorrexe. O melhor achado complementar para confirmar o diagnóstico\né:","options":{"A":"PH vaginal abaixo de 5,0.","B":"Hemograma com discreta leucocitose.","C":"Muco cervical apresentando cristalização arboriforme.","D":"Índice de Líquido Amniótico (ILA) = 9,0 cm ao ultrassom."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-279083","number":"279083","sourceNumber":"279083","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Droga considerada promissora para uso doméstico na terapia de manutenção pós\ntocólise hospitalar.","options":{"A":"Terbutalina.","B":"Progesterona Micronizada.","C":"Sulfato de Magnésio.","D":"Atosiban."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-280454","number":"280454","sourceNumber":"280454","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante G2 P1 (Normal), A0, idade gestacional de 34/35 semanas, dá entrada em\nmaternidade com quadro de febre e perda de líquido amniótico há 36 horas. A melhor conduta\nnesse caso é","options":{"A":"tocólise por 24 horas e corticóide.","B":"corticóide e conduta expectante.","C":"antibiótico e indução do parto.","D":"antibiótico e conduta expectante."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-252912","number":"252912","sourceNumber":"252912","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Mulher tercigista e secundipara (partos normais). Fez pré-natal adequado e nega\nalterações em exames laboratoriais. Deu\nentrada na emergência da Maternidade com 38 semanas\nde gestação, queixando-se de dor em baixo ventre, apresentando 4 contrações de 40 segundos\ncada, em intervalo de 10 minutos. Batimento cardíaco fetal: 144bpm. Ao toque vaginal, colo\ndilatado 9cm, fino, bolsa integra, apresentação em +1 de De Lee com Lambda em correspondência\ncom estreito superior da bacia à esquerda e anteriormente. Identifique a apresentação e a\nvariedade de posição fetal.","options":{"A":"Cefálica fletida e occipito esquerda posterior (OEP).","B":"Cefálica defletida e mento esquerda anterior (MEA).","C":"Cefálica fletida e occipito esquerda anterior (OEA).","D":"Cefálica defletida e bregma esquerda anterior (BEA)."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-252913","number":"252913","sourceNumber":"252913","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Mulher tercigista e secundipara (partos normais). Fez pré-natal adequado e nega\nalterações em exames laboratoriais. Deu\nentrada na emergência da Maternidade com 38 semanas\nde gestação, queixando-se de dor em baixo ventre, apresentando 4 contrações de 40 segundos\ncada, em intervalo de 10 minutos. Batimento cardíaco fetal: 144bpm. Ao toque vaginal, colo\ndilatado 9cm, fino, bolsa integra, apresentação em +1 de De Lee com Lambda em correspondência\ncom estreito superior da bacia à esquerda e anteriormente. Diante do tipo de apresentação fetal,\nidentificada no caso, indique os tempos normais do mecanismo do parto, em ordem cronológica.","options":{"A":"Flexão da cabeça, descida, deflexão da cabeça e rotação externa da cabeça.","B":"Insinuação, rotação interna da cabeça, rotação interna das espáduas e deflexão da cabeça.","C":"Insinuação, descida, rotação externa das espáduas e rotação externa da cabeça.","D":"Flexão da cabeça, deflexão da cabeça, rotação interna da cabeça e rotação externa das\nespaduas."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-252914","number":"252914","sourceNumber":"252914","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Mulher tercigesta e secundípara (partos normais). Fez pré-natal adequado e nega\nalterações em exames laboratoriais. Deu\nentrada na emergência da maternidade com 38 semanas\nde gestação, queixando-se de dor em baixo-ventre, apresentando 4 contrações de 40 segundos\ncada, em intervalo de 10 minutos. Batimento cardíaco fetal: 144 bpm. Ao toque vaginal, colo\ndilatado 9 cm, fino, bolsa íntegra, apresentação em +1 de DeLee com Lambda em correspondência\ncom estreito superior da bacia à esquerda e anteriormente. Para melhorar a assistência dessa\npaciente durante o trabalho de parto, diversas intervenções poderão ser realizadas. Com relação a\nessas intervenções, é CORRETO afirmar:","options":{"A":"A amniotomia deve ser realizada rotineiramente no final da dilatação, diminuindo assim as taxas\nde cesariana.","B":"A manobra de Kristeller deve ser realizada em casos com período expulsivo prolongado.","C":"A episiotomia deve ser realizada com o intuito de proteger o períneo posterior.","D":"No secundamento são importantes a tração controlada do cordão e o uso de agentes\nuterotônicos para diminuir risco de hemorragia."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-249251","number":"249251","sourceNumber":"249251","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Considerada manobra perigosa e atualmente é desaconselhada:","options":{"A":"McRoberts","B":"Bracht","C":"Mauriceau","D":"Kristeller"},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-212210","number":"212210","sourceNumber":"212210","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A manobra de Harvey correlaciona-se a","options":{"A":"secundamento natural.","B":"retenção placentária.","C":"prolapso de cordão.","D":"placenta acreta.","E":"parto pélvico."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-215251","number":"215251","sourceNumber":"215251","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em feto com apresentação cefálica fletida em ODA (Occipito-direita-anterior), ao optar\npor utilizar o fórcipe, a rotação em graus e o\nsentido seriam:","options":{"A":"45 graus sentido horário.","B":"45 graus sentido anti-horário.","C":"90 graus sentido horário.","D":"90 graus sentido anti-horário."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-215256","number":"215256","sourceNumber":"215256","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Um inconveniente da utilização de Indometacina como tocolítico por mais de 72 horas é\na ocorrência de:","options":{"A":"Obstipação crônica.","B":"Fechamento de ducto arterioso fetal.","C":"Desequilíbrio hidroeletrolítico.","D":"Expulsão de um feto vivo."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-187827","number":"187827","sourceNumber":"187827","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Assinalar A PRIMEIRA CONDUTA A SER ADOTADA imediatamente após o\ndiagnóstico de uma distócia de ombro:","options":{"A":"Fratura intencional da clavícula fetal","B":"Hipereflexão da coxas da parturiente e pressão supra-púbica","C":"Pressão no fundo do útero, exercida por um auxiliar experiente","D":"Pressão sobre o pólo cefálico em direção ao períneo da parturiente"},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-187865","number":"187865","sourceNumber":"187865","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Assinalar a alternativa ERRADA em relação à infecção intraamniótica (Coriomnionite):","options":{"A":"Deve se aguardar os resultados dos exames bacteriológicos para se iniciar a antibioticoterapia","B":"É uma infecção polimicrobiana envolvendo bactérias aeróbias e anaeróbias da flora vaginal","C":"Está associada elevada morbidade e mortalidade neonatal","D":"Os principais sinais clínicos da infecção intraamniótica são febre materna e taquicardia fetal"},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-180135","number":"180135","sourceNumber":"180135","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Durante o trabalho de parto de um feto vivo e a termo em primingesta, um toque vaginal\ncom 6 cm de dilatação do colo revela o mento como ponto de referência fetal. No segundo toque,\napós duas horas, permanece a mesma referência, agora com 7 cm. Assinale a alternativa que\napresenta a CONDUTA CORRETA.","options":{"A":"Realizar correção manual.","B":"Indicar cesariana.","C":"Administrar ocitocina.","D":"Utilizar fórceps de Kielland.","E":"Mudar o decúbito materno."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-182771","number":"182771","sourceNumber":"182771","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"São medidas consideradas consagradas em trabalho de parto bem conduzido,\nEXCETO:","options":{"A":"Liberar deambulação durante o período de dilatação.","B":"Ausculta intermitente a cada 30 minutos no período de dilatação.","C":"Ocitocina IM após liberação dos ombros fetais.","D":"Episiotomia mediana."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-182795","number":"182795","sourceNumber":"182795","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A importância anatômica do canal de Alcock reside no fato de:","options":{"A":"ser o local onde acontecem os prolapsos uterinos","B":"ser o ponto de reparo para anestesia loco-regional em parto normal","C":"ser o local onde mais ocorrem as cistoceles","D":"ser o local onde mais ocorrem as enteroceles"},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-183570","number":"183570","sourceNumber":"183570","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Do ponto de vista farmacológico, a maioria das drogas tocolíticas utilizadas em\nmaternidades são:","options":{"A":"bloqueadores dos canais de cálcio.","B":"inibidores seletivos de recaptação de serotonina.","C":"inibidores da enzima conversora de angiotensinogênio.","D":"inibidores da monoamina-oxidase B."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-183030","number":"183030","sourceNumber":"183030","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A manobra que consiste na introdução do dedo indicador do obstetra na cavidade oral\ndo feto no momento do parto visando a liberação do polo cefálico na cabeça derradeira é","options":{"A":"McRoberts.","B":"Mauriceau.","C":"Bracht.","D":"Kristeller."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-183035","number":"183035","sourceNumber":"183035","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante portadora de Herpes genital, nega lesão ativa há mais de 4 meses. Aponte a\nassertiva que corresponde à conduta CORRETA no momento do parto.","options":{"A":"Mesmo sem lesão ativa o feto corre grande risco, portanto há indicação de cesárea.","B":"Sem lesão ativa, não há indicação de cesárea, pois o risco de transmissão, nesse caso, é\ndesprezível.","C":"Deve ser solicitada a carga viral para verificar se há necessidade de cesárea.","D":"A transmissão para o feto é transplacentária, não importando o tipo de parto, mesmo em casos\nde lesão vulvar ativa."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-182752","number":"182752","sourceNumber":"182752","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante de 31 semanas com amniorrexe prematura, vitalidade fetal preservada. Nesse\ncaso, a melhor conduta é:","options":{"A":"Corticóide e acompanhamento ambulatorial duas vezes por semana.","B":"Internação, corticóide, conduta expectante e antibiótico profilático.","C":"Internação, corticóide e resolução em 48 horas.","D":"Internação e indução do parto."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-183056","number":"183056","sourceNumber":"183056","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Dequitação placentária onde a face materna da placenta se exterioriza antes da face\nfetal:","options":{"A":"Baudelocque-Duncan.","B":"Baudelocque-Schultze.","C":"Seymour-Duncan.","D":"Nobile-Budin."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-152638","number":"152638","sourceNumber":"152638","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Na apresentação cefálica defletida de 3º grau, qual o ponto de referência fetal?","options":{"A":"Lambda.","B":"Bregma.","C":"Naso.","D":"Mento.","E":"Occipto."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-158751","number":"158751","sourceNumber":"158751","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A manobra auxiliar no secundamento natural (expulsão da placenta fisiologicamente)\npara o desprendimento das membranas ovulares é\ndenominada Manobra de:","options":{"A":"Fabre.","B":"Credé.","C":"Harvey.","D":"Ahlfeld.","E":"Jacob-Dublin."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-158764","number":"158764","sourceNumber":"158764","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Parturiente encaminhada para HUPAA em trabalho de parto. Durante exame\nobservou-se dilatação 7 cm, linha de orientação a\nsutura sagito-metópica e o ponto referência ao\ntoque encontra-se próximo a iminência iliopectínea à direita. Diante desse quadro, é CORRETO\nafirmar:","options":{"A":"O feto encontra-se cefálico e fletido.","B":"O feto encontra-se defletido primeiro grau.","C":"O feto encontra-se cefálico e defletido terceiro grau.","D":"O feto encontra-se defletido segundo grau e variedade posição bda.","E":"A variedade da posição observada foi certamente ODA (Occipito Direita Anterior)."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-161239","number":"161239","sourceNumber":"161239","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A utilização de corticoide pode ser utilizada para amadurecimento pulmonar fetal na\ngestação e deve ser feita uma única vez. A repetição sistemática semanal desse procedimento,\nalém de contraindicada, pode levar:","options":{"A":"A diabetes fetal.","B":"À restrição de crescimento fetal.","C":"À polidramnia","D":"À hipotiroidismo fetal."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-161140","number":"161140","sourceNumber":"161140","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Acerca da prematuridade, assinale a alternativa CORRETA.","options":{"A":"O sulfato de Magnésio é droga efetiva na inibição das contrações uterinas e com efeitos\ncolaterais mínimos.","B":"O álcool pode ser utilizado como tocolítico, uma vez que a dose tóxica é bastante inferior à dose\nterapêutica.","C":"A Nifedipina é eficaz como tocolítico e com poucos efeitos colaterais.","D":"A Terbutalina pode ser utilizada na forma endovenosa, necessitando de controle materno\nrigoroso, uma vez que pode causar bradicardia severa."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-158811","number":"158811","sourceNumber":"158811","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Denomina-se período de latência na amniorrexe prematura:","options":{"A":"O período pós parto imediato.","B":"O período necessário para o nascimento do feto após a ruptura das membranas.","C":"O período compreendido entre a ruptura das membranas e o período expulsivo do feto.","D":"O tempo necessário para o escoamento do líquido amniótico, após a ruptura das membranas.","E":"O período compreendido entre a ruptura das membranas ovulares e o início das metrossístoles."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-161391","number":"161391","sourceNumber":"161391","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"No momento do parto a opção pela perineotomia (episiotomia medial) apresenta\nvantagens em relação à episiotomia médio\nlateral direita, com EXCEÇÃO de menor:","options":{"A":"Risco de deiscência.","B":"Sangramento.","C":"Chance de dispareunia.","D":"Possibilidade de prolongamento inadvertido da lesão."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-161174","number":"161174","sourceNumber":"161174","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"?Manobra perigosa onde é realizada a compressão do fundo uterino na fase final do\ntrabalho de parto.? Assinale a alternativa a que se refere essa definição.","options":{"A":"Baudelocque Duncan.","B":"Mauriceau.","C":"Kristeller.","D":"Bracht."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-139721","number":"139721","sourceNumber":"139721","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Na dequitação pelo mecanismo de Baudelocque-Duncan é correto afirmar:","options":{"A":"A face fetal da placenta apresenta-se na vulva.","B":"A separação inicia-se no centro da placenta.","C":"O sangue coleta-se atrás da placenta.","D":"A face materna da placenta apresenta-se na vulva.","E":"O sangramento ocorre após a saída da placenta."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-131364","number":"131364","sourceNumber":"131364","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O ponto de referência fetal na apresentação cefálica defletida de terceiro grau é:","options":{"A":"Lâmbda.","B":"Bregma.","C":"Glabela.","D":"Mento.","E":"Crista sacrococcígea."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-131383","number":"131383","sourceNumber":"131383","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Observe o partograma abaixo (VER IMAGEM) e assinale a alternativa correta.","options":{"A":"Ocorreu parada da dilatação cervical.","B":"O partograma em questão evidencia uma atividade uterina fraca.","C":"Ocorreu descida satisfatória da apresentação.","D":"O partograma em questão caracteriza uma distócia de rotação e descida insatisfatória da\napresentação.","E":"Ocorreu parto precipitado."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-134794","number":"134794","sourceNumber":"134794","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante de 25 anos, primigesta, com idade gestacional de 41 semanas e 6 dias, sem\nqueixas, procura o PS com os seguintes dados: PA = 110 x 70 mmHg / BCF = 140 bpm. Ao toque:\ncolo impérvio, posterior e grosso. Para esse caso, a MELHOR conduta é","options":{"A":"Preparar o colo uterino com misoprostol.","B":"Induzir o parto com ocitocina ? 2 um/min.","C":"Induzir o parto com ocitocina ? 4 um/min.","D":"Realizar cesárea em virtude do colo desfavorável."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-134126","number":"134126","sourceNumber":"134126","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante de 20 anos, G2 P1 A0 C0, com 33 semanas de gestação, chega ao\nPronto-socorro com perda de líquido que escorria pelas pernas, em moderada quantidade,\n\nclaro/transparente, sem cheiro, há 4 horas, nega endurecimento da barriga, refere movimentação\nfetal. Ao exame: AU = 30 cm, BCF = 136 bpm, ao\nexame especular vagina brilhante e saída de\npequena quantidade de liquido transparente pelo colo do útero. Diante de tal caso, qual é o\ndiagnóstico e a MELHOR conduta?","options":{"A":"Amniorrexe prematura, interromper a gestação imediatamente com cesárea.","B":"Amniorrexe prematura, induzir o parto vaginal.","C":"Amniorrexe prematura, internar a paciente, solicitar exames e observar.","D":"Perda insensível de urina, orientar a paciente, apenas."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-110593","number":"110593","sourceNumber":"110593","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Com relação à dequitação da placenta, o mecanismo de Baudelocque-Duncan\ncaracteriza-se por, EXCETO:","options":{"A":"A face materna da placenta apresentar-se na vulva. C.","B":"A separação inicia-se na periferia. C.","C":"O sangramento é posterior à saída da placenta. E .","D":"Não é o mecanismo mais frequente. C.","E":"É considerado um mecanismo fisiológico de\ndequitação."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-110534","number":"110534","sourceNumber":"110534","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O ponto de referência no parto cefálico defletido de primeiro grau é:","options":{"A":"Lambda.","B":"Bregma.","C":"Nariz.","D":"Boca.","E":"Mento."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-110548","number":"110548","sourceNumber":"110548","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Com relação à pelve feminina, assinale a alternativa INCORRETA:","options":{"A":"O estreito superior da pequena bacia é delimitado por uma linha imaginária que vai da borda\nsuperior da sínfise púbica ao promontório.","B":"No estreito superior da pequena bacia, o diâmetro transverso é menor que o anteroposterior.","C":"Durante a passagem do feto pelo canal de parto, o segmento mais difícil é o polo cefálico.","D":"É constituída de partes ósseas, músculos e aponeuroses.","E":"Ao examinarmos uma bacia, durante o exame de toque, os pontos que devemos observar são o\npromontório, as espinhas ilíacas e o ângulo subpúbico."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-110556","number":"110556","sourceNumber":"110556","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"São drogas utilizadas para inibição do trabalho de parto prematuro, EXCETO:","options":{"A":"Sulfato de magnésio.","B":"Nifedipina.","C":"Terbutalina.","D":"Ocitocina.","E":"Acetato de atosibana."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-110003","number":"110003","sourceNumber":"110003","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Os Exames Complementares que possibilitam a avaliação da Maturidade Fetal são","options":{"A":"dopplerfluxometria da Artéria Umbilical e Espectrofotometria do Líquido Amniótico.","B":"prova de Pose e Espectrofotometria do Líquido Amniótico com DDO a 650.","C":"pesquisa de Corpos Lamelares e Dosagem do hormônio Lactogênio Placentário.","D":"teste de Clements e Dosagem de Fosfatidilglicerol."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-109737","number":"109737","sourceNumber":"109737","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Os estreitos, bacia obstétrica, possuem os diâmetros conjugados no seu estreito\nsuperior, qual das afirmativas é VERDADEIRA no que se relaciona a estes conjugados?","options":{"A":"O conjugado diagonal mede 12 centímetros e vai da borda inferior da sínfise púbica até o\npromontório.","B":"O conjugado verdadeiro (obstétrico) mede 12 centímetros e vai do promontório até a borda\nsuperior da sínfise púbica.","C":"O conjugado anatômico mede 10 cm e vai do promontório até a borda inferior da sínfise púbica.","D":"O conjugado verdadeiro (obstétrico) mede 11 cm e vai do promontório ao meio da borda superior\nda sínfise púbica."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-109744","number":"109744","sourceNumber":"109744","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Existem 4 tipos de bacia obstétrica que são classificadas de acordo com o formato do\nestreito superior e leva-se em consideração no prognóstico do parto. Qual destas afirmações é\nVERDADEIRA em relação a essas bacias obstétricas?","options":{"A":"A bacia ginecoide: bacia dos macacos, corresponde a 25% dos casos, tem maior chance de\ndistócia no estreito superior.","B":"A bacia androide: bacia masculina, corresponde a 20% dos casos, é o pior tipo de bacia, há\naumento de incidência de obliquas\nposteriores e chance crescente de distócia com a progressão da\napresentação.","C":"A bacia platipeloide: bacia feminina, corresponde a 50% dos casos, tem melhor prognóstico para\no parto vaginal.","D":"A bacia antropoide: bacia achatada, corresponde a 5% dos casos, a insinuação de\nmaneira geral, ocorre na variedade de posição transversa, o prognóstico de parto é bom."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-109973","number":"109973","sourceNumber":"109973","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Na determinação do Índice de Bishop, para indução do parto, quais parâmetros são\navaliados?","options":{"A":"Altura da apresentação, altura uterina, dilatação do colo, consistência do colo e dinâmica\nuterina.","B":"Consistência, espessura, posição e dilatação do colo uterino, e altura da apresentação.","C":"Dinâmica uterina, dilatação do colo e situação fetal.","D":"Consistência, espessura, posição e dilatação do colo uterino, altura da apresentação, e dinâmica\nuterina."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-109788","number":"109788","sourceNumber":"109788","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente de 30 anos, primípara com 3 contrações em 10 minutos há 9 horas, colo\nmedianizado, dilatação de 8 cm, cefálico em ODT, no plano 0 de De Lee há 3 horas, com bossa\nserossanguínea. Diante de tal caso, podemos concluir que, provavelmente,","options":{"A":"o estreito superior da bacia é maior no diâmetro ântero-posterior.","B":"o parto ocorrerá em 3 horas, por via vaginal.","C":"a dilatação total ocorrerá em 6 horas e deve-se aplicar fórceps de Simpsom Brau.","D":"está ocorrendo uma desproporção céfalo-pélvica, por vício pélvico."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-86823","number":"86823","sourceNumber":"86823","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Na mulher, a pelve verdadeira:","options":{"A":"Apresenta o esteito inferior oval;","B":"Apresenta 3 planos definidos: estreito superior, médio e inferior;","C":"Apresenta estreito superior formado por um\nlosango;","D":"É completamente formada por 2 ossos fusionados;","E":"Localiza-se entre as asas ilíacas."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-86850","number":"86850","sourceNumber":"86850","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A ruptura prematura das membranas é mais rigidamente definida como sendo ruptura\nespontânea em qualquer momento antes de:","options":{"A":"Um estágio de viabilidade fetal;","B":"A 32ª semana de gestação;","C":"A 37ª semana de gestação;","D":"Da abertura do colo;","E":"O início do trabalho de parto."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-86854","number":"86854","sourceNumber":"86854","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Globo de segurança de Pinard corresponde:","options":{"A":"Base do instrumento de ausculta fetal;","B":"Vasos mamários;","C":"Contração uterina no trabalho de parto;","D":"Contração uterina no pós parto;","E":"Distensão no segmento uterino durante o trabalho de parto."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-86856","number":"86856","sourceNumber":"86856","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante com DUM 11-06-13, queixando de fortes dores abdominais, tipo cólica, há 2\nhoras e perda líquida há 1 hora. No exame físico encontramos: BCF 120 bpm, bolsa rota e colo\ndilatado para 4 cm. Com isso podemos dizer que:","options":{"A":"Feto a termo, porém bradicárdico;","B":"Feto pré-termo bradicárdico;","C":"Gestante em trabalho de parto prematuro;","D":"Gestante em trabalho de parto a termo;","E":"Amniorrexe prematura."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-86809","number":"86809","sourceNumber":"86809","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Onde se localiza o promontório?","options":{"A":"Entre S1 e L5;","B":"Borda inferior do púbis;","C":"Face anterior de S1;","D":"Face anterior de L5;","E":"Do lado do ilíaco."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-108598","number":"108598","sourceNumber":"108598","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O maior diâmetro da cabeça fetal normal é o:","options":{"A":"Biparietal.","B":"Bitemporal.","C":"Occipitofrontal.","D":"Suboccipitobregmático.","E":"Occipitomentoniano."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-49603","number":"49603","sourceNumber":"49603","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"São considerados fatores de risco para a prematuridade, EXCETO:","options":{"A":"Desnutrição.","B":"Tabagismo.","C":"Amputação do colo uterino.","D":"Obesidade.","E":"Prematuridade prévia."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-49577","number":"49577","sourceNumber":"49577","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Qual o tipo fundamental de bacia que a maioria das mulheres adultas apresenta,\nsegundo a classificação de Caldwell-Moloy?","options":{"A":"Androide.","B":"Platipeloide.","C":"Antropoide.","D":"Ginecoide.","E":"Mista."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-49592","number":"49592","sourceNumber":"49592","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A relação entre o grande eixo do feto e o grande eixo da mãe é chamada de:","options":{"A":"Situação.","B":"Apresentação.","C":"Posição.","D":"Atitude.","E":"Insinuação."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-13117","number":"13117","sourceNumber":"13117","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A manobra que deve ser preferida na assistência ao parto pélvico é a de:","options":{"A":"Pajot.","B":"Rojas.","C":"Bracht.","D":"Mauriceau.","E":"Deventa-Muller."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-13124","number":"13124","sourceNumber":"13124","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Quais os pontos de referência das apresentações cefálicas fletidas e de face?","options":{"A":"Bregma e lâmbda, respectivamente.","B":"Lâmbda e glabela, respectivamente.","C":"Lâmbda e mento, respectivamente.","D":"Bregma e mento, respectivamente.","E":"NDA."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-13125","number":"13125","sourceNumber":"13125","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A bossa serossanguínea (ou ?caput succedaneum?):","options":{"A":"Não respeita a sutura (ultrapassa-a).","B":"Recobre o periósteo.","C":"A e B corretas.","D":"É o mesmo que céfalohematoma.","E":"B e D corretas."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-327277","number":"327277","sourceNumber":"327277","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante, primigesta, realizou exame morfológico cuja cervicometria foi 18mm. Qual\nconduta deve ser adotada conforme evidências científicas?","options":{"A":"Acompanhamento pré-natal","B":"Colocação de Pesário","C":"Progesterona vaginal","D":"Reavaliar em uma semana"},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-298244","number":"298244","sourceNumber":"298244","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente 42 semanas foi a maternidade para a avaliação. Ao exame: colo dilatado para\n1 cm, 50% apagado, medianizado, firme.\nAltura da apresentação -2 de Delee. Qual o índice de\nBishop e a conduta?","options":{"A":"Bishop 8. A maturação cervical não foi completa, considerar a utilização de métodos artificiais\npara se atingir essa maturação.","B":"Bishop 9. A maturação cervical adequada, aguardar trabalho de parto.","C":"Bishop 4. A maturação cervical não foi completa, considerar a utilização de métodos artificiais\npara se atingir essa maturação.","D":"Bishop 3. A maturação cervical adequada, aguardar trabalho de parto."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-298245","number":"298245","sourceNumber":"298245","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Sobre as fases clínicas do trabalho de parto, assinale a alternativa CORRETA.","options":{"A":"A quiescência (fase 1) da contratilidade uterina caracteriza-se por um estado de relativa\nrefratariedade a agentes que determinam contrações miometriais.","B":"A ativação (fase 2) da contratilidade uterina é o próprio trabalho de parto e se divide\nclinicamente\nem três estágios: dilatação, expulsão e\ndequitação.","C":"A estimulação (fase 3) da contratilidade uterina é caracterizada por modificações cervicais e\npela\nda e pela descida do fundo uterino.","D":"A involução (fase 4) contratilidade uterina é marcada pela diminuição da contratilidade uterina,\ncom intuito de facilitar a dequitação."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-286741","number":"286741","sourceNumber":"286741","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante 40 semanas em trabalho de parto e uso de ocitocina venosa 10mUI/min com\n39 semanas. Apresenta desacelerações tardias no\ntraçado de cardiotocografia e atividade uterina\nde 8 contrações em 10 minutos de 50 segundos. Qual a conduta deve ser adotada inicialmente:","options":{"A":"Descontinuar a ocitocina","B":"Indicar cesariana","C":"Iniciar sulfato de magnésio 50 mg","D":"Iniciar terbutalina"},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-286744","number":"286744","sourceNumber":"286744","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O toque vaginal em uma primípara em trabalho de parto evidenciou: colo centralizado,\ndilatação 9 cm, apresentação cefálica,\nsutura sagital mais próxima do pube que do promontório.\n\nPodemos afirmar que o feto está em:","options":{"A":"Assinclitismo posterior.","B":"Variedade de posição OP (Occipitopúbica).","C":"Assinclitismo anterior.","D":"Variedade de posição OS (Occipitossacra)."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-208350","number":"208350","sourceNumber":"208350","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante 37 semanas foi a maternidade com queixa de perda de líquido. Assinale a\nalternativa CORRETA:","options":{"A":"O diagnóstico é dado pelo exame clínico","B":"O diagnóstico é dado pela ultrassonografia","C":"O diagnóstico é dado pelo leucograma","D":"O diagnóstico é dado pelo PH acima de 7,5"},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-208362","number":"208362","sourceNumber":"208362","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Você está de plantão quando é chamado para atender a uma paciente levada pelos\nvizinhos com queixa de contração há mais ou\nmenos cinco horas. Refere que a contração ficou\nmais frequente na última hora. Primigesta, com 24 anos de idade. Trouxe o cartão de pré-natal\ninformando que realizou 10 consultas, tomou todas as vacinas e realizou todos os exames de\nrotina. Não houve intercorrência durante a gestação. Idade Gestacional pela Data da Última\nMenstruação: 37 semanas 2/7 e Idade Gestacional pela primeira USG realizado na 8ª semana: 38\nsemanas 2/7. Nas apresentações cefálicas, na maioria das vezes, o mento se aproxima do externo,\no que constitui apresentação?","options":{"A":"Defletida de 1º grau.","B":"Defletida de 2º grau.","C":"Defletida de 3º grau.","D":"Cefálica fletida."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-208367","number":"208367","sourceNumber":"208367","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A distocia biacromial é uma situação grave nas apresentações cefálicas. São fatores de\nrisco para essa distocia, EXCETO:","options":{"A":"Doença hipertensiva específica da gestação","B":"Obesidade","C":"Período expulsivo prolongado","D":"Distocia do biacromial prévia"},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-176060","number":"176060","sourceNumber":"176060","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A orientação do feto em relação à pelve materna é descrita em termos de situação,\napresentação, posição e atitude fetal. Assinale a alternativa INCORRETA acerca disso:","options":{"A":"Os fatores predisponentes às situações transversais consistem na multiparidade, placenta\nanterior, polidrâmnio e anomalias uterinas.","B":"A primeira manobra de Leopold é realizada pinçando com o polegar e os dedos de uma das\nmãos a parte interior do abdome materno\nexatamente acima da sínfise púbica. Quando a parte fetal\napresentada não se encontra encaixada, percebe-se massa móvel, geralmente a cabeça.","C":"A incidência de apresentação pélvica diminui com a idade gestacional, sendo de\naproximadamente 25% com 28 semanas, 11% com 32 semanas e apenas 3% no termo.","D":"O feto penetra na pelve na posição Occipto-Esquerdo-Transversa (OET) em 40% dos trabalhos\nde parto e na posição\nOccipto-Direito-Transversa (ODT) em 20%."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-176072","number":"176072","sourceNumber":"176072","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Adolescente, 14 anos, primigesta com 38 semanas e 3 dias de gestação deu entrada\nna Maternidade Balbina Mestrinho com queixa de\ndor há 12 horas com piora há 4 horas. Dinâmica\nuterina presente, 3 contrações em 10 minutos, movimentos fetais presentes, AU = 35 cm, AF = 146\nbpm, rítmico. Bolsa íntegra. Ao toque: colo fino, centralizado, pérvio para 8,0 cm, +1 de De Lee,\nAF\n\n= 141 bpm, rítmico. Em relação aos diâmetros fetais no termo, qual o de maior extensão?","options":{"A":"Occipitomentoniano.","B":"Suboccipitobregmático.","C":"Submentobregmático.","D":"Occipitofrontal."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-151972","number":"151972","sourceNumber":"151972","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Quanto a maturação cervical é CORRETO afirmar: I. Bioquimicamente, a maturação\ncervical é um processo complexo no qual estão\nenvolvidos vários tipos de glicosaminoglicanas,\ncomo heparina, sulfato de heparan, dermatan e sulfato de condroitina, e outras substâncias que\nagem na degradação do colágeno, como proteases e colagenases. II. Uma das formas de\nquantificar a maturação cervical é a utilização de índices como o descrito por Bishop em 1964. III.\nVários métodos são descritos como capazes de promover a maturação cervical, entre eles:\nHialuronidase, a relaxina, óxido nitrico, misoprostol, laminárias, descolamento digital de membrana\novulares e cateter-balão de Foley transcervical. Assinale a alternativa CORRETA:","options":{"A":"Somente as afirmativas I e III estão corretas.","B":"Somente as afirmativas II e III estão corretas.","C":"Somente a afirmativa III está correta.","D":"Todas as afirmativas estão corretas."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-129731","number":"129731","sourceNumber":"129731","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Jovem de 20 anos, IG 0P 0A, 40 semanas de gestação, confirmada por DUM a US\nprecoce 7 semanas, deu entrada na\nMaternidade Ana Braga com PA: 120 x 80 mmHg, dinâmica\nuterina: 2/10 colo pérvio para 5,0 cm com bolsa íntegra. Foi internada em trabalho de parto. Quanto\nao partograma assinale a alternativa CORRETA:","options":{"A":"O partograma é a representação gráfica do trabalho de parto que permite acompanhar sua\nevolução, documentar, diagnosticar alterações e orientar tomada de condutas para correção de\ndesvios.","B":"No trabalho de parto fisiológico, a dilatação do cilco deve seguir uma curva hiperbólica.","C":"A parte principal do partograma corresponde ao registro da dilatação do colo e da frequência\ncardíaca fetal.","D":"A fase de latência prolongada é definida pela duração abaixo de 18 horas."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-129748","number":"129748","sourceNumber":"129748","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Quanto ao mecanismo de parto é INCORRETO afirmar:","options":{"A":"As apresentações cefálicas fletidas com variedade de posição anterior, além de mais comuns,\nsão as que apresentam melhores\ncaracterísticas para a progressão dos mecanismos de parto.","B":"A variedade de posição complementa a orientação espacial ao relacionar um ponto de referência\nda apresentação fetal com um ponto de referência\nósseo da bacia materna, levando-se em\nconsideração as faces anterior, posterior ou lateral da gestante.","C":"Chama-se assinclitismo posterior quando a sutura sagital se aproxima da pube e o parietal\nposterior desce até ultrapassar o promontório materno.","D":"Em jovens primíparas, a cabeça fetal mostra-se mais frenquentemente em assinclilitismo\nanterior, uma vez que as contrações uterinas\ne a contenção da prensa abdominal levam o corpo do\nfeto em direção anterior."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-103861","number":"103861","sourceNumber":"103861","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O parto pré-termo tem importantes consequências para os seres humanos, sendo a\nmaior causa de morbi-mortalidade neonatal. Assinale a alternativa INCORRETA:","options":{"A":"Alterações genéticas e ambientais podem levar ao nascimento pré-termo.","B":"A rutura espontânea das membranas fetais tem como uma das principais causas o fator\ninfeccioso.","C":"Alguns micro-organismos como Gardnerella vaginalis, Mycopasma hominis e Ureaplasma\nurealyticum são mais comumente detectados no líquido amniótico.","D":"O trabalho de parto pré-termo com membranas rôtas são a causa mais comum de parto\npré-termo, e representam 50% dos nascimentos."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-87395","number":"87395","sourceNumber":"87395","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O tríplice gradiente descendente que ocorre na contração uterina fisiológica é:","options":{"A":"Predomínio na região fúndica e cornual dos marca-passos que originam o estímulo contrátil.","B":"Responsável pela contração uterina que se inicia da região ístmica em direção ao fundo.","C":"Formado pela contratilidade simultânea das fibras miometriais.","D":"Ausência de dilatação cervical.","E":"Presença de contrações uterinas atônicas vigorosas que se iniciam no marca-passo uterino, que\nse localiza no fundo uterino."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-87411","number":"87411","sourceNumber":"87411","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Cláudia, 36 semanas. após o parto teve uma inversão uterina. A primeira medida a ser\ninstituida para o tratamento da inversão uterina aguda além da correção da hipovolemia é:","options":{"A":"Manobra de Cristeler.","B":"Manobra de Crede.","C":"Manobra de Taxe.","D":"Manobra de Fitz Hugz Cutz.","E":"Manobra de Huntigton."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-81959","number":"81959","sourceNumber":"81959","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Ao examinar uma parturiente cujo feto se encontra em situação longitudinal,\napresentação cefálica fletida, posição direita e\no ponto de referência fetal voltado para a eminência\niliopectínea, o médico pode tocar o lambda na posição de:","options":{"A":"2 h","B":"3 h","C":"4 h","D":"8 h","E":"10 h"},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-81016","number":"81016","sourceNumber":"81016","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente em trabalho de parto acabou de ser examinada pelo residente de obstetrícia.\nAo ser perguntado sobre qual plano o feto se\nencontrava, ele respondeu: naquele plano localizado\nao nível das espinhas isquiáticas. A qual plano o residente se referia?","options":{"A":"Primeiro plano de DeLee e plano zero de Hodge.","B":"Plano zero de DeLee e segundo plano de Hodge.","C":"Terceiro plano de Hodge e terceiro plano de DeLee.","D":"Plano zero de DeLee e terceiro plano de Hodge.","E":"Segundo plano de DeLee e plano zero de Hodge."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-81029","number":"81029","sourceNumber":"81029","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Maria, 24 anos, G1 P0 está em trabalho de parto com o feto em apresentação cefálica\nfletida. Nessa paciente, quando poderemos dizer que já ocorreu a insinuação?","options":{"A":"Quando o diâmetro Biparietal ultrapassa o estreito médio.","B":"O vértice da apresentação atinge o plano das espinhas ciáticas.","C":"O ponto de maior declive da apresentação atinge o períneo.","D":"O maior diâmetro da cabeça atinge o plano zero de De Lee.","E":"Quando ocorrer o Hipomóclio."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-80993","number":"80993","sourceNumber":"80993","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente multipara, com 35 semanas de gestação é admitida na maternidade com\nhistória de perda líquida. Ao exame especular foi visualizada pequena quantidade de líquido em\nfundo de saco vaginal posterior. O achado complementar que melhor pode confirmar esse\ndiagnóstico é:","options":{"A":"Centralização fetal","B":"pH vaginal abaixo de 6","C":"Leucocitose e desvio","D":"Cristalização arboriforme do muco cervical","E":"Ultrassonografia transvaginal"},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-60864","number":"60864","sourceNumber":"60864","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"São fatores que predispõem às situações transversas, EXCETO:","options":{"A":"Polidramnia","B":"Oligodramnia","C":"Multiparidade","D":"Placenta anterior","E":"Anomalias uterinas"},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-60867","number":"60867","sourceNumber":"60867","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Fazem parte do mecanismo do trabalho de parto, EXCETO:","options":{"A":"Flexão","B":"Extensão","C":"Dilatação","D":"Insinuação","E":"Rotação Interna"},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-61532","number":"61532","sourceNumber":"61532","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Assinale a alternativa CORRETA:","options":{"A":"Denomina-se apresentação a relação entre os grandes eixos fetais e uterino.","B":"Há 4 tipos fundamentais de bacia: ginecoide (feminina, 80%), androide (dos macacos, 1%),\nantropoide (masculina, 10%) e platipeloide (achatada, 9%).","C":"Os planos da Hodge são 4: o primeiro corresponde à borda inferior do pube, o segundo passa\npela borda superior do pube e pelo promontório, o terceiro é traçado nas espinhas ciáticas e o\nquarto parte da ponta do cóccix e confunde-se com o assoalho pélvico.","D":"Os diâmetros mais importantes de interesse para o parto são: occiptofrontal, supraocciptofrontal,\nsupraocciptomentoniano, supraocciptobregmático, biparietal e biacromial.","E":"Para expressar a altura da apresentação, ou seja, sua distância ao estreito superior, é útil o\ncritério de De Lee: considerar o diâmetro biespinha ciática como plano de referência zero. Acima\ndesse plano a altura será negativa em centímetros e abaixo, positiva em centímetros."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-60907","number":"60907","sourceNumber":"60907","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"São fatores implicados na ruptura prematura pré-termo de membranas, EXCETO:","options":{"A":"Tabagismo","B":"Obesidade materna","C":"Infecção intra-amniótica","D":"Baixo índice de massa corporal","E":"Baixa condição socioeconômica"},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-60909","number":"60909","sourceNumber":"60909","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Na condução do parto pélvico, a manobra que auxilia no desprendimento da cabeça\nderradeira é:","options":{"A":"Pajot","B":"Rojas","C":"Bracht","D":"Pinard","E":"Mauriceau"},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-61573","number":"61573","sourceNumber":"61573","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"São contraindicações para a indução do parto:","options":{"A":"Desproporção cefalopélvica, fetos acima de 3500 gramas, dilatação de 3 cm e índice Bishop\nigual a 6.","B":"Desproporção cefalopélvica, gestações múltiplas, apresentações anômalas, grande\nmultiparidade.","C":"Placenta prévia, cabeça insinuada, induções anteriores, fetos acima de 3500 gramas.","D":"Placenta prévia, óbito fetal intrauterino, Desproporção de celafopélvica e índice de Bishop igual\na 6.","E":"Índice de Bishop igual a 6, fetos acima de 3500 gramas, dilatação de 3 cm e grande\nmultiparidade."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-61571","number":"61571","sourceNumber":"61571","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"São tempos do mecanismo do parto (em ordem de acontecimento):","options":{"A":"Insinuação, Descida e Desprendimento.","B":"Desprendimento, Insinuação e Descida.","C":"Insinuação, Desprendimento e Descida.","D":"Desprendimento, Descida e Insinuação.","E":"Descida, Desprendimento e Insinuação."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-34151","number":"34151","sourceNumber":"34151","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"São drogas utilizadas no trabalho de parto prematuro, EXCETO:","options":{"A":"Terbutalina.","B":"Ritodrina.","C":"Isoxsuprina.","D":"Salbutamol.","E":"Ácido acetilsalicílico."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-34107","number":"34107","sourceNumber":"34107","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"De acordo com este partograma (VER IMAGEM), posso afirmar que:","options":{"A":"Houve uma parada de progressão.","B":"Se caracteriza como parto taquitócito.","C":"Não tem risco para o feto.","D":"É um partograma típico de amniorrexe prematura.","E":"Se caracteriza como parto eutócito."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":["question_bank/media/medcurso/medcurso-obstetricia-obs-2/34107.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-26486","number":"26486","sourceNumber":"26486","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A parte do corpo de concepto que está em contato com o estreito superior da bacia\nchama-se:","options":{"A":"Posicionamento","B":"Atitude","C":"Linha de orientação","D":"Apresentação","E":"Hipomóclio"},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-26489","number":"26489","sourceNumber":"26489","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O 2º estágio do trabalho de parto começa:","options":{"A":"com contrações ritmicas e frequentes.","B":"separação e expulsão da placenta.","C":"desprendimento da placenta.","D":"dilatação completa da cérvix.","E":"desprendimento da cabeça do feto."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-26503","number":"26503","sourceNumber":"26503","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Assinale a afirmativa correta:","options":{"A":"O diagnóstico diferencial de oligodramnia no segundo trimestre far-se-a com rotura pré-matura\nde membranas, patologia renal fetal, patologia\nesofageana e insuficiência placentária grave.","B":"O diagnóstico da rotura prematura de membranas ocorre clinicamente em mais de 90% dos\ncasos. O ultrassom revela oligodramnia em 80% das vezes.","C":"Nos casos de amniorrexe prematura, a conduta após 30 semanas é indução do parto.","D":"A rotura prematura das membranas tem fraca correlação com deslocamento pré maturo de\nplacenta.","E":"O óbito perinatal ocorre mais frequentemente devido a hipóxia fetal."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-26645","number":"26645","sourceNumber":"26645","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"De acordo com este partograma posso afirmar que: (VER IMAGEM)","options":{"A":"Foi um parto distócico e o desprendimento deu-se na situação OP","B":"Foi um parto taquitócito e o feto encontrava-se na posição ODA","C":"Foi um parto com distócia de rotação","D":"Foi um parto eutócico e o feto encontrava-se numa variedade de posição indiferente","E":"Foi um parto eutócico e o feto encontrava-se na variedade de posição OEA"},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":["question_bank/media/medcurso/medcurso-obstetricia-obs-2/26645.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-26646","number":"26646","sourceNumber":"26646","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Fazem parte dos períodos clínicos do parto: I. Insinuação II. Descida III. Rotação\ninterna IV. Rotação externa V. Dequitação. Está CORRETO apenas o contido em:","options":{"A":"I, II, III e IV","B":"I, II, III e V","C":"I, II, IV e V","D":"I, II e V","E":"I e IV"},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-26649","number":"26649","sourceNumber":"26649","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em relação à figura abaixo os diâmetros submento bregmático, occípito frontal e\nsub-ocípto bregmático correspondem respectivamente a que apresentações: (VER IMAGEM)","options":{"A":"Face, bregma e occipício","B":"Fronte, face e bregma","C":"Bregma, face e occipício","D":"Face, fronte e bregma","E":"Face, occipício, bregma"},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":["question_bank/media/medcurso/medcurso-obstetricia-obs-2/26649.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-26652","number":"26652","sourceNumber":"26652","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A identificação anatômica ao exame pélvico das espinhas isquiáticas têm grande\nimportância nas situações abaixo, EXCETO:","options":{"A":"É o ponto de referência para se classificar os graus de distopia","B":"É o ponto de fixação do ligamento sacro espinhal","C":"É o ponto de referência no bloqueio de nervo pudendo","D":"É o ponto de referência na suspensão vaginal do ligamento sacroespinhal","E":"É o ponto de referência no trabalho de parto para se avaliar a altura da apresentação fetal"},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-7523","number":"7523","sourceNumber":"7523","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"São indicações absolutas de cesárea, exceto:","options":{"A":"cesárea anterior.","B":"placenta prévia total.","C":"desproporção céfalo-pélvica.","D":"apresentação córmica.","E":"sofrimento fetal agudo."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-294475","number":"294475","sourceNumber":"294475","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em acompanhamento de trabalho de parto a termo, uma parturiente encontra-se com\ntrês contrações uterinas a cada 10 minutos. A\nvitalidade fetal está boa e a dilatação cervical é de\n5cm. Após algum tempo, constata-se colo complementar dilatado, bolsa rota, 5 contrações uterinas\na cada 10 minutos, batimentos cardiofetais em 80bpm. A apresentação fetal encontra-se em -3,\nvariedade de posição Occipto púbica. Considerando que o parto será vaginal, indique em que\nmomento deve-se realizar a analgesia regional.","options":{"A":"Quando a paciente solicitar, independente da fase do parto.","B":"A partir de 5 cm de dilatação, após a fase de latência do trabalho de parto.","C":"Após serem oferecidas técnicas de analgesia não farmacológicas disponíveis, sem resultado\neficaz.","D":"Quando as dores estiverem impedindo a colaboração da parturiente."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-294476","number":"294476","sourceNumber":"294476","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em acompanhamento de trabalho de parto a termo, uma parturiente encontra-se com\ntrês contrações uterinas a cada 10 minutos. A\nvitalidade fetal está boa e a dilatação cervical é de\n5cm. Após algum tempo, constata-se colo complementar dilatado, bolsa rota, 5 contrações uterinas\na cada 10 minutos, batimentos cardiofetais em 80bpm. A apresentação fetal encontra-se em -3,\nvariedade de posição Occipto púbica. Indique o momento no qual o partograma deve ser aberto.","options":{"A":"No início do período de dilatação.","B":"No início do período expulsivo.","C":"Na fase ativa do trabalho de parto.","D":"Na admissão da parturiente no centro obstétrico."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-294477","number":"294477","sourceNumber":"294477","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em acompanhamento de trabalho de parto a termo, uma parturiente encontra-se com\ntrês contrações uterinas a cada 10 minutos. A\nvitalidade fetal está boa e a dilatação cervical é de\n5cm. Após algum tempo, constata-se colo complementar dilatado, bolsa rota, 5 contrações uterinas\na cada 10 minutos, batimentos cardiofetais em 80bpm. A apresentação fetal encontra-se em -3,\nvariedade de posição Occipto púbica. Considerando os dados do caso, indique a melhor conduta\nobstétrica.","options":{"A":"Parto cesariano de urgência.","B":"Fórceps ou vácuo-extrator.","C":"Manobra de Kristeler.","D":"Estimular o puxo e realizar episiotomia."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-62804","number":"62804","sourceNumber":"62804","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primigesta, com 40 semanas gestacional, encontra-se na fase ativa do trabalho de\nparto. Apresenta três contrações/minuto, colo\nuterino 75% apagado, dilatado 7 cm. Bolsa amniótica\nrota com líquido claro com grumos. Apresentação cefálica no plano +2 de De Lee. Cardiotocografia\nbasal categoria 1. Nesse momento, a conduta é:","options":{"A":"realizar cesariana imediata","B":"realizar amnioscopia","C":"conduzir o trabalho de parto","D":"iniciar analgesia de parto imediata","E":"aplicar fórcipe alto"},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-49303","number":"49303","sourceNumber":"49303","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Secundigesta, 40 semanas de gestação, com parto natural anterior, encontra-se com 2\ncm de dilatação cervical, 50% de\napagamento, uma contração em 10 minutos, bolsa íntegra e BCF:\n144 bpm. A conduta do obstetra, nesse caso, é:","options":{"A":"solicitar internação e imediato acompanhamento com o partograma.","B":"realizar cesariana por se tratar de uma parada secundária da dilatação.","C":"realizar amniotomia.","D":"reavaliar, após duas horas, para confirmar início do trabalho de parto.","E":"recomendar repouso em domicílio e retorno com 42 semanas de gestação."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-49313","number":"49313","sourceNumber":"49313","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Puérpera evoluiu com hemorragia pós-parto secundária à atonia uterina na última\ngestação. A medida profilática recomendada pela OMS para casos como esse é:","options":{"A":"ocitocina 10 UI por via intramuscular, no 3º período.","B":"misoprostol 400 mg por via oral ou retal, no 3º período.","C":"metilergonovina 0,2 mg por via intramuscular, no 3º período.","D":"massagem do fundo uterino, no 2º período.","E":"ocitocina 5 U em bolus, por via endovenosa, no 2º período."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-34928","number":"34928","sourceNumber":"34928","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante primigesta, com 36 semanas de gestação, assintomática, apresenta rotura\nprematura de membranas confirmada pelo\nexame especular realizado durante consulta pré-natal. A\nmelhor conduta é:","options":{"A":"internar para indução do trabalho de parto.","B":"solicitar ultrassom e retorno com uma semana.","C":"internar para acompanhamento na enfermaria.","D":"solicitar leucograma, VHS e PCR e retorno com uma semana.","E":"solicitar ultrassonografia com Doppler, imediatamente."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-11145","number":"11145","sourceNumber":"11145","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primigesta, na 30ª semana procura a maternidade com queixa de perda de líquido pela\nvagina, há uma semana, e desconforto uterino há 12 horas. Temperatura axilar materna de 38,1ºC,\npulso: 105 bpm, a ultrassonografia mostrou ILA de 3,2 cm, o leucograma evidenciou 17.200\nleucócitos/mm³ e o teste de papel de nitrazina, positivo. Com esse quadro, além da\nantibioticoterapia, deve-se:","options":{"A":"realizar cesariana.","B":"iniciar indução do parto.","C":"administrar uterolítico + corticosteroide.","D":"adotar conduta expectante.","E":"administrar antibiótico + uterolítico."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-13317","number":"13317","sourceNumber":"13317","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Mulher, 30 anos de idade, G3P2A0, com 40 semanas de gestação, progrediu no\ntrabalho de parto de 6 cm para 7 cm de\ndilatação cervical em 2 horas. Ao toque: ODP em plano 0\nde DeLee, que persiste desde o início do trabalho de parto. Dos seguintes episódios, o que melhor\ndescreve o partograma dessa paciente é:","options":{"A":"fase latente prolongada","B":"fase ativa acelerada","C":"parada de fase ativa","D":"fase ativa protraída","E":"trabalho de parto normal"},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-13319","number":"13319","sourceNumber":"13319","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Mulher, 30 anos de idade, G3P2A0, com 40 semanas de gestação, progrediu no\ntrabalho de parto de 6 cm para 7 cm de\ndilatação cervical em 2 horas. Ao toque: ODP em plano 0\nde DeLee, que persiste desde o início do trabalho de parto. O tipo de pelve que predispõe à\nposição occipital posterior persistente é a:","options":{"A":"androide","B":"antropoide","C":"ginecoide","D":"platipeloide","E":"ginecoplatipeloide"},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-13321","number":"13321","sourceNumber":"13321","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Mulher, 30 anos de idade, G3P2A0, com 40 semanas de gestação, progrediu no\ntrabalho de parto de 6 cm para 7 cm de\ndilatação cervical em 2 horas. Ao toque: ODP em plano 0\nde DeLee, que persiste desde o início do trabalho de parto. A variedade de posição descrita refere\nà:","options":{"A":"apresentação córmica, situação transversa e posição direita","B":"apresentação pélvica, situação longitudinal e posição esquerda","C":"apresentação cefálica defletida de 1° grau, situação longitudinal e posição direita","D":"apresentação cefálica fletida, situação longitudinal e posição direita","E":"apresentação cefálica fletida, situação oblíqua e posição posterior"},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-281892","number":"281892","sourceNumber":"281892","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em uma cesariana, tradicionalmente não é seccionado:","options":{"A":"Aponeurose abdominal.","B":"Músculo reto-abdominal.","C":"Peritônio parietal.","D":"Peritônio visceral."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-181187","number":"181187","sourceNumber":"181187","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante a termo dá entrada no PS Obstétrico em trabalho de parto, com dilatação\ntotal, apresentação pélvica, exteriorizando membros\ninferiores até a altura dos joelhos fetais.\n\nLevada ao centro obstétrico é realizada a manobra de Mauriceau, que consiste na liberação de:","options":{"A":"Tronco fetal.","B":"Pólo cefálico fetal.","C":"Quadril fetal.","D":"Ombro anterior fetal."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-157590","number":"157590","sourceNumber":"157590","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Dos exames listados abaixo, assinale aquele que representa o melhor método\npropedêutico para avaliar maturidade pulmonar fetal em gestação complicada pelo diabetes.","options":{"A":"Teste de Clements.","B":"Relação lecitina/esfingomielina no líquido amniótico.","C":"Fosfatidilglicerol no líquido amniótico.","D":"Dosagem de alfafetoproteína no líquido amniótico."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-157611","number":"157611","sourceNumber":"157611","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente em trabalho de parto com feto em apresentação cefálica fletida plano +1 de\nDe Lee, variedade ODT (occipito direita\ntransversa). Para que o parto evolua de forma satisfatória,\nsem intercorrências, o sentido de rotação, a quantidade em graus e a posição final serão,\nRESPECTIVAMENTE:","options":{"A":"Anti-horário / 45 graus / OP (occipito púbica).","B":"Horário / 90 graus / OP (occipito púbica).","C":"Anti-horário / 45 graus / OS (occipito sacra).","D":"Anti-horário / 90 graus / OP (occipito púbica)."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-157697","number":"157697","sourceNumber":"157697","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante em trabalho de parto, ao toque, verifica-se que o vértice do polo cefálico\nencontra-se ao nível das espinhas ciáticas. Isso significa que houve:","options":{"A":"Deflexão.","B":"Insinuação.","C":"Rotação interna.","D":"Rotação externa."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-157651","number":"157651","sourceNumber":"157651","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em relação à contratilidade uterina, assinale a alternativa CORRETA.","options":{"A":"O tríplice gradiente descendente está presente durante o transcurso de todo o período\ngestacional.","B":"Durante as contrações uterinas, há diminuição significativa do retorno venoso, provocando\nhipotensão materna.","C":"O decúbito lateral esquerdo não modifica as características da contratilidade uterina.","D":"O número de receptores de ocitocina aumenta à medida que a gravidez se aproxima do termo."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-139740","number":"139740","sourceNumber":"139740","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Assinale a alternativa que apresenta a substância que NÃO inibe a contratilidade\nuterina.","options":{"A":"Ritodrina.","B":"Atropina.","C":"Salbutamol.","D":"Indometacina."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-134678","number":"134678","sourceNumber":"134678","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente 20 anos, G1P0, com 33 semanas de gestação, comparece no PS com queixa\nde perda de líquido que escorre pelas pernas\nhá 2 horas atrás, nega contrações refere boa\nmovimentação fetal. Diante de tal caso, qual alternativa abaixo não deve ser realizada como\nconduta?","options":{"A":"Exame especular.","B":"Ultrassonografia.","C":"Toque vaginal.","D":"Exame de lâmina a fresco."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-134719","number":"134719","sourceNumber":"134719","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Na assistência ao parto normal, o partograma deve ser iniciado:","options":{"A":"No momento em que o parto atingir o 2º período.","B":"Com, pelo menos, 3 cm de dilatação e 3 a 5 contrações/10 min.","C":"Na fase de latência.","D":"Na fase pélvica."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-111864","number":"111864","sourceNumber":"111864","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A dose terapêutica para indução do parto com ocitocina é de + ou ? 1,0 mUI/minuto.\nSabendo-se que uma ampola de ocitocina tem 5UI, em 1 litro de soro fisiológico, o gotejamento\ninicial por minuto deve ser de:","options":{"A":"4 gotas/min.","B":"5 gotas/min.","C":"6 gotas/min.","D":"7 gotas/min."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-111883","number":"111883","sourceNumber":"111883","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Indica-se cesárea eletiva nos casos abaixo, EXCETO:","options":{"A":"condiloma de colo e gravidez de termo.","B":"herpes genital agudo e gravidez de termo.","C":"HIV (+) com carga viral desconhecida e gestação de termo.","D":"descolamento prematuro da placenta com gestação de 33 semanas e feto vivo."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-111894","number":"111894","sourceNumber":"111894","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Na assistência ao parto normal, o partograma deve ser iniciado:","options":{"A":"no momento em que o parto atingir o 2º período.","B":"com pelo menos 3 cm de dilatação e 3 a 5 contrações/10 min.","C":"na fase de latência.","D":"na fase pélvica."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-111911","number":"111911","sourceNumber":"111911","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente primigesta em trabalho de parto, colo dilatado 8 cm, OET\n\n(Occípito-Esquerda-Transversa), para que o parto evolua normalmente com expulsão em OP\n(Occípito-Púbica), seria ideal rotação de:","options":{"A":"45 graus no sentido horário.","B":"90 graus no sentido anti-horário.","C":"45 graus no sentido anti-horário.","D":"135 graus no sentido horário."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-350843","number":"350843","sourceNumber":"350843","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O estudo da estática fetal é de suma importância para analisar as relações do produto\nconceptual e seus respectivos pontos de referência ao insinuarem-se pelo estreito superior, com a\nbacia e com o útero, dando-nos dados essenciais para o bom entendimento e acompanhamento do\ntrabalho de parto. A partir da figura, assinale a alternativa que descreve corretamente a situação,\napresentação, variedade de posição e posição fetal.","options":{"A":"Situação longitudinal, apresentação cefálica (fletida), occipto-direta anterior (O.D.A.) e dorso\nà\ndireita.","B":"Situação longitudinal, apresentação cefálica de bregma (defletida de 1º grau),\nbregma-direita-anterior (B.D.A.) e dorso à esquerda.","C":"Situação longitudinal, apresentação cefálica de fronte (defletida de 2º grau),\nnaso-direita-anterior\n(N.D.A.) e dorso à esquerda.","D":"Situação longitudinal, apresentação cefálica de face (defletida de 3º grau),\nmento-esquerda-anterior (M.E.A.) e dorso à esquerda."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-350841","number":"350841","sourceNumber":"350841","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente primigesta no curso das 38 semanas de gestação com altura uterina de 41\ncm, em assistência ao trabalho de parto, no\nperíodo expulsivo. Após desprendimento do polo\ncefálico e subsequente rotação externa, não se obteve sucesso no desprendimento do ombro\nanterior fetal. Assinale a alternativa que descreve corretamente fatores de risco, manejo adequado\ne complicações do quadro acima descrito, respectivamente.","options":{"A":"Hipertiroidismo e Pós Datismo; Manobras de Bracht e Rubin II; Fraturas fetais e Pneumotórax.","B":"Hipertensão gestacional e Obesidade; Manobras de Pajot e Rubin I; Lesão de plexo braquial e\nÓbito fetal.","C":"Macrossomia fetal e Diabetes descompensada; Manobras de Retirada do braço posterior e\nWoods; Lacerações perineais e Fístulas reto-vaginais.","D":"Diabetes descompensada e Rotura Ante-Parto das Membranas Ovulares; Manobras de Mc\nRoberts e Woods; Hemorragia Pós-Parto e Restrição do crescimento fetal."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-350838","number":"350838","sourceNumber":"350838","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente de 33 anos, secundigesta com um parto vaginal prévio, pré-natal de risco\nhabitual na Unidade Básica de Saúde, foi\nadmitida no centro obstétrico de maternidade de atenção\nsecundária com 39 semanas de idade gestacional, feto em apresentação cefálica e no plano zero\nde De Lee, colo apagado e pérvio para 7 cm, bolsa das águas íntegras, 03 contrações de 50\nsegundos em 10 minutos, pressão arterial de 120x70mmHg. Quais informações você vai fornecer\nsobre as rotinas para essa paciente no primeiro, segundo e terceiro período do parto, prezando\npela segurança e bem estar do binômio materno fetal?","options":{"A":"Ausculta fetal intermitente a cada 30 minutos no primeiro período do parto e a cada 15 minutos\nno segundo período do parto e delivramento\nativo da placenta com uso de uterotônico e tração\ncontrolada do cordão, no terceiro período do parto.","B":"Cardiotocografia no primeiro período do parto ao ser admitida, ausculta fetal intermitente a cada\n05 minutos no período expulsivo e delivramento\nativo da placenta com uso de uterotônico e tração\ncontrolada do cordão, no terceiro período do parto.","C":"Ausculta fetal intermitente a cada 30 minutos no primeiro período do parto e a cada 05 minutos\nno segundo período do parto e delivramento\nfisiológico da placenta com clampeamento do cordão\napós parar a pulsação do mesmo e expulsão da placenta por esforço materno, no terceiro período\ndo parto.","D":"Cardiotocografia no primeiro período do parto ao ser admitida, ausculta fetal intermitente a cada\n15 minutos no período expulsivo e delivramento\nfisiológico da placenta com clampeamento do\ncordão após parar a pulsação do mesmo e expulsão da placenta por esforço materno, no terceiro\nperíodo do parto."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-350837","number":"350837","sourceNumber":"350837","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"BSF, 31 anos, primigesta, IG 41 sem e 4 dias (calculada por ultrassom de primeiro\ntrimestre), procura a emergência por orientação de seu médico de pré-natal. PA 110x70 mmhg,\nfundo uterino 37cm, atividade uterina ausente, apresentação cefálica, índice de Bishop = 7.\n\nCardiotocografia anteparto na admissão reativa. Considerando o quadro clínico acima, podemos\nafirmar:","options":{"A":"Trata-se de uma gestação pós-termo, devendo ser indicada a resolução por via obstétrica.","B":"A indução eletiva, neste caso, reduz a mortalidade perinatal quando comparada à conduta\nexpectante.","C":"Deve-se administrar Misoprostol 25mcg a cada 6 h, por via vaginal, até o desencadeamento do\ntrabalho de parto.","D":"A realização de ultrassonografia obstétrica é obrigatória, para avaliação do peso fetal e maior\nbolsão de líquido amniótico."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-350836","number":"350836","sourceNumber":"350836","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primigesta, 35 semanas, gestação gemelar e trabalho de parto prematuro em estágio\navançado (7 cm de dilatação), tem sua\ncesárea indicada por apresentação pélvica incompleta modo\nde pés do feto que está insinuado no estreito médio da pequena pelve. USG obstétrica há 1\nsemana, revelou mioma uterino de 8,0 x 5,5 x 7,0 cm em parede uterina anterior na transição corpo\ncolo. Sobre os cuidados durante a cesárea, desta paciente, podemos afirmar:","options":{"A":"A incisão uterina clássica deve ser considerada, apesar da maior perda sanguínea durante a\ncesárea.","B":"A remoção manual da placenta é o modo de escolha do secundamento, por propiciar menor\nperca sanguínea e preservação do hematócrito\nmaterno.","C":"A incisão uterina transversal segmentar deve ser realizada por propiciar a possibilidade de\ntentativa de parto vaginal em trabalho de parto subsequente.","D":"A administração de ácido tranexâmico deve ser evitada, pelos fatores de risco aumentado para\ntromboembolismo que a paciente apresenta."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-321357","number":"321357","sourceNumber":"321357","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primigesta de 26 anos, idade gestacional de 38 semanas e 2 dias, pressão arterial 120\nx 80 mmHg, peso 85 kg, pré-natal sem\nintercorrências, solicita a seu obstetra a resolução da\ngestação via abdominal. Considerando o enunciado acima, qual a afirmativa correta em relação a\ncesárea a pedido?","options":{"A":"Instituir o contato pele a pele e o estímulo à amamentação na sala cirúrgica e iniciar dieta\nlíquida\n10 h após a cesárea.","B":"Orientar deambulação precoce a partir de 4 h após o procedimento e manter puérpera e\nrecém-nascido em alojamento conjunto.","C":"Realizar a raspagem de pelos e administrar Cefazolina 1,0 g endovenosa, idealmente 30\nminutos antes da incisão cirúrgica na pele.","D":"Realizar orientação antecipada acerca do procedimento a ser executado, solicitar a assinatura\ndo termo de consentimento e resolver a gestação\nno dia seguinte."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-321359","number":"321359","sourceNumber":"321359","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"S.P.M.S, 29 anos, G2P1(vaginal)A0, idade gestacional 37 semanas, procura a\nemergência com quadro de rotura anteparto das\nmembranas ovulares (RAMO). Ao exame,\nobserva-se líquido amniótico claro escoando pelo orifício cervical externo. Toque vaginal apresenta\ncolo posterior, longo, amolecido, dilatado 2 cm, apresentação cefálica -1 de Lee. Identifique a\nmelhor conduta a ser tomada.","options":{"A":"Após comprovar bem-estar fetal por meio de cardiotocografia e estimar que o peso fetal\nencontre-se dentro do esperado para a idade\ngestacional, deve-se iniciar indução farmacológica do\ntrabalho de parto com uso de ocitocina, uma vez que o índice de Bishop é menor que 7.","B":"Após comprovar bem-estar fetal por meio de cardiotocografia e estimar que o peso fetal\nencontre-se dentro do esperado para a idade\ngestacional, deve-se iniciar indução farrmacológica\ndo trabalho de parto com uso de ocitocina, uma vez que o índice de Bishop é maior que 7.","C":"Após comprovar bem-estar fetal por meio de cardiotocografia e estimar que o peso fetal\nencontre-se dentro do esperado para a idade\ngestacional, deve-se iniciar indução farmacológica do\ntrabalho de parto com uso de misoprostol, uma vez que o índice de Bishop é maior que 7.","D":"Após comprovar bem-estar fetal por meio de cardiotocografia e estimar que o peso fetal\nencontre-se dentro do esperado para a idade\ngestacional, deve-se iniciar indução farmacológica do\ntrabalho de parto com uso de misoprostol, uma vez que o índice de Bishop é menor que 7."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-321360","number":"321360","sourceNumber":"321360","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"VSF, 32 anos, primigesta, idade gestacional de 40 semanas, procurou maternidade por\ndor tipo contração. Na admissão,\napresentava altura de fundo uterino de 38 cm, 3 contrações em\n10 minutos de 45 segundos de duração, toque vaginal evidenciando colo centralizado e apagado\ncom 4 cm de dilatação, apresentação cefálica fletida em occipito esquerda anterior, no plano zero\nde DeLee e bolsa das águas íntegras. Três horas após esta avaliação, o exame de toque vaginal\nencontrava-se sem alterações. Mãe e concepto apresentavam boa vitalidade. A conduta mais\nadequada é:","options":{"A":"Indicar cesárea.","B":"Liberar paciente para o domicílio.","C":"Romper a bolsa das águas e avaliar o líquido amniótico.","D":"Reavaliar vitalidade materna e fetal a cada 30 minutos e dilatação a cada 2 ou 3 horas."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-321361","number":"321361","sourceNumber":"321361","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"C.F.N, 17 anos, G2P1A0, parto prematuro vaginal em gestação anterior com 30\nsemanas, sem ocorrência de RAMO (Rotura\nAnteparto das Membranas Ovulares). Comparece pela\nprimeira vez ao ambulatório de pré-natal para acompanhamento, com idade gestacional de 10\nsemanas. Indique a melhor orientação a ser dada.","options":{"A":"Está indicada a cerclagem uterina no fim do primeiro trimestre (12-14s) e o uso de nifedipina 20\nmg, oral, a cada 8h, diariamente, da 16a a 36a semana de gravidez, uma vez que existe como fator\nde risco história de trabalho de parto prematuro em gestação anterior.","B":"Está indicada a medição do colo por via transvaginal entre 16 e 24 semanas e o uso de\nnifedipina 20 mg, oral, a cada 8h, diariamente, da 16a a 36a semana de gravidez, uma vez que\nexiste como fator de risco história de trabalho de parto prematuro em gestação anterior.","C":"Está indicada a cerclagem uterina no fim do primeiro trimestre (12-14s) e o uso de progesterona\nnatural micronizada, de 100 a 200 mg intravaginal,\ndiariamente, da 16a a 36a semana de gravidez,\numa vez que existe como fator de risco história de trabalho de parto prematuro em gestação\nanterior.","D":"Está indicada a medição do colo por via transvaginal entre 16 e 24 semanas de gestação e o\nuso de progesterona natural micronizada, de\n100 a 200 mg intravaginal, diariamente, da 16a a 36a\nsemana de gravidez, uma vez que existe como fator de risco história de trabalho de parto\nprematuro em gestação anterior."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-292872","number":"292872","sourceNumber":"292872","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente, 23 anos, G1P0A0, em seguimento pré-natal na Unidade Básica de Saúde,\nmostra-se preocupada acerca da dor durante o trabalho de parto e as formas mais adequadas de\nseu alívio e aborda seu prenatalista sobre a maneira mais indicada de se conduzir diante desta\nsituação. Identifique a melhor orientação a ser dada.","options":{"A":"A pré-hidratação, acesso venoso periférico e manutenção de decúbito lateral são obrigatórios\ndurante todo o tempo em que a paciente estiver\nsob analgesia peridural.","B":"A solicitação materna por analgesia farmacológica de parto não compreende indicação suficiente\npara sua realização. Avaliação e prescrição\nconjunta, de obstetra e anestesista, deve ser sempre\nrealizada e todos os métodos não farmacológicos devem ter sido esgotados previamente.","C":"Os métodos não farmacológicos de alívio da dor, tais como imersão em água, áudio-analgesia e\naromaterapia, devem ser oferecidos à mulher antes da utilização de métodos farmacológicos, pois\nconstituem intervenções não invasivas e sem descrição de efeitos colaterais.","D":"Os métodos não farmacológicos de alívio da dor tais como imersão em água, áudio-analgesia,\naromaterapia, injeção de água estéril, estimulação elétrica transcutânea e acupuntura, devem ser\nsempre oferecidos à parturiente, já que se tratam de intervenções não invasivas e sem descrição\nde efeitos colaterais."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-292873","number":"292873","sourceNumber":"292873","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A prematuridade permanece, nos dias atuais, como sério problema perinatal, sendo\nresponsável por cerca de 75% de toda a morbidade e mortalidade neonatais (Blencowe et al., 2013;\nACOG, 2016). Com relação ao trabalho de parto prematuro, é CORRETO afirmar:","options":{"A":"O nifedipino é o fármaco de primeira escolha para inibir o parto pré-termo, por apresentar as\nseguintes vantagens: via oral de administração, poucos efeitos colaterais e eficácia em reduzir as\ncomplicações neonatais. A indometacina também pode ser utilizada, especialmente após a 32ª\nsemana.","B":"O uso de tocolítico visa prolongar a gestação por 48h enquanto se aguardam os efeitos\nbenéficos do corticoide e se transfere a\npaciente para maternidade de nível terciário. A manutenção\ndo tratamento tocolítico acima de 48h também é eficaz em prevenir o parto prematuro e melhorar o\nprognóstico neonatal.","C":"O sulfato de magnésio (MgSO) utilizado para a neuroproteção fetal está indicado na gestação\nentre 23 + 0 e 31 + 6 semanas quando há\nrisco de parto nos próximos 7 dias. A Profilaxia\nAntibiótica Intraparto (PAI) contra estreptococo do grupo B (GBS) é obrigatória, a menos que a\ncultura vaginorretal tenha sido negativa nas últimas 5 semanas.","D":"O corticoide é capaz não só de reduzir a incidência de Síndrome da Angústia Respiratória (SAR)\ncomo também de outras complicações no\nrecém-nascido, tais como hemorragia intraventricular,\nretinopatia da prematuridade, enterocolite necrosante, persistência do canal arterial e, o que é\nmais\nimportante, a taxa de mortalidade neonatal. O repouso no leito e a hidratação de nada servem para\na prevenção do parto prematuro."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-259777","number":"259777","sourceNumber":"259777","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primigesta a termo, comparece à emergência da maternidade referindo cólicas e perda\nde catarro com sangue. Ao exame obstétrico,\napresentava 2 contrações uterinas em 10 minutos,\nfeto com cabeça ocupando a escavação pélvica, fixa a mobilização, foco de ausculta principal em\nquadrante inferior direito a 155 batimentos cardiofetais, colo uterino 50% apagado, em\ncentralização, consistência intermediária, 3 cm de dilatação, apresentação no plano -2 de lee.\n\nSobre este caso, é correto afirmar que:","options":{"A":"o feto se encontra em situação longitudinal e posição a direita.","B":"a paciente se encontra em trabalho de parto ativo e o partograma deverá ser aberto.","C":"a apresentação está insinuada, o que infere em bom prognóstico para o parto vaginal.","D":"a variedade de posição fetal será determinada quando houver dilatação cervical mais avançada."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-259780","number":"259780","sourceNumber":"259780","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primigesta de 17 anos, IG 40 semanas, pré-natal sem intercorrências, comparece à\nemergência em trabalho de parto ativo, sendo admitida para assistência hospitalar. Encontra-se\nansiosa e refere não ter sido orientada sobre o processo do nascimento durante o pré-natal. De\nacordo com as boas práticas na assistência ao parto, indique, dentre as opções a seguir, qual\nrecomendação pode ser repassada a esta paciente no momento da admissão:","options":{"A":"Evita-se a indicação de analgesia peridural em fases iniciais de trabalho de parto, mesmo sob a\nsolicitação da mulher.","B":"As posições verticalizadas devem ser estimuladas durante todo o trabalho de parto, conforme o\ndesejo e conforto da mulher, mas devem ser evitadas durante o período expulsivo.","C":"Conforme recomendações mais recentes, lavagem intestinal, episiotomia e tricotomia genital e\nperineal devem ser realizados de rotina, desde que previamente comunicados e permitidos pela\nmulher.","D":"O exame de toque vaginal para avaliar a progressão da dilatação cervical deverá ser realizado\nem intervalos mínimos de 2 a 4 horas, evitando-se\npraticá-lo com muita frequência, exceto se\nhouver alguma preocupação com a evolução rápida do parto ou em resposta aos desejos da\nmulher."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-259782","number":"259782","sourceNumber":"259782","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente, 30 anos, G2P1nA0, idade gestacional de 28 semanas, tabagista, com\npolidrâmnio idiopático, procura assistência obstétrica referindo perda de líquido amniótico em\ngrande quantidade por via vaginal. A conduta imediata será:","options":{"A":"Realizar ultrassonografia para confirmar a ruptura e a hipoplasia pulmonar.","B":"Oferecer suplementação com progesterona vaginal para reduzir o risco de parto prematuro.","C":"Indicar tocólise e administrar betametazona 12 mg a cada 24h por 2 dias para maturação\npulmonar do feto.","D":"Realizar exame especular e administrar ampicilina 2 g EV, 6/6h por 48h + azitromicina 1 g VO\ndose única, seguida de amoxicilina 500 mg VO\n8/8h por mais 5 dias."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-259785","number":"259785","sourceNumber":"259785","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente de 20 anos, G2P1, IG 30 semanas, parto vaginal prematuro prévio, procura\nemergência obstétrica com cólicas acentuadas. Ao exame físico: PA 100x60 mmhg, altura uterina\n29 cm, batimentos fetais 150 bpm, dinâmica uterina presente, toque vaginal evidencia colo uterino\nde consistência amolecida, em apagamento, dilatado 3 centímetros, com bolsa amniótica íntegra.\nBaseado nesse quadro clínico, avalie os itens abaixo e indique a conduta inicial mais adequada ao\ncaso.","options":{"A":"Realizar medida de colo uterino por meio de ultrassonografia transvaginal, para confirmar\ndiagnóstico.","B":"Prescrever antibioticoprofilaxia contra infecção pelo estreptococo do crupo B e sulfato de\nmagnésio para neutroproteção.","C":"Prescrever nifedipino 20 mg via oral a cada 30 minutos, no máximo 4 doses, e betametasona 12\nmg intramuscular de 24/24 horas, 2 doses.","D":"Internar paciente em maternidade terciária, prescrever hidratação venosa vigorosa e analgesia e\norientar repouso em decúbito lateral esquerdo."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-234091","number":"234091","sourceNumber":"234091","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente primigesta, com gestação a termo, procura atendimento em hospital de nível\nsecundário apresentando quadro de dor em baixo-ventre rítmica e perda de tampão mucoso. O\nexame admissional evidencia dilatação do colo uterino de 6,0 cm, concepto em apresentação\ncefálica, frequência cardíaca fetal de 148 bpm e pressão arterial de 120 x 70 mmHg. Nega doenças\ncrônicas, uso de medicações ou alergias conhecidas. Para garantir atendimento humanizado\ndurante o trabalho de parto, devem ser oferecidos:","options":{"A":"Puxos orientados, amniotomia precoce, enteroclisma e delivramento ativo.","B":"Acompanhante de livre escolha, alimentação leve, tricotomia pubiana e verticalização.","C":"Enteroclisma, estimular deambulação, métodos não farmacológicos para alívio da dor e toques\nvaginais 4/4 horas.","D":"Bloqueio combinado raqui/peridural, posição materna de livre escolha, acompanhante de livre\nescolha e agentes uterotônicos no pós-parto."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-199653","number":"199653","sourceNumber":"199653","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Juliana, 35 anos, G5P4N, 40 semanas de gestação, está em período expulsivo,\nassistido por uma obstetra e acompanhada por uma\ndoula e por seu marido, Rodrigo. Rodrigo\nlembra à equipe a opção de Juliana pelo manejo ativo no terceiro período do parto. Qual é a\nsequência CORRETA do manejo ativo no terceiro período do parto?","options":{"A":"Ocitocina intramuscular, seguida de pinçamento do cordão umbilical e extração manual da\nplacenta.","B":"Ocitocina intramuscular, pinçamento do cordão umbilical e tração controlada após sinais de\nseparação da placenta.","C":"Pinçamento do cordão umbilical no primeiro minuto, ocitocina intramuscular e tração controlada\ndo\n\ncordão.","D":"Pinçamento do cordão umbilical após sinais de separação da placenta seguido de tração\ncontrolada do cordão."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-199733","number":"199733","sourceNumber":"199733","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Você assume o plantão no centro obstétrico e se depara com o partograma abaixo.\nQual a principal causa desse tipo de distócia?","options":{"A":"Assinclitismo.","B":"Taquissistolia.","C":"Hipocontratilidade uterina.","D":"Desproporção cefalopélvica."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-172997","number":"172997","sourceNumber":"172997","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Larissa, 20 anos, primeira gestação, admitida com queixa de cólicas e perda de tampão\nmucoso. Ao exame: 2 contrações em 10 minutos com duração de 25 segundos. BCF = 140 bpm e\ncolo centralizado, apagado e dilatado 3 cm. Três horas depois é avaliada e persiste com mesma\ndilatação cervical. Suas contrações ainda têm duração variável de 25 a 30 segundos e BCF = 148\nbpm. Grita e chora sem parar. Qual a melhor conduta diante desse cenário?","options":{"A":"Prescrever dolantina para alívio da dor.","B":"Solicitar analgesia peridural contínua.","C":"Orientar deambulação.","D":"Indicar cesárea."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-150834","number":"150834","sourceNumber":"150834","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primigesta de 15 anos, tabagista e usuária de drogas, com idade gestacional de 25\nsemanas, comparece à consulta de pré-natal questionando um resultado de ultrassonografia\nobstétrica que evidenciava medida de colo uterino de 2,4cm. Você observa na caderneta de\n\npré-natal, que a paciente iniciou o pré-natal no 1° trimestre, vem regularmente às consultas e que\nos exames de rotina do pré-natal foram\nrealizados há 2 meses e não apresentam alterações. Com\nrelação à prevenção da prematuridade, qual a melhor conduta?","options":{"A":"Explicar que existe risco de parto prematuro e iniciar progesterona.","B":"Tranquilizar a paciente, pois ela vem realizando o pré-natal corretamente.","C":"Prescrever corticoide, iniciar progesterona e encaminhar para realizar cerclagem.","D":"Agendar retorno para 30 dias, quando pretende prescrever progesterona e corticoide."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-150846","number":"150846","sourceNumber":"150846","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"SMST, 25 anos, gesta 1, com gestação de 40 semanas, apresentou o partograma a\nseguir. A parturiente estava deambulando livremente até então. Ante o exposto, e pela\ninterpretação do partograma, qual a melhor conduta? (VER IMAGEM)","options":{"A":"Realizar cirurgia cesariana.","B":"Aumentar a dose de ocitocina.","C":"Aguardar a evolução para parto vaginal.","D":"Orientar repouso em decúbito lateral esquerdo."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-127023","number":"127023","sourceNumber":"127023","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primigesta, 17 anos, 38 semanas de gestação foi admitida em maternidade de\nnível terciário. Exausta, paciente chora e se recusa a adotar posições verticalizadas. O partograma\nque demonstra a evolução de seu trabalho de parto encontra-se abaixo. (VER IMAGEM)\nAnalisando seu partograma, qual a conduta mais apropriada?","options":{"A":"Aplicar fórceps.","B":"Orientar os puxos.","C":"Administrar ocitocina endovenosa.","D":"Aguardar evolução espontânea do parto."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-126933","number":"126933","sourceNumber":"126933","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante, com idade gestacional de 36 semanas, com quadro de rotura prematura de\nmembrana há 19h, foi admitida em uma maternidade terciária com dinâmica uterina regular (3\ncontrações de 30 segundos em 10 minutos) e colo uterino centralizado, apagado e dilatado para\n3cm. Realizou, com 34 semanas, swab vaginal e retal para estreptococo do Grupo B cujas\nculturas foram negativas. Relata alergia a penicilina. Diante do quadro, qual a melhor orientação\nquanto à prevenção da sepse neonatal precoce?","options":{"A":"Iniciar cefazolina, 1g, EV, de 8 em 8h.","B":"Usar clindamicina, 900mg, EV, de 8 em 8h.","C":"Iniciar ampicilina, 2,0g, EV, seguida por 1,0g, EV, de 4 em 4h.","D":"Não há necessidade de se prescrever antibiótico."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-102134","number":"102134","sourceNumber":"102134","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante de 15 anos, com idade gestacional de 36 semanas por última menstruação e\nconfirmada por ultrassonografia precoce, relata perda de líquido claro, que escorre pelas pernas,\nassociada a dor no baixo ventre. Ao exame obstétrico, observa-se: pulso = 88 ppm, T = 37°. C, PA=\n120x80 mmHg, ausência de atividade uterina e batimentos fetais = 144 bpm. Ao toque vaginal,\nidentifica-se que a apresentação é cefálica de vértice, bolsa rota e o escore de Bishop = 3. Diante\ndo quadro, qual a MELHOR conduta dentre as opções abaixo?","options":{"A":"Indução do parto com ocitocina.","B":"Indução do parto com laminaria.","C":"Indução do parto com misoprostol.","D":"Indução do parto com sonda de Foley."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-102157","number":"102157","sourceNumber":"102157","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente gestante de 38 semanas, em seguimento pré-natal de rotina na Unidade\nBásica de Saúde da Família, foi examinada\npelo profissional pré-natalista que evidenciou os\nseguintes achados: dorso fetal do lado direito do abdome materno, polo cefálico em contato com o\nestreito superior da bacia. Ante o exame descrito, qual a posição fetal?","options":{"A":"Direita.","B":"Oblíqua.","C":"Cefálica.","D":"Longitudinal."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-102172","number":"102172","sourceNumber":"102172","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente com gestação de 40 semanas, em trabalho de parto em maternidade de nível\nterciário, apresenta o partograma mostrado na figura abaixo (VER IMAGEM).Ante a análise do\npartograma, qual a distócia a ser diagnosticada?","options":{"A":"Fase ativa prolongada.","B":"Período pélvico Prolongado.","C":"Parada secundária da descida.","D":"Parada secundária da dilatação."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-81240","number":"81240","sourceNumber":"81240","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Ao realizar a primeira manobra de Leopold, o professor de Medicina descreveu para o\naluno a palpação de um polo com superfície regular, arredondado, resistente e irredutível. Diante\ndo exame físico descrito pelo professor, qual a provável apresentação fetal?","options":{"A":"Pélvica.","B":"Córmica.","C":"Cefálica fletida.","D":"Cefálica defletida."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-81288","number":"81288","sourceNumber":"81288","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primigesta de 18 anos, com 39 semanas de gestação, encontra-se em trabalho de\nparto com a evolução expressa no partograma abaixo. Diante do quadro, defina o diagnóstico.\n(VER IMAGEM)","options":{"A":"Parada secundária de dilatação.","B":"Período pélvico prolongado.","C":"Fase latente prolongada.","D":"Fase ativa prolongada."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-81311","number":"81311","sourceNumber":"81311","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primigesta de 35 anos, em trabalho de parto com 5 contrações/10 minutos, com\nduração de 50 segundos cada; bolsa rota;\ncolo dilatado em 10 cm; apresentação cefálica em\noccipito direita anterior, no plano zero de De Lee. Examinada uma hora depois, apresentava sinais\nde distensão do seguimento inferior e a apresentação permanecia no mesmo plano. O médico\nresolveu fazer a pelvimetria, cujo resultado foi: conjugata diagonalis = 12 cm e diâmetro\nbituberoso\n\n= 9 cm. Diante dos achados acima, qual o provável diagnóstico?","options":{"A":"Distocia do estreito superior.","B":"Distocia do estreito inferior.","C":"Distocia do estreito médio.","D":"Distocia de rotação."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-81315","number":"81315","sourceNumber":"81315","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Secundigesta, com 28 semanas e história anterior de trabalho de parto prematuro,\nprocurou a emergência referindo cólicas de\nforte intensidade associadas à perda de tampão\nmucoso. Ao exame, identificou-se 3 contrações de 40 segundos em 10 minutos, batimentos\ncardíacos fetais de 140 bpm e colo uterino dilatado para 3 cm em apagamento. Qual terapêutica\ndeve ser indicada com o intuito de neuroproteção neonatal nesse caso?","options":{"A":"Atosiban.","B":"Penicilina cristalina.","C":"Sulfato de magnésio.","D":"Progesterona natural."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-65676","number":"65676","sourceNumber":"65676","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Durante avaliação de gestante em trabalho de parto, identificou-se como ponto de\nreparo da apresentação, o queixo fetal, que\nse encontrava anterior e à esquerda. Qual a linha de\norientação da referida variedade de posição?","options":{"A":"Linha facial.","B":"Sutura sagital.","C":"Sutura metópica.","D":"Sulco interglúteo.","E":"Sutura sagitometópica."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-65669","number":"65669","sourceNumber":"65669","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A incorporação das boas práticas de atenção ao parto e nascimento pelas equipes de\ncuidados é, sem dúvida, uma das ações com maior impacto na redução da morbimortalidade\nmaterna e neonatal. Desde 1985, a Organização Mundial da Saúde, Organização Panamericana da\nSaúde e o Ministério da Saúde recomendam práticas baseadas em evidências científicas,\ndemonstradamente úteis, que devem ser estimuladas na assistência ao parto. Qual das práticas\nabaixo está nesta lista?","options":{"A":"Controle da dor por analgesia peridural.","B":"Manipulação ativa do feto no momento do parto.","C":"Monitoramento fetal por meio de ausculta intermitente.","D":"Amniotomia precoce de rotina para diminuir a duração do trabalho de parto.","E":"Uso rotineiro de ergometrina parenteral no terceiro estágio do trabalho de parto."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-65668","number":"65668","sourceNumber":"65668","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante de 22 anos de idade, G1P0, idade gestacional de 38 semanas, foi admitida\nem trabalho de parto, e sua evolução pode ser\nvista no partograma abaixo. Diante dessa evolução,\nqual a melhor conduta? (VER IMAGEM)","options":{"A":"Estimular deambulação.","B":"Aplicar fórceps de alívio.","C":"Indicar parto abdominal.","D":"Prescrever ocitocina endovenosa.","E":"Aguardar evolução espontânea do parto normal."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-51128","number":"51128","sourceNumber":"51128","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Durante avaliação obstétrica, identificou-se que o feto estava em apresentação cefálica\nfletida e que o diâmetro biparietal havia\npassado pelo estreito superior da bacia materna. Como se\ndenomina esse tempo do mecanismo do parto?","options":{"A":"Insinuação.","B":"Sinclitismo.","C":"Rotação interna da cabeça.","D":"Flexão fisiológica da cabeça fetal."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-51253","number":"51253","sourceNumber":"51253","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Durante avaliação da parturiente, identificou-se, ao toque, colo com dilatação completa,\nbolsa íntegra e feto em apresentação cefálica\nfletida. Em qual período do trabalho de parto\nencontra-se a parturiente?","options":{"A":"Primeiro.","B":"Segundo.","C":"Terceiro.","D":"Quarto."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-51257","number":"51257","sourceNumber":"51257","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Durante avaliação da bacia obstétrica, identificou-se que o estreito superior era\narredondado, o diâmetro anteroposterior e o\nbituberoso eram grandes, o sacro era largo e côncavo.\nQual tipo de bacia está sendo descrita?","options":{"A":"Androide.","B":"Ginecoide.","C":"Antropoide.","D":"Platipeloide."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-141611","number":"141611","sourceNumber":"141611","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente 40 anos, gesta IV para III, chega à emergência com história de volumosa\nperda líquida, por via vaginal, há 6 horas. IG\n(US com 12s) = 31 semanas e pré-natal sem\nanormalidades. Ao exame físico, BCF = 142 bpm, AU = 27 cm e ausência de dinâmica uterina. Ao\nexame especular, observa-se presença de líquido amniótico. Considerando-se esse quadro, qual a\nmelhor conduta?","options":{"A":"Avaliar o índice de Bishop.","B":"Iniciar hidratação endovenosa e corticoterapia, para maturação pulmonar fetal.","C":"Indicar a amniocentese para se diagnosticar possível infecção ovular e se avaliar o grau de\nmaturidade pulmonar.","D":"Indicar parto abdominal pelo alto risco de tocotraumatismo na prematuridade."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-45334","number":"45334","sourceNumber":"45334","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"No mecanismo do parto, a rotação interna das espáduas ocorre em concomitância com:","options":{"A":"o desprendimento da cabeça.","B":"a rotação interna da cabeça.","C":"a descida.","D":"o encaixamento.","E":"a insinuação."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-32523","number":"32523","sourceNumber":"32523","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Qual é a percentagem máxima de partos por cesariana que a Organização Mundial de\nSaúde (OMS) recomenda?","options":{"A":"50%","B":"10%","C":"15%","D":"20%","E":"25%"},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-30900","number":"30900","sourceNumber":"30900","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante 29 anos, G4P3A0, 3 partos vaginais anteriores (1° e 3° pré-termos),\napresentou 3 episódios de infecção urinária\ndurante a gestação, diagnosticados por urinocultura\ncom isolamento de E. coli, tratadas de forma inadequada. O exame direto do conteúdo vaginal\nrealizado no 2° trimestre demonstrou vaginose bacteriana. Foi admitida com queixa de perda de\nlíquido amniótico e sem atividade uterina. A idade gestacional de 32 semanas foi confirmada e a\nvitalidade fetal está preservada. Qual das opções abaixo NÃO faz parte da conduta para este caso?","options":{"A":"Fazer corticoide IM.","B":"Fazer antibiótico VO.","C":"Rastrear infecção.","D":"Vigiar vitalidade fetal.","E":"Fazer uterolítico EV."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-32554","number":"32554","sourceNumber":"32554","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"No parto, uma laceração perineal rompeu, através da pele da fúrcula, a mucosa\nvaginal, a fáscia e o músculo perineal; não\ncomprometeu, contudo, o esfíncter anal nem a mucosa\nretal. Isso deve ser registrado como laceração perineal de:","options":{"A":"Primeiro grau.","B":"Segundo grau.","C":"Terceiro grau.","D":"Quarto grau.","E":"Quinto grau."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-37006","number":"37006","sourceNumber":"37006","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Na assistência ao parto, como se denomina a 1ª hora após a saída da placenta?","options":{"A":"1º. período.","B":"2º. período.","C":"3º. período.","D":"4º. período."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-37007","number":"37007","sourceNumber":"37007","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Qual a circunferência de insinuação na apresentação pélvica incompleta?","options":{"A":"Sulco interglúteo.","B":"Sacrotibial.","C":"Sacrofemoral.","D":"Sacrococcígea."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-37009","number":"37009","sourceNumber":"37009","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Qual a principal causa de hemorragia pós-parto?","options":{"A":"Distúrbio de coagulação.","B":"Laceração de trajeto.","C":"Restos placentários.","D":"Atonia uterina."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-37010","number":"37010","sourceNumber":"37010","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Qual uterolítico apresenta menos efeitos colaterais?","options":{"A":"Nifedipina.","B":"Ritodrina.","C":"Atosiban.","D":"Indometacina."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-37442","number":"37442","sourceNumber":"37442","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O diagnóstico da rotura prematura das membranas é confirmado na maioria das vezes\natravés do(a):","options":{"A":"PH vaginal maior ou igual a 6,5.","B":"Cristalização do muco cervical.","C":"Ultrassonografia obstétrica é o procedimento mais\nutilizado e em mais de 80% dos casos mostra a\noligoidramnia severa.","D":"Anamnese e exame físico raramente.","E":"Infusão intra-amniótica de corante (fenol vermelho)."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-25325","number":"25325","sourceNumber":"25325","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Multípara em trabalho de parto apresenta ao toque vaginal colo dilatado para 8 cm,\nbolsa rota, apresentação cefálica, com parietal anterior profundamente baixo em relação ao\nposterior e sutura sagital próxima do promontório. Como se denomina este achado?","options":{"A":"Assinclitismo anterior","B":"Flexão fisiológica da cabeça fetal","C":"Rotação interna da cabeça","D":"Sinclitismo","E":"Obliquidade de Litzman"},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-22940","number":"22940","sourceNumber":"22940","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Qual das apresentações abaixo torna o parto mais lento?","options":{"A":"Occiptoesquerda anterior","B":"Occiptodireita anterior","C":"Sacropúbica","D":"Occiptopúbica","E":"Occiptodireita posterior"},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-24387","number":"24387","sourceNumber":"24387","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Na extração podal, a manobra utilizada para a extração do braço fetal, com a aplicação\ndo polegar na axila, apoiados o índice ao longo\ndo úmero e o médio na prega do cotovelo, onde a\npressão é exercida, é chamada:","options":{"A":"Manobra de Mauriceau.","B":"Manobra de Bracht.","C":"Manobra de Pajot.","D":"Manobra de Pinard."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-24390","number":"24390","sourceNumber":"24390","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Na determinação da variedade de posição, o ponto de referência fetal nas\napresentações cefálicas defletidas de 1º grau é:","options":{"A":"Lâmbda.","B":"Extremidade anterior do bregma.","C":"Glabela ou raiz do nariz.","D":"Mento."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-27687","number":"27687","sourceNumber":"27687","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Sobre as manobras de Leopold-Zweifel, marque a alternativa verdadeira.","options":{"A":"O primeiro tempo consiste na determinação da posição fetal.","B":"O segundo tempo determina o polo fetal que ocupa o estreito superior da bacia.","C":"O terceiro tempo delimita o fundo uterino e a parte fetal que o ocupa.","D":"O quarto tempo explora a escava e o polo que a ocupa.","E":"O quinto tempo determina a mobilidade e insinuação do polo em contato com o estreito superior\nda bacia."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-27689","number":"27689","sourceNumber":"27689","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Marque a alternativa ERRADA na associação entre situação, apresentação, ponto de\nreferência e linha de orientação:","options":{"A":"Longitudinal, cefálica fletida, lâmbda, sutura sagital","B":"Transversa, córmica, acrômio e dorso","C":"Longitudinal, pélvica, crista sacrococcígea, sulco interglúteo","D":"Longitudinal, cefálica de fronte, glabela, linha metópica","E":"Longitudinal, cefálica de face, bregma, linha facial"},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-27704","number":"27704","sourceNumber":"27704","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente de 22 anos, G2P1A0 (parto vaginal há 3 anos), 33 semanas, chega à\nemergência da maternidade com sangramento vivo e indolor, de leve intensidade, de início há 2\nhoras. PA 120 X 80 mmHg, pulso 76 bpm, FR 16 irpm. Ao US evidencia-se placenta prévia\nmarginal e feto com boa vitalidade (BCF 144 bpm, ILA 150 mm, boa movimentação fetal). Qual a\nconduta mais adequada?","options":{"A":"Interrupção imediata da gestação por cesariana.","B":"Progesterona via vaginal e acompanhamento ambulatorial semanal.","C":"Internação, corticoterapia e observação clínica.","D":"Corticoterapia e acompanhamento ambulatorial semanal.","E":"Indução imediata do parto por via vaginal"},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-6916","number":"6916","sourceNumber":"6916","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Multípara em trabalho de parto apresenta ao toque vaginal colo dilatado para 8 cm,\nbolsa rota, apresentação cefálica, com parietal anterior profundamente baixo em relação ao\nposterior e sutura sagital próxima do promontório. Como denomina-se este achado?","options":{"A":"Assinclitismo anterior.","B":"Flexão fisiológica da cabeça fetal.","C":"Rotação interna da cabeça.","D":"Sinclitismo.","E":"Obliquidade de Litzman."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-6904","number":"6904","sourceNumber":"6904","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Qual medicação abaixo NÃO deve ser utilizada como uterolítico?","options":{"A":"Nifedipina.","B":"Ritodrina.","C":"Atosiban.","D":"Progesterona.","E":"Indometacina."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-7257","number":"7257","sourceNumber":"7257","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Qual item contém a sequência correta em termos de frequência de apresentação fetal?","options":{"A":"Cefálica defletida > pélvica > transversa.","B":"Transversa > pélvica > cefálicas.","C":"Cefálica fletida > pélvica > transversa.","D":"Cefálicas > transversa > pélvica.","E":"Transversa > pélvica > cefálica fletida."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-13476","number":"13476","sourceNumber":"13476","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Na apresentação cefálica com deflexão de 3º grau, com variedade de posição\nmento--esquerda--anterior, qual a situação e a posição fetal?","options":{"A":"Transversa, direita.","B":"Transversa, esquerda.","C":"Longitudinal, direita.","D":"Longitudinal, esquerda.","E":"Córmica, esquerda."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-13396","number":"13396","sourceNumber":"13396","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em nulípara de 24 anos, com 32 semanas de gestação, o feto encontra--se em\napresentação pélvica. Qual a informação abaixo deve ser dada a gestante?","options":{"A":"Seria melhor programar cesárea eletiva.","B":"Esse achado é comum nessa idade gestacional.","C":"É necessário tentar versão externa imediata.","D":"Será necessário tentar uma versão externa durante o trabalho de parto.","E":"Indicar versão interna imediatamente."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-16045","number":"16045","sourceNumber":"16045","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A bacia que possui o estreito superior de forma triangular é denominada:","options":{"A":"ginecoide.","B":"androide.","C":"antropoide.","D":"platipeloide.","E":"assimétrica."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-16055","number":"16055","sourceNumber":"16055","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A fibronectina fetal é um preditor de:","options":{"A":"corioamnionite.","B":"placenta prévia.","C":"parto pré-termo.","D":"gestação prolongada.","E":"mola hidatiforme."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-365564","number":"365564","sourceNumber":"365564","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Uma gestante de 22 anos de idade, G1, IG = 34 semanas e 1 dia, compareceu ao\npronto-socorro da maternidade com queixa de perda de líquido via vaginal, que parecia água com\nodor de água sanitária, há seis horas. Relatou ter achado que era urina, mas que iniciou com\ncalafrios e optou por procurar assistência médica. Negou outros sintomas. Ao exame físico,\napresentou FC = 102 bpm, T = 39 ºC, FR = 25 irpm, SpO2 = 99%, PA = 110 mmHg x 75mmHg e\nBCF = 162 bpm. O exame especular mostrou presença de líquido transparente, com rajas de\nsangue exteriorizando-se por orifício externo de colo uterino. Ao exame de abdome, demonstrou\ndor à palpação do útero. Em relação ao caso clínico descrito, qual é a principal hipótese\ndiagnóstica?","options":{"A":"Sofrimento fetal agudo detectado pelo aumento da frequência cardíaca fetal","B":"Descolamento prematuro da placenta","C":"Trabalho de parto prematuro","D":"Corioamnionite"},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-365563","number":"365563","sourceNumber":"365563","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Uma gestante de 22 anos de idade, G1, IG = 34 semanas e 1 dia, compareceu ao\npronto-socorro da maternidade com queixa de perda de líquido via vaginal, que parecia água com\nodor de água sanitária, há seis horas. Relatou ter achado que era urina, mas que iniciou com\ncalafrios e optou por procurar assistência médica. Negou outros sintomas. Ao exame físico,\napresentou FC = 102 bpm, T = 39 ºC, FR = 25 irpm, SpO2 = 99%, PA = 110 mmHg x 75mmHg e\nBCF = 162 bpm. O exame especular mostrou presença de líquido transparente, com rajas de\nsangue exteriorizando-se por orifício externo de colo uterino. Ao exame de abdome, demonstrou\ndor à palpação do útero. Acerca do caso clínico mencionado, considere que a paciente em\natendimento, ao toque vaginal, tenha apresentado colo posterior, com 1 cm de dilatação, cabeça\nfetal em -1 de Delee e dinâmica uterina ausente. Nesse contexto, assinale a alternativa que\ncorresponde à conduta mais adequada ao caso.","options":{"A":"Internação, cesariana de urgência e penicilina cristalina endovenosa.","B":"Internação, avaliação da vitalidade fetal, indução de parto e antibioticoterapia com ampicilina e\ngentamina endovenosos.","C":"Internação, corticoterapia para maturação pulmonar e tocólise por 48 horas.","D":"Internação, ecografia obstétrica, hiper-hidratação, antibioticoterapia com ampicilina e\nazitromicina, mantendo observação clínica."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-322198","number":"322198","sourceNumber":"322198","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante de 41 semanas, G2C1, procura o hospital para resolução da gestação, sendo\nque sua última cesárea foi há 3 anos.\nPré-natal de risco habitual e sem complicações durante a\ngestação. Ao exame físico, apresenta sinais vitais normais, vitalidade fetal preservada, altura\nuterina de 34 cm, contrações ausentes e movimentos fetais presentes. No toque vaginal,\napresentação cefálica, colo posterior com 2 cm de dilatação e apagado 20%, De Lee -1 e bolsa\níntegra. Nesse caso clínico, qual seria a melhor conduta?","options":{"A":"Misoprostol via vaginal a cada 4 horas.","B":"Misoprostol via vaginal a cada 6 horas.","C":"Indicar cesárea.","D":"Preparo de colo com Sonda Foley.","E":"Indução do trabalho de parto com ocitocina em bomba de infusão."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-322201","number":"322201","sourceNumber":"322201","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Referente à indução do trabalho de parto em pacientes que possuem cesárea anterior e\nfeto com boa vitalidade, assinale a alternativa correta.","options":{"A":"É contraindicado realizar indução do parto devido ao risco de rotura uterina.","B":"Se o índice de Bishop for maior que 6, poderá ser usada ocitocina em bomba de infusão.","C":"Misoprostol 25 mcg é a primeira escolha nesses casos.","D":"Realizar amniotomia e aguardar início do trabalho de parto.","E":"Realizar misoprostol 25 mcg associado à ocitocina."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-305330","number":"305330","sourceNumber":"305330","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O partograma é um gráfico no qual são anotadas a progressão do trabalho de parto e\nas condições materno-fetais. Analise o seguinte\npartograma e assinale a alternativa correspondente\ncom o padrão encontrado.","options":{"A":"Fase ativa prolongada.","B":"Parada secundária da descida.","C":"Desproporção cefálo-pélvica.","D":"Distócia funcional.","E":"Trabalho de parto fisiológico."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-305338","number":"305338","sourceNumber":"305338","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"São parâmetros utilizados para avaliar o colo uterino (índice de Bishop), EXCETO:","options":{"A":"Dilatação.","B":"Apagamento.","C":"Consistência.","D":"Coloração.","E":"Posição."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-211934","number":"211934","sourceNumber":"211934","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Uma paciente de 35 anos de idade, G3P1A1, gestação única de feto cefálico com 28\nsemanas de idade gestacional, sem\ncomorbidades, referiu perda de líquido via vaginal, com início\nhá aproximadamente oito horas. Ao exame especular, apresentou saída de líquido amniótico pelo\norifício cervical externo. Ela mostra-se estável, com temperatura axilar de 36,2°C, altura uterina\nde\n26 cm, BCF de 156 bpm e dinâmica uterina ausente. O toque vaginal evidenciou colo grosso,\nposterior e fechado. De acordo com esse caso clínico, a respeito da conduta mais adequada para\npaciente mencionada, assinale a alternativa correta.","options":{"A":"Conduta expectante, internação, exames e controle da vitalidade fetal.","B":"Conduta expectante, cardiotocografia e controle ambulatorial.","C":"Realização de cesárea de urgência pelo risco de infecção ovular.","D":"Conduta expectante, internação, exames e indução do parto com 30 semanas.","E":"Internação, exames laboratoriais e indução do parto imediatamente."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-211986","number":"211986","sourceNumber":"211986","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Um paciente de 35 anos de idade , G3C2, com 38 semanas de idade gestacional, sem\ncomorbidades, chegou ao consultório apresentando queixa de contrações frequentes. Ao exame,\nverificaram-se altura uterina de 37 cm, BCF de 138 bpm, dinâmica uterina presente igual a 3\ncontrações de 40 segundos em 10 minutos e, ao toque vaginal, observou-se colo grosso, posterior,\nfechado. Diante desse quadro, a paciente foi encaminhada para internação para realização de\ncesariana por iteratividade. Com base nesse caso clínico e nos conhecimentos médicos correlatos,\na respeito das indicações de cesárea, assinale a alternativa correta.","options":{"A":"Feto em apresentação cefálica.","B":"Condilomatose vulvar.","C":"Feto em apresentação córmica.","D":"História de herpes genital.","E":"Pré-eclâmpsia."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-179176","number":"179176","sourceNumber":"179176","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"No que diz respeito ao alívio da dor no trabalho de parto normal a termo, assinale a\nalternativa CORRETA de acordo com as recentes diretrizes nacionais de assistência ao parto\nnormal do Ministério da Saúde.","options":{"A":"A imersão em água para alívio da dor no trabalho de parto é contraindicada devido ao risco para\no binômio mãe-filho.","B":"A analgesia regional não prolonga o primeiro período do parto mais longo nem aumenta a\nchance de cesariana.","C":"A solicitação materna por analgesia de parto é dependente da fase do parto e do grau de\ndilatação.","D":"A estimulação elétrica transcutânea deve ser utilizada em mulheres em trabalho de parto\nestabelecido.","E":"Os opioides devem ser utilizados de rotina, pois oferecem alívio da dor e apresentam poucos\nefeitos colaterais para a mulher."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-179187","number":"179187","sourceNumber":"179187","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"No que se refere à conduta adequada em casos de ruptura prematura de membranas\nno parto a termo, assinale a alternativa correta\nà luz das recentes diretrizes nacionais de\nassistência ao parto normal do Ministério da Saúde.","options":{"A":"Na ausência de contrações, deve-se realizar toque vaginal caso haja dúvida em relação ao\ndiagnóstico de ruptura das membranas.","B":"Deve-se informar à gestante que mais da metade das mulheres com ruptura precoce de\nmembranas no termo entrará em trabalho de parto em até 24 horas.","C":"Deve-se induzir o trabalho de parto até 48 horas após a ruptura precoce das membranas.","D":"Deve-se aconselhar a mulher a aguardar em domicílio, por até 24 horas, para prevenção de\ninfecção hospitalar.","E":"Deve-se indicar cesariana se o trabalho de parto não se iniciar em até 72 horas após a ruptura\nprecoce das membranas."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-179193","number":"179193","sourceNumber":"179193","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Acerca das novas condutas recomendadas em intervenções e medidas de rotina no\nprimeiro período do parto normal, assinale a alternativa CORRETA:","options":{"A":"A amniotomia precoce, associada ou não à ocitocina, deve ser realizada de rotina em mulheres\nem trabalho de parto que estejam progredindo\nbem.","B":"As tricotomias pubiana e perineal devem ser realizadas de forma rotineira durante o trabalho de\nparto.","C":"As mulheres devem ser orientadas a permanecer em repouso, na posição de decúbito lateral\nesquerdo.","D":"Se houver suspeita de falha de progresso ainda no primeiro estágio do trabalho de parto,\ndeve-se considerar a necessidade de avaliação especializada.","E":"O enema deve ser realizado de forma rotineira durante o trabalho de parto."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-152115","number":"152115","sourceNumber":"152115","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente de 19 anos de idade, primigesta, com 35 semanas de gestação, tabagista de\n10 cigarros/dia, com má adesão ao pré-natal,\napresenta exames solicitados de terceiro trimestre,\nentre eles VDRL 1:16, e demais sorologias não reagentes. Paciente nega tratamento prévio para\nsífilis e desconhece o diagnóstico da doença; não realizou sorologias de primeiro e segundo\ntrimestre. Considerando essa situação e os conhecimentos médicos a ela relacionados, julgue o\nitem a seguir. É necessário realizar corticoterapia em duas doses para maturação pulmonar e logo\ninduzir o trabalho de parto.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-152105","number":"152105","sourceNumber":"152105","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente de 28 anos de idade, G2P1 com 37 semanas de gestação, 12 consultas de\npré-natal, sorologias negativas, TS A positivo, coleta de Streptococcus do grupo B (Vaginal e reta),\nambas positivas, chega à emergência obstétrica relatando contrações e perda de líquido, que se\niniciou há 1 hora. Ao exame físico geral, apresentou TA = 120/70, FC= 80, FR= 20, TAX= 36,5°. Ao\nexame físico obstétrico, observam-se altura uterina= 35 cm, BCF = 150 batimentos por minuto,\ndinâmica uterina = 3 contrações efetivas em 10 minutos. Especular mostra que há líquido amniótico\nclaro com vémix fluindo pelo orifíco cervical e, ao toque vaginal, o colo encontra-se amolecido,\ncentrado, com 3 cm de dilatação; a apresentação é cefálica e não se toca bolsa residual. Com base\nnesse caso clínico, e considerando os conhecimentos médicos a ele relacionados, julgue o item a\nseguir. A paciente deve ser liberada, pois não está em trabalho de parto.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-131812","number":"131812","sourceNumber":"131812","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Assinale a alternativa que apresenta a situação na qual é indicada a conduta\nexpectante na ruptura prematura de membranas.","options":{"A":"Gestante com 27 semanas de idade gestacional e presença de sinais indicativos de infecção\nmaterna.","B":"Presença de infecção fetal em gestante com 25 semanas de idade gestacional.","C":"Utilização prévia de corticosteroide (betametasona 12mg, IM, duas doses com intervalo de 24\nhoras) em gestante assintomática e com 31 semanas de idade gestacional.","D":"Sofrimento fetal agudo, independentemente da idade gestacional.","E":"Idade gestacional \"maior ou igual\" 34 semanas."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-131814","number":"131814","sourceNumber":"131814","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Quanto à primeira manobra a ser realizada na ocorrência de uma distócia de ombro,\nassinale a alternativa correta.","options":{"A":"Manobra de McRoberts.","B":"Manobra de saca-rolhas de Woods.","C":"Manobra de Rubin.","D":"Manobra de Zavanelli.","E":"Fratura deliberada da clavícula anterior."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-108197","number":"108197","sourceNumber":"108197","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Julgue o próximo item, referente a planejamento familiar e assistência pré-natal. O parto\ncesáreo é mandatório para as gestantes que tenham sido submetidas à cirurgia bariátrica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-64673","number":"64673","sourceNumber":"64673","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Uma paciente de 20 anos que morava em lugar sem saneamento básico faz pré-natal\nregularmente na unidade básica de saúde e está com 23 semanas de gestação. Os exames\nlaboratoriais apresentaram alterações como hemoglobina de 10,1 g/dl, hematócrito de 31% e\nparasitológico de fezes com Giardia lamblia. Os demais exames estavam dentro da normalidade. A\npaciente tem, como queixa clínica, diarreia aquosa duas vezes ao dia, de odor fétido. Ela apresenta\nmucosas hidratadas. Com base nestas informações, assinale a alternativa que apresenta o melhor\ntratamento para a parasitose desta paciente.","options":{"A":"Hidratação via oral, dieta leve e medicamentos para cessar o quadro diarreico.","B":"Teclosan 1 g 8/8h por 3 dias, hidratação endovenosa e jejum por 24h.","C":"Clorosalicilamida 100 mg/dia durante 3 dias, praziquantel 25 mg/kg, dose única e hidratação\nendovenosa.","D":"Metronidazol 250 mg 3 vezes por dia durante 7 dias, hidratação via oral ou tinidazol 2 g dose\núnica.","E":"Pamoato de pirantel 10 mg/kg durante 3 dias, loperamida e hidratação via oral."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-64725","number":"64725","sourceNumber":"64725","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Ao acompanhar uma paciente primigesta em trabalho de parto ativo, com 39 semanas\ne 4 dias de gestação, e ao avaliar o\npartograma, observa-se a seguinte característica: persistência\nda mesma dilatação evidenciada por dois toques sucessivos com intervalo de 2 horas, presença de\nbossa serossanguinolenta. Diante do exposto, assinale a alternativa que apresenta,\nrespectivamente, o diagnóstico deste partograma, a causa dessa alteração e a conduta a ser\ntomada.","options":{"A":"Parada secundária da descida, cordão umbilical curto e fórcipe.","B":"Parada secundária da dilatação, desproporção cefalopélvica e rotura das membranas ovulares\nou cesariana.","C":"Período pélvico prolongado, contração uterina ineficaz e uso de vácuo extrator.","D":"Parto fisiológico, rotura das membranas ovulares e episiotomia.","E":"Parada secundária da dilatação, nó verdadeiro de cordão e ocitocina."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-52604","number":"52604","sourceNumber":"52604","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Julgue o próximo item, relativo à semiologia obstétrica. A sutura sagital próxima ao\npromontório caracteriza o assinclitismo anterior e, quando próxima ao pube, caracteriza o\nassinclitismo posterior.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-52606","number":"52606","sourceNumber":"52606","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Julgue o próximo item, relativo a semiologia obstétrica. O antropoide, entre os quatro\ntipos fundamentais de bacias, é o canal ósseo da\npelve mais comumente encontrado em mulheres.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-52614","number":"52614","sourceNumber":"52614","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Julgue o próximo item, relativo a semiologia obstétrica. A fontanela anterior\ncorresponde ao bregma e é a maior das fontanelas.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-52615","number":"52615","sourceNumber":"52615","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Julgue o próximo item, relativo a semiologia obstétrica. O período de Greenberg, ou\nquarto período do parto, corresponde ao período de uma hora após a descida da placenta.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-52617","number":"52617","sourceNumber":"52617","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Julgue o próximo item, relativo a semiologia obstétrica. A maioria dos deslocamentos\nplacentários que acontecem no secundamento\nocorre pelo mecanismo de Baudelocque-Schultze.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-45757","number":"45757","sourceNumber":"45757","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante de dezenove anos, G1P0A0, Idade Gestacional (IG) de 39 semanas, bem\ndatada, bolsa rota com saída de líquido claro\nhá três horas, encontra-se internada no centro\nobstétrico, onde foi admitida às oito horas. Foi iniciada a indução do parto logo após a admissão.\nForam feitas avaliações conforme a seguir. Primeira avaliação às 8h: Batimentos Cardíacos Fetais\n(BCF) = 150 bpm, Dinâmica Uterina (DU) = 1/10'/20\", toque vaginal = colo pérvio para 1 cm.\n\nReavaliação às 10h: BCF = 138 bpm, DU = 1/10'/40\", toque vaginal = colo pérvio para 2 cm.\nReavaliação às 11h: BCF: = 155 bpm, DU =\n3/10'/40\", toque vaginal = colo pérvio para 3 cm.\nReavaliação às 14h: BCF = 140 bpm, DU = 4/10'/40\", toque vaginal = colo pérvio para 7 cm.\nReavaliação às 15h: BCF = 110 bpm, DU = 6/10'/40\", toque vaginal = colo pérvio para 9 cm. O\npartograma é a representação gráfica do trabalho de parto. Seu emprego melhora a qualidade da\nassistência obstétrica, permitindo identificar e corrigir precocemente trabalhos de parto\ndisfuncionais. Para tal, é fundamental o início do registro gráfico sem precipitações. No caso dessa\npaciente, analisando-se as evoluções descritas, o horário correto e mais adequado para o início do\nregistro gráfico do partograma será às:","options":{"A":"8 horas.","B":"10 horas.","C":"11 horas.","D":"14 horas.","E":"15 horas."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-32148","number":"32148","sourceNumber":"32148","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Assinale a alternativa correta a respeito da prematuridade.","options":{"A":"A interrupção antecipada da gravidez é uma das causas mais comuns do parto pré-termo\nindicado.","B":"Os organismos encontrados no parto pré-termo espontâneo são de alta virulência como\nestreptococo do grupo B e a Escherichia coli.","C":"A indicação de cesárea aos pré-termos com menos de 32 semanas faz-se diante da\napresentação pélvica, anômala, porém a via vaginal\nfica reservada aos de apresentação cefálica.","D":"A prematuridade pode compreender não apenas aqueles nascidos antes do tempo cronológico,\nmas também aqueles lactentes que sofreram\nrestrição de crescimento no útero.","E":"O uso de tocolíticos, empregados enquanto houver contrações uterinas, melhora o prognóstico\nperinatal."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-32187","number":"32187","sourceNumber":"32187","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Uma paciente procurou atendimento médico apresentando o seguinte quadro: G II P I\n(parto vaginal há três anos) Ab O, DUM revela IG de 36 semanas, história de moderada perda de\nlíquido claro há seis horas e ausência de dores, BCF de 144 bpm. Com base no caso apresentado\nno texto, assinale a alternativa que apresenta o procedimento inicial correto a ser realizado pelo\nmédico.","options":{"A":"Realizar toque vaginal para percepção e visualização da perda do líquido pela paciente, para,\nentão, promover a internação.","B":"Solicitar à paciente que realize manobras de esforço; não visualizando perda líquida pela\ngenitália externa, encerrar o atendimento.","C":"Realizar o toque vaginal e pedir à paciente que faça manobras de valsalva, para visualizar a\nperda.","D":"Por não haver necessidade do exame médico, solicitar exame de imagem, para verificar a perda.","E":"Examinar com ajuda do espéculo vaginal em associação com uma pressão no fundo uterino,\npara melhor visualização da perda líquida."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-32192","number":"32192","sourceNumber":"32192","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Uma paciente procurou atendimento médico apresentando o seguinte quadro: G II P I\n(parto vaginal há três anos) Ab O, DUM revela IG de 36 semanas, história de moderada perda de\nlíquido claro há seis horas e ausência de dores, BCF de 144 bpm. Considerando o caso\napresentado no texto, assinale a alternativa que apresenta a melhor opção terapêutica.","options":{"A":"Internar a paciente; iniciar antibiótico de largo espectro; impedir o nascimento durante 72 horas\npara realizar o amadurecimento pulmonar do\nconcepto, com emprego de corticoide, e realizar\ncesariana.","B":"Aguardar o início das contrações em regime domiciliar-ambulatorial, para internação da paciente;\niniciar antibioticoterapia de largo espectro.","C":"Internar a paciente; induzir o parto, com uso de ocitocina intravenosa, considerando a\nnecessidade de amadurecimento do colo com\nprostaglandinas do tipo E1, de acordo com o Índice\nde Bishop; associar o uso profilático com antibiótico de amplo espectro durante todo o tempo, até o\nquinto dia de pós-parto.","D":"Internar a paciente na enfermaria de alto risco, sob uso de antibioticoterapia e, após 48 horas,\nrealizar a cesárea.","E":"Internar a paciente na enfermaria de alto risco, com repouso absoluto; realizar leucograma\ndiário, para rastreio de infecção, monitorização\ncom cardiotocografia, perfil biofísico fetal diário e\nultrassonografia diária, para determinação do ILA; a gravidez poderá ser interrompida, se houver\nsinal de infecção."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-32158","number":"32158","sourceNumber":"32158","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Assinale a alternativa correta quanto à assistência ao parto.","options":{"A":"Para que se processe o encaixamento, é necessário haver redução dos diâmetros da cabeça\nfetal. Assim sendo, passando do maior diâmetro\ne resultando no occipitofrontal.","B":"Em ordem decrescente, a variedade de posição de encaixamento mais frequente é a OEA,\nseguida da ODA, OEP e, a mais rara, ODP.","C":"O parto compreende basicamente três tempos: insinuação, descida e desprendimento.","D":"O início do registro do partograma deve ser feito na presença de uma contração em dez minutos\ne dilatação de 3 cm.","E":"O secundamento ou terceiro período do parto consta de três tempos: deslocamento ou\ndequitação, descida e expulsão ou desprendimento da placenta."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-27553","number":"27553","sourceNumber":"27553","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A amniotomia é considerada oportuna quando realizada com a dilatação do colo uterino\nmedindo:","options":{"A":"entre 4 e 8 cm.","B":"entre 1 e 3 cm.","C":"entre 9 e 10 cm.","D":"com 9 cm de dilatação.","E":"em qualquer fase do período de dilatação."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-27534","number":"27534","sourceNumber":"27534","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente Gesta III Para II, partos vaginais, na 38ª semana de gravidez, apresenta-se ao\nhospital com queixas de dores abdominais tipo cólica e perda de tampão mucoso. Ao exame\napresenta: 1 metrossístole em 10 minutos, com 35 segundos de duração, - colo com apagamento\nde 50%, centralizado, dilatado para 2 cm, apresentação cefálica alta, membranas íntegras. BCF de\n140 bpm, ritmados. O diagnóstico deve ser:","options":{"A":"1ª fase de trabalho de parto.","B":"fase prodrômica de trabalho de parto.","C":"falso trabalho de parto","D":"gravidez serotina.","E":"desproporção cefalo-pélvica."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-7527","number":"7527","sourceNumber":"7527","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente é internada em 8/11/08 no centro obstétrico, em trabalho de parto. No cartão\nde pré-natal consta DUM 1/2/08, DPP 10/11/08,\nGesta II, Para I (PN), aborto 0, laudo da\nultrassonografia realizada em 30/3/08: Embrião com bcf Positivo, comprimento cabeça-nádegas de\n52mm, IG de 9 semanas+ 4 dias. Ao exame físico: posição do colo posterior, esvaecimento em\n40% consistência média, altura do plano de Delee em -1,2 dilatado para 4 cm, bolsa íntegra,\napresentação cefálica, bcf de 144 bpm, 2 contrações de 50 segundos em 10 minutos, boa\nproporcionalidade bacia e apresentação fetal. Em relação a essa situação hipotética, assinale a\nalternativa correta.","options":{"A":"Essa gestação é de 40 semanas+2 dias. Pelo índice de Bishop ser < que 6, indica-se uso de\nprostaglandinas para amadurecimento do colo e assim indução do parto.","B":"Essa gestação é de 40 semanas. Pelo índice de Bishop ser igual a 6, indica-se uso de ocitocina\npara indução do parto.","C":"Essa gestação é de 40 semanas + 5 dias. Pelo índice de Bishop ser igual a 6, indica-se uso de\nocitocina para indução do parto.","D":"Essa gestação é de 40 semanas + 1 dia. Pelo índice de Bishop ser < que 6, indica-se uso de\nprostaglandinas para amadurecimento do colo e assim indução do parto.","E":"Essa gestação é de 40 semanas + 3 dias. Pelo índice de Bishop ser igual a 6, indica-se uso de\nocitocina para condução do trabalho de parto."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-334898","number":"334898","sourceNumber":"334898","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Com base nos dados do partograma apresentado, assinale a alternativa que indica o\ndiagnóstico correto.","options":{"A":"Parto eutócico","B":"Parto taquitócico","C":"Parada secundária da descida","D":"Parada secundária da dilatação","E":"Período pélvico prolongado"},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-307122","number":"307122","sourceNumber":"307122","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Quanto ao parto vaginal eutócico, assinale a alternativa correta. Alternativas:","options":{"A":"A primeira fase clínica do parto é chamada de expulsão.","B":"O terceiro período ou 1 hora pós-parto é a fase mais importante para avaliação de hemorragia\npuerperal.","C":"Em relação à estática fetal, a insinuação pode ocorrer em situação longitudinal, apresentação\ncefálica, fletida, em occipito esquerda\ntransversa.","D":"Em pacientes multiparas, o apagamento do colo ocorre previamente à dilatação cervical.","E":"Os tempos do parto incluem, nesta ordem, descida, insinuação, rotação interna,\ndespreendimento cefálico, rotação externa e despreendimento do tronco."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-301309","number":"301309","sourceNumber":"301309","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Um parturiente com idade gestacional de 40 semanas e 4 dias, primigesta, pré-natal de\nbaixo risto sem intercorrências, AFU = 42 cm, encontra-se com colo pérvio para 8 cm ao toque\nvaginal, bolsa rota com líquido amniótico claro, polo cefálico há quatro horas mantendo-se no plano\n\n+1 de De Lee com bossa ++/4+ e assinclitismo de Litzmann. Verifica-se cardiotocografia basal com\npadrão tranquilizador. Tendo em vista o caso clínico apresentação, julgue o item a seguir. No\nassinclitismo de Litzmann, a sutura sagital encontra-se mais próxima do púbis.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-263340","number":"263340","sourceNumber":"263340","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Ao atender uma primigesta com 15 anos de idade, trazida à Emergência de um hospital\ngeral pela ambulância do Serviço de\nAtendimento Móvel de Urgência (SAMU), o plantonista\nencontra a seguinte situação: idade gestacional de 36 semanas, bolsa rota com líquido claro, 4\ncontrações uterinas fortes com duração de 40 segundos em 5 minutos de observação, colo dilatado\n10 cm, feto em apresentação cefálica em posição occipto-pública no plano +1 de De Lee,\nfrequência cardíaca fetal = 130 bpm. Nessa situação, o plantonista deve","options":{"A":"conduzir a gestante de maca até o Centro Obstétrico do mesmo hospital e realizar o parto\nnormal.","B":"realizar cesariana de urgência, mesmo sem a presença dos pais para autorização.","C":"requisitar fórcipe de alívio e finalizar o parto na própria sala de Emergência.","D":"iniciar analgesia peridural e infundir ocitocina endovenosa."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-268911","number":"268911","sourceNumber":"268911","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em relação ao mecanismo do parto, assinale a alternativa correta.","options":{"A":"O ponto de referência para as variedades de posição na deflexão de primeiro grau é o naso.","B":"Durante o período de rotação interna, o bebê pode assumir qualquer variedade de posição e o\nparto obrigatoriamente ocorrer em occipito púbico (OP).","C":"A insinuação dá-se na passagem do estreito superior da pelve, com o diâmetro biparietal fetal\nlocalizado no menor diâmetro da pelve.","D":"O assinclitismo pode ser classificado como anterior quando a sutura sagital encontra-se mais\npróxima do pube e como assinclitismo posterior quando a sutura sagital encontra-se mais próxima\ndo sacro.","E":"No decorrer do trabalho de parto, o bebê assume diferentes posições em relação à estática fetal,\ncompreendendo, nessa ordem, os tempos de descida, insinuação, rotação externa e\ndesprendimento de espáduas."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-268912","number":"268912","sourceNumber":"268912","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Uma paciente realizou seis consultas de pré-natal, com cultura de urina Streptoccocus\nagalactiae sensível à ampicilina tratada com 16\nsemanas. No momento, com 32 semanas bem\ndatada por ultrassonografia precoce, iniciou com perda de líquido claro sem grumos há três horas\nda admissão no pronto-socorro, sem dor ou enrijecimento abdominal, sem sangramento vaginal,\ncom movimentação fetal presente. Acerca do caso clínico apresentado, assinale a alternativa\ncorreta.","options":{"A":"As causas mais relacionadas à rotura prematura de membranas são infecção dentária, diabetes\nmellitus e infecção do trato urinário.","B":"A paciente deve ser internada, iniciado corticoterapia para amadurecimento pulmonar fetal,\ncolhido cultura estreptococo grupo B e programada interrupção com 34 semanas.","C":"As pacientes com bolsa rota, em sua grande maioria, iniciam trabalho de parto em até 48 horas\ndo ato da rotura.","D":"A via de parto, após a rotura prematura de membranas, é determinada por via alta, não tendo\nindicação formal ao parto vaginal.","E":"A rotura prematura de membranas diminui a chance de complicações graves, como\ndescolamento prematuro de membranas e (ou) prolapso de cordão umbilical."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-291502","number":"291502","sourceNumber":"291502","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primigesta, 41 semanas, em trabalho de parto espontâneo há 10 horas. Insinuação em\nOEA (occipto esquerda anterior). No segundo\nperíodo do parto, houve a expulsão do polo cefálico,\ncom desprendimento em OP (occipto púbico), sem intercorrências. Após ocorrer a rotação externa\nconstatou-se grande dificuldade para desprendimento das espáduas, havendo impactação do\ndiâmetro biacromial fetal, entre o púbis e o promontório maternos. O médico assistente alertou a\nequipe para a situação de emergência e solicitou auxílio de outro profissional habilitado. Realizada\nepisiotomia, mesmo assim o ombro permaneceu impactado. A primeira manobra a ser realizada\nnessa situação é","options":{"A":"hiperextensão das coxas sobre o abdome associada à pressão suprapúbica.","B":"colocar a paciente em posição de quatro apoios.","C":"realizar manobras internas para rotação fetal ou retirada do ombro posterior.","D":"recolocar a cabeça fetal para dentro do útero e proceder com a cesariana."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-263387","number":"263387","sourceNumber":"263387","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Uma gestante, no curso da 24ª semana de gestação, comparece à consulta de rotina\nde pré-natal. Informa já ter tido um aborto com\n7 semanas e um parto vaginal com 34 semanas. No\nmomento, está sem queixas e apresenta exame físico dentro da normalidade. Traz consigo\nultrassonografia gestacional que revela gestação única, tópica, com 24 semanas (corrigidas), feto\ncom apresentação cefálica, placenta anterior e com grau zero de maturidade, quantidade de líquido\namniótico e peso fetal normais para a idade gestacional, colo uterino fechado medindo 2,9 cm\n(valor de referência: > 2,5 cm). Apresenta também resultado de exame de urocultura que revela E.\ncoli com 105 unidades formadoras de colônias. O médico prescreve cefalexina e progesterona para\nessa paciente. Nesse caso, a prescrição de progesterona se justifica porque a gestante apresenta:","options":{"A":"Bacteriúria assintomática, que é um fator de risco para parto prematuro.","B":"Ultrassonografia gestacional que demonstrou um colo uterino curto.","C":"Passado de um aborto precoce por insuficiência de corpo lúteo.","D":"Histórico de parto prematuro."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-274654","number":"274654","sourceNumber":"274654","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Clinicamente, o parto propriamente dito é dividido em quatro fases ou estágios\nprincipais, sendo elas: dilatação, expulsão, estágio da placenta e período de Greenberg.\n\nConsiderando os estágios do parto e suas particularidades, é CORRETO afirmar:","options":{"A":"No período de Greenberg, há possibilidades de grandes hemorragias. Estende-se pelas\nprimeiras 4 horas após o parto.","B":"A fase da dilatação inicia-se pela dilatação progressiva do colo uterino e divide-se em fase\npassiva e ativa, sendo esta última caracterizada por um aumento na dilatação cervical.","C":"A fase da placenta começa a partir da dilatação e é encerrada pela expulsão da placenta e das\nmembranas fetais.","D":"O parto do feto se constitui na expulsão do bebê, processo iniciado a partir da dilatação\nincompleta do colo uterino."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-274667","number":"274667","sourceNumber":"274667","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Anestesia regional tem sido usada com sucesso em gestantes, permitindo que a\npaciente participe ativamente nos processos de trabalho de parto. Pode ser usada quando há\ndificuldade antecipada com intubação e preferida em mulheres com pré-eclâmpsia. No entanto,\nNÃO é indicada:","options":{"A":"Quando há dificuldade antecipada com intubação.","B":"Quando há trombocitopenia.","C":"Quando há distúrbios cardiovasculares.","D":"Quando há solicitação materna isolada."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-244491","number":"244491","sourceNumber":"244491","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A figura apresentada indica um partograma que representa um trabalho de parto","options":{"A":"distócico, com parada secundária da descida.","B":"distócico, com parada secundária da dilatação.","C":"eutócico.","D":"distócico, com período expulsivo ou pélvico prolongado.","E":"distócico, com fase ativa prolongada."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-227424","number":"227424","sourceNumber":"227424","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Acerca do manejo adequado do trabalho de parto, bem como do tratamento e da\nprevenção de suas complicações, julgue o\nitem a seguir. Uma estratégia eficaz para reduzir a\nnecessidade de administração de ocitocina exógena e a taxa de cesariana é internar a paciente em\ntrabalho de parto a partir do momento em que ela apresentar seis centímetros de dilatação cervical\ne uma frequência mínima de duas contrações a cada dez minutos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-230609","number":"230609","sourceNumber":"230609","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente deu entrada na maternidade em trabalho de parto, com dilatação de 8 cm,\napresentação cefálica fletida em OEA, evoluindo apos 2 horas para parto normal em OP, sem\nintercorrências. O ângulo e o sentido da rotação foram de:","options":{"A":"45 graus, anti-horário.","B":"45 graus, horário.","C":"90 graus, anti-horário.","D":"90 graus, anti-horário."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-158038","number":"158038","sourceNumber":"158038","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente de 26 anos de idade, G2P1C1A0, gestante de 41 semanas e um dia, é\ninternada por pós-datismo. Nega contrações e\nrefere boa movimentação fetal. Não apresentou\nintercorrências no pré-natal. Foi realizada cesárea anterior há três anos por apresentação fetal\npélvica. Ao exame físico, BFC = 142 bpm, dinâmica uterina ausente. Ao toque vaginal, colo longo,\nposterior, fechado. Acerca desse caso clínico, assinale a alternativa que indica a conduta mais\nadequada.","options":{"A":"Internação para cesariana.","B":"Ocitocina para indução de trabalho de parto, já que a paciente apresenta contraindicação ao uso\nde misoprostol.","C":"Espera do início espontâneo do trabalho de parto, com monitorização fetal por meio de\nultrassonografia com doppler, uma vez por dia.","D":"Amnioscopia para avaliação do liquido amniótico e definição da via de parto.","E":"Inserção vaginal de comprimido de misoprostol para maturação cervical após comprovação do\nbem-estar fetal."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-158002","number":"158002","sourceNumber":"158002","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente de 16 anos de idade, primigesta em trabalho de parto, não realizou pré-natal.\nNega comorbidades. Trouxe a ultrassonografia\nobstétrica que realizou há cinco dias, na qual\nconstam feto longitudinal, cefálico, dorso à esquerda, BCF = 154 bpm, placenta fúndica grau 2,\npeso fetal estimado no percentil 45 para a idade gestacional , ILA = 10 cm. O toque vaginal revelou\ncolo 70% apagado, dilatação de 5 cm, bolsa íntegra, altura do polo cefálico no plano 2 de De Lee e\nvariedade de posição occípito-esquerda transversa. Com base nesse caso clínico e nos\nconhecimentos médicos corretos, assinale a alternativa CORRETA:","options":{"A":"No momento da realização da ultrasonografia, o feto se encontrava em situação esquerda,\nposição longitudinal e apresentação cefálica.","B":"Assinclitismo seria considerado, caso a sutura sagital fetal posicionada no eixo laterolateral se\nencontrasse mais próxima ao sacro ou ao pube.","C":"Variedade de posição occipitossacra é impeditiva para o parto normal.","D":"O grau placentário representa a espessura do tecido da placenta em sua porção central e tem\nforte correlação com sofrimento fetal, se estiver com valor alterado.","E":"As bacias antropoides são as que possuem melhor prognóstico para parto normal."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-168452","number":"168452","sourceNumber":"168452","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Uma mulher com 26 anos de idade, Gesta 3 Para 1 Aborto 1, no curso de 39 semanas\ne 2 dias de gestação, e diagnóstico de\ndiabetes gestacional, é admitida para acompanhamento do\ntrabalho de parto. No exame inicial, apresenta colo dilatado para 5 cm, bolsa rota e apresentação\ncefálica no plano -1 de De Lee. Evolui bem e em 4 horas atinge a dilatação completa. Na\nassistência ao segundo período do parto, após o desprendimento do polo cefálico, constata-se\ndificuldade para liberação do ombro do nascituro. Nesse caso, como manobra a ser imediatamente\nrealizada, deve-se","options":{"A":"rodar o polo cefálico do nascituro para OP ou OS, flexioná-lo e impulsioná-lo para refazer o\ncaminho do canal de parto.","B":"empurrar o ombro anterior do feto em direção ao tórax fetal, reduzindo o diâmetro biacromial e\nliberando o ombro anterior encravado.","C":"hiperfletir e abduzir as coxas da parturiente sobre o abdome e, simultaneamente, exercer\npressão suprapúbica.","D":"colocar a mão atrás do ombro posterior do feto e rodá-lo progressivamente a 180º, de maneira\nsimilar ao movimento de um saca-rolha, de modo a desencravar o ombro anterior."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-168528","number":"168528","sourceNumber":"168528","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Secundisgesta com 27 anos de idade, na 35ª semana de gestação, comparece à\nUnidade de Pronto Atendimento com queixas\nde dor em baixo ventre e perda de líquido pela\nvagina. O exame físico evidencia: batimento cardíaco fetal de 145 bpm; dinâmica uterina de três\ncontrações de 35 segundos em 10 minutos, amniorrexe confirmada pelo exame especular. Ao\ntoque, observa-se colo esvaecido e dilatado para 4 cm. Nesse caso, a conduta médica adequada é","options":{"A":"realizar tocólise e profilaxia antimicrobiana para Streptococcus beta hemolítico por 48 horas.","B":"colher cultura para Streptococcus beta hemolítico e aguardar resulatdo para instituir\nprofilaxia.","C":"colher cultura para Streptococcus beta hemolítico e realizar profilaxia antimicrobiana por 48\nhoras.","D":"realizar a profilaxia antimicrobiana para Streptococcus beta hemolítico até o nascimento da\ncriança."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-168516","number":"168516","sourceNumber":"168516","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Uma mulher com 32 anos de idade, primigesta, na 38ª semana de gestação, deu\nentrada na maternidade com queixa de dores\nem baixo ventre e perda de líquido pela vagina, em\ngrande quantidade, há cerca de uma hora. Ao exame físico, apresentava temperatura de 36,5° C,\ndinâmica uterina de uma contração de 30 segundos em 10 minutos, saída de líquido claro pelo\norifício cervical externo do colo uterino, batimentos cardíacos fetais de 148 bpm, colo uterino\npérvio\npara 3 cm e com esvaecimento de 40%. O resultado da cardiotocografia apresentou padrão\ntranquilizador. O exame de ultrassonografia realizado na sua admissão evidenciou feto único, com\napresentação cefálica, índice de líquido amniótico = 7 cm, tônus fetal preservado, com movimentos\nrespiratótios e corpóreos presentes. A imagem a seguir apresenta partograma com a evolução do\nquadro da parturiente nas primeiras 5 horas de internamento (Conforme imagem no caderno de\nquestões). As informações apresentadas indicam a ocorrência de","options":{"A":"fase latente do trabalho de parto.","B":"parada secundária da dilatação.","C":"parada secundária da descida.","D":"parto taquitócico."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-129012","number":"129012","sourceNumber":"129012","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Assinale a alternativa que apresenta recomendação para assistência humanizada do\nparto e diminuição do número de cesarianas.","options":{"A":"Proteção do períneo, fazendo uso sistemático de episiotomia","B":"Presença de acompanhante do gênero feminino durante o trabalho de parto","C":"Ruptura artificial da bolsa amniótica (amniotomia)","D":"Utilização do partograma, que é opcional em gestação de baixo risco e obrigatório em gestação\nde alto risco","E":"Estimulação de partos vaginais mesmo após uma cesárea anterior"},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-133966","number":"133966","sourceNumber":"133966","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"No que tange ao período expulsivo do trabalho de parto, é correto afirmar que o\nprincipal inconveniente da episiotomia mediana, em\ncomparação à episiotomia mediolateral, é o (a)","options":{"A":"Reparo cirúrgico mais difícil.","B":"Maior propensão à deiscência.","C":"Elevada perda sanguínea.","D":"Maior tendência a prolongamento para laceração de 3º ou 4º graus.","E":"Maior incidência futura de incontinências urinárias."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-133977","number":"133977","sourceNumber":"133977","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente primigesta com 34 semanas e 3 dias de gestação apresenta quadro\ncompatível com o diagnóstico de ruptura\nprematura das membranas, sem nenhuma outra queixa. O\nfeto está bem, a gestante encontra-se fora de trabalho de parto e não há sinais de infecção\nmaterna ou fetal. Considerando essa situação hipotética, assinale a alternativa que apresenta o\ntratamento mais apropriado.","options":{"A":"Tratamento expectante.","B":"Tratamento expectante, a não ser que a maturidade pulmonar fetal seja confirmada.","C":"Ciclo de corticosteroides seguido por parto.","D":"Indução do trabalho de parto.","E":"Resolução da gestação por cesariana."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-111318","number":"111318","sourceNumber":"111318","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante com 40 semanas, em trabalho de parto, 8 cm de dilatação cervical, fletida em\nesquerda anterior. Na situação do texto, o ponto de referência fetal na avaliação da variedade de\nposição é:","options":{"A":"Lambda.","B":"Bregma.","C":"Fronte.","D":"Naso.","E":"Mento."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-111324","number":"111324","sourceNumber":"111324","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante com 40 semanas, em trabalho de parto, 8 cm de dilatação cervical, fletida em\nesquerda anterior. O desprendimento fetal ao final do período expulsivo no caso do texto ocorrerá:","options":{"A":"Em occipitossacro.","B":"Após rotação de 45 graus no sentido horário.","C":"Após rotação de 135 graus no sentido horário.","D":"Após rotação de 45 graus no sentido anti-horário.","E":"Após a rotação de 135 graus no sentido anti-horário."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-111263","number":"111263","sourceNumber":"111263","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O método mais utilizado para avaliação da vitalidade fetal intraparto é:","options":{"A":"Dopplerfluxometria.","B":"Cardiotocografia.","C":"Amnioscopia.","D":"Ultrassonografia.","E":"Mobilograma do feto."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-75552","number":"75552","sourceNumber":"75552","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Mulher com 35 anos de idade, G2 P1 (parto vaginal há 4 anos), 41 semanas e 2 dias\nde idade gestacional (corrigida por\nultrassonografia realizada no primeiro trimestre), vem à Unidade\nBásica de Saúde para mais uma consulta de pré-natal. Refere dor nas costas e cansaço. Nega\ncontrações, disúria, perda líquida ou sangramento vaginal. Relata boa movimentação fetal. Ao\nexame: pressão arterial = 100 x 60 mmHg, peso = 68 kg, altura uterina = 34 cm, batimentos\ncardiofetais = 140 bpm, ausência de dinâmica uterina. Toque vaginal = colo grosso, centrado, 2 cm\nde dilatação, apresentação cefálica. A conduta indicada é:","options":{"A":"Dar alta do pré-natal e orientar a paciente a procurar a Maternidade quando apresentar sintomas\ndo trabalho de parto.","B":"Encaminhar para a Maternidade para avaliação da vitalidade fetal e indução do parto.","C":"Orientar controle da movimentação fetal e aguardar o trabalho de parto espontâneo.","D":"Agendar nova consulta em 7 dias e orientar sinais e sintomas do trabalho de parto.","E":"Solicitar ultrassonografia obstétrica e agendar nova consulta em 7 dias."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-75500","number":"75500","sourceNumber":"75500","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primigesta, com 39 semanas de gestação, encontra-se em trabalho de parto há seis\nhoras. Nas últimas três horas, manteve a\ndilatação cervical de 6 cm, sem que houvesse\nmodificações no colo uterino, que se encontra medianizado e esvaecido em 50%. Quando a\npaciente foi internada, apresentava três contrações moderadas em 10 minutos. Nas últimas duas\nhoras, tem apresentado dinâmica uterina de duas contrações fracas em 10 minutos. A descida do\npolo cefálico vem se processando de forma progressiva e agora observa-se que o polo cefálico está\nno plano zero de De Lee. Com base no quadro clínico, o diagnóstico e a conduta são:","options":{"A":"Fase ativa prolongada, distócia funcional; deambulação e, se necessário, ocitocina.","B":"Fase de latência prolongada; administrar ocitocina e realizar amniotomia.","C":"Período pélvico prolongado; realizar amniotomia e administrar ocitocina.","D":"Desproporção cefalopélvica relativa; indicar operação cesariana.","E":"Parada secundária de descida; indicar operação\ncesariana."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-75509","number":"75509","sourceNumber":"75509","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primigesta com 30 anos de idade, 38 semanas de gestação e pré-natal sem\nintercorrências, é admitida na Maternidade em\ntrabalho de parto. Ao exame físico na admissão,\npressão arterial = 100 x 60 mmHg, altura uterina = 35 cm, dinâmica uterina - 2 contrações em 10\nminutos, frequência cardíaca fetal = 140 bpm. Ao toque vaginal, colo fino, 3 cm de dilatação,\napresentação cefálica, bolsa íntegra. (VER IMAGEM). Analisando a evolução do trabalho de parto,\nconforme o\n\npartograma mostrado acima, a hipótese diagnóstica e a conduta correta, após 10 horas de\nobservação, são, respectivamente:","options":{"A":"Fase ativa prolongada; administrar ocitocina.","B":"Parada secundária da descida; realizar cesariana.","C":"Parada secundária da dilatação; realizar cesariana.","D":"Parada secundária da dilatação; administrar ocitocina.","E":"Parada secundária da descida; realizar analgesia\n(bloqueio combinado)."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-137697","number":"137697","sourceNumber":"137697","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Uma paciente de 23 anos de idade é internada na maternidade com rotura prematura\nde membranas na 29ª semana de gestação.\nEncontra-se assintomática, afebril, normotensa,\nfrequência cardíaca = 76 bpm, ainda referindo perda de líquido amniótico claro, sem grumos e sem\nodor desagradável. Leucograma com 9 500 leucócitos/mm3 (valor de referência: 3 800 a 10\n600/mm3 ), 2 bastões; Proteína C Reativa = 0,5 mg /dL (valor de referência = 0,3 a 0,5 mg /dL). A\nultrassonografia obstétrica mostrou feto com 29 semanas de gestação, com frequência cardíaca\nfetal de 140 bpm, maior bolsão de líquido amniótico de 6 centímetros. Qual das condutas abaixo é\nadequada para essa paciente?","options":{"A":"Tocólise com nifedipina com duração até a 34ª semana de gestação.","B":"Corticoterapia com betametasona repetida semanalmente até a 34ª semana de gestação","C":"Sulfato de magnésio para a neuroproteção fetal, administrado no momento da internação da\npaciente e repetido na 34ª semana de gestação.","D":"Antibioticoterapia profilática para postergação da gestação com duração até 34ª semana de\ngestação.","E":"Rastreio para estreptococo beta-hemolítica, feito no amomento da internação e repetido na 34ª\nsemana de gestação."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-137703","number":"137703","sourceNumber":"137703","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Um paciente de 24 anos, primigesta, vai à consulta médica pré-natal no posto de\nsaúde. Nessa consulta pré-natal, o médico\ncalculou a idade gestacional considerando sua primeira\nultrassonografia de 12 semanas, concluindo que está com 41 semanas e 6 dias de gestação. Ao\nexame pélvico, observou colo uterino de consistência amolecida, posterior, apagado 30%, orifício\nexterno fechado, apresentação alta e móvel. Na manobra de palpação fetal (de Leopold-Zweifel),\npercebeu-se que havia boa mobilidade fetal, sinalizando quantidade normal de líquido amniótico.\n\nTemendo o pós-datismo, o médico encaminhou a paciente para a internação na Maternidade. Lá\nchegando, foi submetida à cardiotocografia, cuja imagem é reproduzida abaixo (VER IMAGEM).\nQual a conduta que deve ser proposta para essa paciente?","options":{"A":"Cesariana devido ao padrão não tranquilizador da cardiotocografia.","B":"Amadurecimento cervical com misoprostol.","C":"Indução eletiva do parto com ocitocina.","D":"Descolamento da bolsa amniótica.","E":"Dilatação cervical e amniotomia."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-138388","number":"138388","sourceNumber":"138388","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primigesta de 25 anos de idade procura a Maternidade pelo início do trabalho de parto\nàs 13 horas e sua evolução está registrada\nno partograma. (VER IMAGEM) A paciente completa o\nprimeiro período do parto às 18h30min. O segundo período já durava 45 minutos, quando o feto\ncomeçou a apresentar desacelerações tipo II. Qual o diagnóstico desse caso e a conduta obstétrica\nmais apropriada?","options":{"A":"Período pélvico prolongado; fórcipe para distocia de rotação.","B":"Parto taquitócico; tocólise aguda com terbutalina subcutânea.","C":"Parada secundária da descida; operação cesariana por desproporção cefalopélvica.","D":"Fase ativa prolongada; administração de ocitocina para aumentar as metrossístoles.","E":"Parada secundária da dilatação; orientação para a paciente ficar em decúbito lateral esquerdo\npara coordenar as metrossístoles."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-138403","number":"138403","sourceNumber":"138403","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Mulher multípara, com gestação de 34 semanas e um dia, chega à maternidade com\nqueixa de dor em cólica e endurecimento do abdome. Ao exame: presença de contrações uterinas\nfrequentes (uma a cada cinco minutos), colo uterino com 50% de esvaecimento e 1cm de dilatação,\nvitalidade fetal preservada. A conduta correta a ser adotada para a paciente é","options":{"A":"administrar terbutalina associada à corticoesteróide.","B":"iniciar partograma e acompanhar evolução do\ntrabalho de parto.","C":"administrar indometacina e iniciar antibioticoterapia\npor via endovenosa.","D":"guardar repouso em observação e reavaliar o quadro após duas horas.","E":"administrar nifedipina sem associação de\ncorticoesteróide."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-30962","number":"30962","sourceNumber":"30962","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Acerca da anatomia da pelve feminina e da fisiologia da gestação, julgue o item que se\nsegue. O diâmetro interespinhoso, representado por um plano que se estende de uma espinha\nisquiática à outra, é importante relação pélvica que determina se há ou não passagem suficiente\npara a descida e a extensão da cabeça do feto durante o trabalho de parto.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-30985","number":"30985","sourceNumber":"30985","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O parto resulta de complexa relação e interação de fatores maternos, fetais e\nplacentários. Cuidados na assistência ao parto e\npuerpério são fundamentais na redução dos\níndices de mortalidade materna e perinatal. Com referência a esse tema, julgue o item seguinte. A\nutilização de prostaglandinas, E2 (dinoprostone) e E1 (misoprostol), na maturação cervical,\nassocia-se claramente à redução do intervalo entre o início da indução e o parto, bem como na\nredução dos índices de cesarianas quando comparado a casos nos quais se utilizou somente a\nocitocina.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-138680","number":"138680","sourceNumber":"138680","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente, com 25 anos de idade, secundigesta, com parto cesáreo anterior (G2P1C1),\npré-natal sem intercorrências, foi internada\nem trabalho de parto e apresenta evolução de acordo\ncom partograma, apresentado abaixo. Na décima hora de evolução, apresenta atividade uterina\nregular de 5 contrações/45 segundos/10 minutos/fortes e batimentos cardiofetais de 150 bpm (VER\nIMAGEM). Analisando o partograma, qual é o diagnóstico e a conduta para o caso?","options":{"A":"Parada secundária da descida e fórceps.","B":"Parada secundária da dilatação e ocitocina.","C":"Parada secundária da dilatação e fórceps.","D":"Parada secundária da descida e cesárea.","E":"Período expulsivo prolongado e cesárea."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-138739","number":"138739","sourceNumber":"138739","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante de 39 semanas, com quatro gestações e três partos, foi internada no\n\npré-parto com dinâmica uterina de três contrações fortes em 10 minutos, cervicodilatação de 5 cm,\nbolsa íntegra e cardiotocografia com padrão ativo. Em uma hora evoluiu para 7 cm de dilatação,\napresentando quatro contrações fortes em 10 minutos. Qual deve ser a indicação de analgesia\nobstétrica para essa paciente?","options":{"A":"Bloqueio de pudendo no segundo período do parto, visto que a paciente é multípara.","B":"Bloqueio peridural com anestésico local e cateter para complementação anestésica\nsubsequente.","C":"Bloqueio raquidiano em sela com anestésico local.","D":"Analgesia endovenosa com meperidina.","E":"Não há necessidade de analgesia e o parto ocorrerá rapidamente se considerarmos a evolução\ndo trabalho de parto na última hora."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-22173","number":"22173","sourceNumber":"22173","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Acerca de assistência do parto, julgue o seguinte item. Durante a indução e condução\ndo trabalho de parto com ocitocina, a gestante\ndeve ser hidratada com solução de Ringer lactato.\nQuando infundida em altas doses, a ocitocina tem efeito antidiurético e, associada a soro glicosado,\npode acarretar quadro grave de intoxicação hídrica.","options":{"A":"certo","B":"errado"},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-351625","number":"351625","sourceNumber":"351625","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O diagnóstico de trabalho de parto (TP) tem como critérios clássicos as contrações\nuterinas dolorosas e regulares em tempo (a cada 5\nminutos ou menos), em intensidade (fortes) e\nem duração (50 a 60 segundos) e ainda colo uterino com apagamento superior a 50%,\ncentralizando e com 3 a 4 cm de dilatação. Fonte: Assistência aos quatro períodos do parto e risco\nhabitual. Protocolo Febrasgo/Obstetrícia. N° 101. 2018. Sobre as fases clínicas do parto é\nCORRETO afirmar que:","options":{"A":"O período expulsivo se inicia quando a dilatação é total.","B":"O primeiro período divide-se em três fases.","C":"O quarto período corresponde ao desprendimento fetal.","D":"A dequitação ocorre durante o quarto período."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-368154","number":"368154","sourceNumber":"368154","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente de 30 anos de idade, G1 P0 A0, está com 39s 5d de gestação e chega à\nmaternidade relatando contrações uterinas dolorosas. Nega perda de líquido ou sangramento\ngenital. Ao ser examinada, sua PA é de 120x80 mmHg e FC 89 bpm. As contrações uterinas estão\nocorrendo a cada 4 minutos, e o BCF é 148 bpm. Ao toque vaginal, o colo está com 3 cm de\ndilatação e 90% apagado, a bolsa está íntegra e o polo cefálico está alto. Não desejou analgesia\ndurante o acompanhamento do trabalho de parto. Analise o padrão de dilatação do colo uterino e\nda descida do polo cefálico a seguir e assinale a alternativa correta.","options":{"A":"Essa distocia é diagnosticada quando a expulsão do feto ocorre em um período de 4h ou menos.","B":"Essa distocia costuma estar relacionada à contratilidade uterina deficiente.","C":"Estava indicada cesariana uso de fórceps na 6ª hora de avaliação.","D":"Trata-se de um caso de parada secundária da descida."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-320432","number":"320432","sourceNumber":"320432","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"?O parto pré-termo é aquele que ocorre em até 36 semanas e 6 dias de idade\ngestacional, excluindo o período considerado\ncomo de abortamento. Sua ocorrência é grande em\ntodo mundo; no Brasil, está em torno de 11%. As complicações da prematuridade são a maior\ncausa de morte neonatal. São três as principais causas de partos pré-termo: o trabalho de parto\nprematuro, a rotura prematura pré-termo das membranas ovulares e a prematuridade terapêutica\n(quando alguma condição mórbida materna e/ou fetal ocasiona a antecipação do parto).? - Manual\nde gestação de alto risco [recurso eletrônico] / Ministério da Saúde, Secretaria de Atenção Primária\nà Saúde. Departamento de Ações Programáticas. ? Brasília: Ministério da Saúde, 2022. Avalie as\nafirmativas abaixo: I. O uso de progesterona via vaginal é recomendado para mulheres que tiveram\nparto prematuro espontâneo anterior, independentemente da medida de colo uterino com o objetivo\nde prevenir o parto pré-termo II. A administração de corticosteroides tem como resultado acelerar a\nmaturação pulmonar fetal e reduzir hemorragia periventricular porém aumenta o risco de\nenterocolite necrosante. III. A nifedipina, que tem sido recomendada como primeira escolha na\ntocólise, cujo objetivo é evitar o parto no período de 48 horas, possivelmente, por até 7 dias. Esse\nganho de tempo é considerado benéfico para garantir tempo adequado para administração de\ncorticosteroide e/ou transferência da gestante para uma instituição com maiores recursos antes que\nocorra o parto prematuro IV. A antibioticoprofilaxia para estreptococo do grupo B está indicada\napenas nos casos de partos pré-termo associados a rotura prematura pré-termo das membranas\novulares, sendo dispensada nos casos com membranas integras. Sobre a prematuridade, é correto\no que se afirma em:","options":{"A":"I apenas.","B":"I e III apenas.","C":"I, II e III apenas.","D":"III apenas.","E":"I, II, III e IV."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-337643","number":"337643","sourceNumber":"337643","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O trabalho de parto consiste em uma série de contrações ritmadas e progressivas do\nútero que gradualmente movem o feto através\nda parte inferior do útero (colo do útero) e do canal\nvaginal (vagina) para o mundo exterior. A Organização Mundial da Saúde (OMS) desenvolveu uma\nclassificação das práticas comuns na condução do parto normal, orientando para o que deve e o\nque não deve ser feito no processo do parto. Esta classificação foi baseada em evidências\ncientificas concluídas através de pesquisas feitas no mundo todo. Sobre as boas praticas\nconsideradas em obstetrícia, analise as afirmativas a seguir: I- A utilização da cardiotocografia\ncomo teste de rotina a ser realizado na admissão da paciente mostrou inquestionáveis benefícios\nao prognóstico fetal. II- Não há evidências de que a utilização rotineira de enemas e de tricotomia\nperineal durante o trabalho. III- O número de avaliações das condições do colo do útero não é\nestabelecido na literatura; porém, preconiza-se que seja realizada a quantidade mínima necessária\npara que se tenham informações sobre a evolução do trabalho de parto, sem que se aumente o\nrisco de infecções. IV- Antes da analgesia intraparto é recomendado evitar o toque vaginal, com\nobjetivo de evitar estimulação das contrações uterinas. Estão CORRETAS as afirmativas:","options":{"A":"I, II e IV apenas.","B":"II, III e IV apenas.","C":"I e IV apenas.","D":"II e III apenas."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-336295","number":"336295","sourceNumber":"336295","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante com 20 semanas de idade gestacional, terceira gestação com antecendente\nde prematuridade com dois partos vaginais de 34\nsemanas e 30 semanas, respectivamente, vem\npara consulta de pré-natal de rotina sem queixas. USG gestacional solicitado na última consulta\ncom comprimento do colo de 40 mm. Exame físico normal. Nesse momento, a melhor conduta é:","options":{"A":"Nifedipina","B":"Carbonato de cálcio.","C":"Progesterona","D":"Cerclagem"},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-345740","number":"345740","sourceNumber":"345740","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Na avaliação do colo uterino para predição de prematuridade, a idade gestacional mais\nadequada e o tipo de ultrassom são, respectivamente:","options":{"A":"20 a 24 semanas, transvaginal.","B":"16 a 20 semanas, transvaginal.","C":"12 a 16 semanas, transvaginal.","D":"20 a 24 semanas, pélvico."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-345742","number":"345742","sourceNumber":"345742","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Durante a condução de um trabalho de parto, após a saída do pólo cefálico, o feto\nrealiza a rotação externa, e o Obstetra nota\ndistocia de bisacrominal. A primeira manobra que deve\nser tentada nesse momento é:","options":{"A":"Hamilton.","B":"McRoberts.","C":"Credé.","D":"Taxe."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-291623","number":"291623","sourceNumber":"291623","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente de 34 anos, GI P0 A0, idade gestacional de 24,2 semanas comparece à\nconsulta de pré-natal trazendo resultado de\nultrassonografia morfológica realizada com 23 semanas\nde gestação. Neste exame observou-se biometria fetal compatível com a idade gestacional, líquido\namniótico com volume normal, placenta corporal anterior, ausência de alterações morfológicas do\nfeto e colo com 14 mm de comprimento. Sem queixas na consulta, exame físico com ausência de\ncontrações, colo fechado e ausência de perdas vaginais. Assinale a alternativa quanto a prevenção\nde prematuridade nessa paciente.","options":{"A":"manter acompanhamento pré-natal habitual pois a paciente não apresenta risco aumentado de\nprematuridade.","B":"indicar cerclagem do colo uterino de emergência.","C":"internar a paciente e iniciar tocólise com nifedipina imediatamente.","D":"prescrever progesterona por via vaginal e manter até 36 semanas, orientar repouso e\nabstinência sexual.","E":"conduta expectante e, caso a paciente entre em trabalho de parto prematuro, prescrever agente\ntocolítico e realizar cerclagem."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-291933","number":"291933","sourceNumber":"291933","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em relação à apresentação cefálica durante o Trabalho de Parto (TP), assinale a\nalternativa INCORRETA:","options":{"A":"A insinuação fetal depende da forma da bacia materna, sendo a preferência pelos diâmetros\ntransversos é predominantemente no tipo ginecoide e no platipeloide.","B":"A rotação anterior do polo fetal ocorre até o final do 1o período e até mais cedo nas\nmultíparas.","C":"Na apresentação occiptossacra surge primeiro a grande fontanela sendo que a progressão\nocorre em hiperflexão até que o nariz se\nencontre sob o arco púbico.","D":"A rotação manual da cabeça fetal para a posição anterior, realizada durante a contração uterina\ne indicada quando o colo uterino apresenta\ndilatação completa ou após espera de 1 a 2 horas,\npoderá ser bem- sucedida em aproximadamente 90% dos casos."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-305013","number":"305013","sourceNumber":"305013","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Considere que uma paciente de 28 anos de idade, G1 PV0 A0, com 40 semanas e seis\ndias de gestação, chega à maternidade relatando contrações uterinas dolorosas. Nega perda de\nlíquido ou sangramento genital. Ao ser examinada, sua PA é de 120 x 80 mmHg e a FC é de 86\nbpm. As contrações uterinas estão ocorrendo a cada cinco minutos e o BCF é 140 bpm. Ao toque\nvaginal, o colo está com 3 cm de dilatação e 50% apagado, a bolsa está íntegra e o polo cefálico\nestá alto. Não desejou analgesia durante o acompanhamento do trabalho de parto. Analise o\npadrão de dilatação do colo uterino e da descida do polo cefálico a seguir e assinale a alternativa\nCORRETA.","options":{"A":"Trata-se de um caso de parada secundária da descida.","B":"Essa distócia é diagnosticada por dois toques sucessivos, com intervalo de duas horas ou mais,\nestando a paciente em trabalho de parto ativo.","C":"É frequente nesse tipo de distocia a contratilidade uterina deficiente.","D":"Estava indicado uso de fórceps na sexta hora de avaliação."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-306722","number":"306722","sourceNumber":"306722","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Marque a incorreta:","options":{"A":"A ativação da contratilidade uterina é caracterizada por modificações cervicais e pela descida do\nfundo uterino.","B":"Durante a gestação, a contratilidade uterina possui quatro fases: quiescência, ativação,\nestimulação e involução","C":"A expulsão tem início com a dilatação completa e se encerra com a saída do concepto.","D":"A dilatação cervical, nas multíparas, tem velocidade média de 3 cm/h"},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-314061","number":"314061","sourceNumber":"314061","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em relação ao trabalho de parto, analisar os itens abaixo: I. O terceiro estágio do\ntrabalho de parto vai da dilatação cervical\ncompleta até a expulsão do feto. II. Um segundo estágio\nnormal dura menos de duas horas em nulíparas. III. O quarto estágio do trabalho de parto tem inicio\napós a expulsão do bebê e termina com a expulsão da placenta e das membranas. Está(ão)\nCORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e II.","D":"Somente os itens I e III.","E":"Todos os itens."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-313324","number":"313324","sourceNumber":"313324","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"MMGT, 25 anos, deu entrada no hospital, 39 semanas de gestação, com relatos de\ncontrações uterinas a cada 5 minutos, de\nacordo com seu controle e do marido. O Ginecologista de\nplantão decide mantê-la em observação, e verifica a presença de 4 cm de dilatação ao toque.\n\nDurante o exame, o médico decide utilizar o sonar Doppler. Sobre esse recurso, temos que: I-\nDeve-se realizar a ausculta antes, durante e\nimediatamente após uma contração, por pelo menos 1\nminuto e a cada 30 minutos, registrando como uma taxa única; II- O médico deve palpar o pulso\nmaterno se alguma anormalidade for suspeitada para diferenciar os batimentos fetais e da mãe; III-\nDeve-se registrar acelerações e desacelerações se ouvidas. Dos itens acima:","options":{"A":"Apenas o item II está correto.","B":"Apenas os itens I e II estão corretos.","C":"Apenas os itens I e III estão corretos.","D":"Apenas os itens II e III estão corretos.","E":"Todos os itens estão corretos."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-314069","number":"314069","sourceNumber":"314069","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Indução do trabalho de parto, ou simplesmente indução do parto, é a estimulação\nartificial da dinâmica uterina antes do\ninicio espontâneo do trabalho de parto com objetivo de atingir\nparto vaginal. A indução do parto é indicada quando os riscos maternos e/ou fetais de manter a\ngestação são superiores aos benefícios, na ausência de contraindicação ao parto vaginal. Todas as\ncontraindicações ao parto por via vaginal são contraindicações à indução do parto. São\ncontraindicações à indução do trabalho de parto: l. Infecção herpética passada. II. Placenta previa\nou vasa prévia. III. Carcinoma invasivo de colo uterino. IV. Incisão uterina transmural prévia\n(miomectomia). Está(ão) CORRETO(S):","options":{"A":"Todos os itens.","B":"Somente os itens II e IV.","C":"Somente os itens I, II e III.","D":"Somente os itens II, III e IV.","E":"Nenhum dos itens."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-266387","number":"266387","sourceNumber":"266387","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"As fases clínicas do parto são processos fisiológicos e dividem-se em quatro períodos.\nFazem parte desses períodos as seguintes\nfases, EXCETO:","options":{"A":"Fase de contratilidade.","B":"Fase de dilatação.","C":"Fase de expulsão.","D":"Fase de secundamento."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-283912","number":"283912","sourceNumber":"283912","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primigesta com 30 semanas de gestação é internada em franco trabalho de parto. Ao\nexame: pressão arterial de 120/80 mmHg, 4 contrações em 10 minutos, bcf de 155 bpm, toque\nvaginal com colo fino, 8 cm de dilatação, apresentação cefálica e bolsa íntegra. São condutas\nadequadas para o caso, EXCETO:","options":{"A":"Uso de sulfato de magnésio intravenoso.","B":"Uso de antibioticoprofilaxia intravenosa.","C":"Ausculta intermitente dos batimentos cardiofetais durante o trabalho de parto.","D":"Realização de episiotomia para evitar tocotraumatismo.","E":"Realização de tocólise e corticoterapia."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-234414","number":"234414","sourceNumber":"234414","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em relação à fisiologia das contrações uterinas, assinale a alternativa INCORRETA:","options":{"A":"A intensidade de cada contração é dada pela elevação que ela determina na pressão amniótica,\nacima do tônus uterino.","B":"A atividade uterina é o produto da intensidade das contrações pela sua frequência, sendo\nexpressa em unidades Montevidéu.","C":"O trabalho uterino corresponde à soma das intensidades de todas as contrações responsáveis\npela tarefa de dilatar o colo uterino, por\nexemplo.","D":"As contrações de Braxton-Hicks resultam de contrações sincrônicas parcialmente propagadas,\nde baixa frequência (8-10)/h, porém com tônus\npermanecendo entre 2 e 14mmHg."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-227084","number":"227084","sourceNumber":"227084","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A distócia de ombros é uma das mais temidas complicações obstétricas. São manobras\nreconhecidas e eficazes para resolução dessa condição, EXCETO:","options":{"A":"Pressão supra-púbica.","B":"Rotação sem sentido anterior ao feto do ombro superior.","C":"Hiperflexão dos membros inferiores.","D":"Pressão aplicada em fundo uterino."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-227085","number":"227085","sourceNumber":"227085","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O adequado acompanhamento pré-natal é imprescindível para o bom desfecho\ngestacional. Durante esse período é possível se identificar pacientes com risco aumentado de\ntrabalho de parto pré-termo e muitas dessas pacientes podem se beneficiar com o uso de\nprogesterona micronizada. São pacientes que se beneficiam com o uso da progesterona para\nprevenção do trabalho de parto pré-termo:","options":{"A":"Pacientes com gestação gemelar e gestantes com mais de 40 anos.","B":"Pacientes com história de aborto de repetição e pacientes que apresentaram sangramento no\nprimeiro trimestre gestacional.","C":"Pacientes com história prévia de trabalho de parto pré-termo e com colo uterino curto medido ao\nultrassom.","D":"Pacientes com gestação gemelar e pacientes com macrossomia fetal diagnosticada."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-227091","number":"227091","sourceNumber":"227091","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Para o adequado acompanhamento do trabalho de parto, é imperativa a boa formação\ndo profissional que assiste a parturiente, assim\ncomo a boa infraestrutura do local em que se dará o\nacompanhamento do processo e do parto propriamente dito. São consideradas boas práticas para\no acompanhamento do trabalho de parto, EXCETO:","options":{"A":"Usar criteriosamente a ocitocina venosa em detrimento de sua administração de rotina.","B":"Oferecer métodos não-farmacológicos de alívio da dor, assim como analgesia farmacológica se\ndemandada pela paciente.","C":"Permitir presença contínua de acompanhante de livre escolha da paciente.","D":"Manter reavaliações seriadas e constantes da dilatação cervical através do toque vaginal."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-232122","number":"232122","sourceNumber":"232122","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante de 27,3 semanas, GII PI A0, informa que na gestação anterior teve parto\nnormal na 28ª semana. Chega à maternidade\napresentando 3 contrações de 40 segundos em 10\nminutos. Altura uterina = 26 cm. Batimento cardíaco fetal = 140 bpm. Colo dilatado 2 cm, apagado,\napresentação cefálica, bolsa íntegra. Cardiotocografia mostrando feto com boa vitalidade. Assinale\na alternativa que apresenta a melhor opção de medicações que devem ser iniciadas imediatamente\npara essa paciente:","options":{"A":"Clindamicina, atosiban, progesterona.","B":"A Penicilina cristalina, nifedipina, betametasona.","C":"Penicilina cristalina, nifedipina, sulfato de magnésio.","D":"Ampicilina, terbutalina, progesterona.","E":"Ampicilina, atosiban, sulfato de magnésio."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-227092","number":"227092","sourceNumber":"227092","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Entender os períodos do trabalho de parto e sua fisiologia são conhecimentos\nessenciais para a boa assistência obstétrica.\nTodas as condutas devem ser norteadas no intuito de\npermitir a evolução fisiológica do processo e na intervenção somente quando oportuna e\ncomprovadamente eficaz. São condutas adequadas para assistência ao trabalho de parto,\nEXCETO:","options":{"A":"Orientar a paciente a adotar a postura em que se sinta mais confortável durante todo o\nprocesso.","B":"Permitir ambiente seguro e privado para a paciente durante o trabalho de parto.","C":"Verticalizar a paciente durante o período expulsivo e realizar manobras de proteção perineal se\nnecessárias.","D":"Realizar episiotomia rotineira em primigestas logo que o feto atinja o plano +2 de DeLee."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-243010","number":"243010","sourceNumber":"243010","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Com relação ao uso da episiotomia no parto vaginal, assinale a alternativa CORRETA:","options":{"A":"é indicado, rotineiramente, em todos os partos vaginais.","B":"a episiotomia mediana é considerada atualmente como o padrão?ouro.","C":"o uso da episiotomia mediana está associado ao maior risco de lacerações graves.","D":"a episiotomia está associada a melhores escores de Apgar quando utilizada de forma rotineira.","E":"observa?se uma tendência mundial no aumento da incidência dos partos com auxílio da\nepisiotomia."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-246379","number":"246379","sourceNumber":"246379","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Uma gestante encontra-se em trabalho de parto que não está tendo uma evolução\nsatisfatória devido à incoordenação da atividade\nuterina. Nesta situação, a medida NÃO indicada é:","options":{"A":"Ocitocina venosa.","B":"Analgesia peridural.","C":"Tocolíticos.","D":"Amniotomia."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-246755","number":"246755","sourceNumber":"246755","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primípara que dilata 2 cm em 6 horas de evolução de trabalho de parto:","options":{"A":"Fase de desaceleração prolongada.","B":"Fase latente prolongada.","C":"Parada do trabalho de parto.","D":"Trabalho de parto normal.","E":"Fase de desaceleração rápida."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-220297","number":"220297","sourceNumber":"220297","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em relação às distocias do parto, é INCORRETO afirmar que:","options":{"A":"No início do trabalho de parto, a defleção da cabeça condiciona apresentações de 1º, 2º e 3º\ngraus, respectivamente, apresentação de fronte, bregma e face.","B":"Na apresentação de face, o prognóstico é mais reservado pela facilitação de procidência do\ncordão e, em casos de circulares\ncervicais, elas podem ser comprimidas entre o dorso e o occipital\nfetais.","C":"Na apresentação córmica, o grande eixo fetal não coincide com a direção da coluna vertebral\nmaterna, cruzando-a em ângulo reto, e tem incidência de 1:300 partos.","D":"O parto espontâneo poderá ocorrer em apresentações córnicas, em feto diminuto e sobretudo,\nquando morto e macerado, mais facilmente em\nmultíparas e é denominado mecanismo\nconduplicato corpore."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-199497","number":"199497","sourceNumber":"199497","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em relação à contratilidade uterina, assinale a alternativa INCORRETA:","options":{"A":"As contrações de Braxton-Hicks de até 2 contrações/h, com tônus de 3 a 8mmHg, resultam mais\nda soma de metrossístoles assincrônicas parcialmente propagadas, do que de atividade bem\ncoordenada.","B":"No período de dilatação, as contrações atingem intensidade de 30mmHg para alcançar ao final\nvalores de 40mmHg.","C":"No parto normal, a onda contrátil tem sua origem em dois marca-passos, direito e esquerdo,\nsituados próximos das implantações tubárias.","D":"Durante a gravidez, o útero não está inativo, porém com atividade bastante reduzida e irregular,\natividade essa mantida pelo chamado bloqueio estrogênico."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-199558","number":"199558","sourceNumber":"199558","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Após a indução da analgesia para condução do trabalho de parto, observa-se\nhipotensão arterial importante. Qual das condutas abaixo não tem indicação?","options":{"A":"Checar o decúbito da paciente.","B":"Expansão volêmica.","C":"Uso de vasopressores.","D":"Uso de uterotônicos."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-199563","number":"199563","sourceNumber":"199563","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Na investigação da amniorrexe prematura é utilizado o teste do pH vaginal. Neste teste\no resultado falso-positivo pode ocorrer devido\na presença de:","options":{"A":"Tricomoníase.","B":"Cândida albicans.","C":"Lactobacilos.","D":"Vaginite citolítica."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-212906","number":"212906","sourceNumber":"212906","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em uma cesariana são sete as camadas que devem ser seccionadas (ou\ndivulsionadas) até se atingir o bebê. Como se denomina a quinta camada?","options":{"A":"Fáscia muscular (aponeurose).","B":"Músculo reto-abdominal.","C":"Peritônio visceral.","D":"Peritônio parietal","E":"Miométrio."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-212944","number":"212944","sourceNumber":"212944","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Assinale o teste utilizado para diagnóstico da rotura prematura de membranas, que é\npositivo quando há aumento do pH vaginal?","options":{"A":"Cristalização.","B":"Brossen Gordon.","C":"Células orangiófilas.","D":"Iannetta.","E":"Fenol vermelho."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-174397","number":"174397","sourceNumber":"174397","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"D.S.F. 32 anos, GII PI (parto normal) A0. DUM 09/03/2017 e a ultrassonografia de\nprimeiro trimestre mostrou idade gestacional\ncompatível com a DUM. Pré-natal sem intercorrências,\ncartão de pré-natal completo (não há registro de pesquisa de estreptococos do grupo B). Chega\nhoje (17/11/2017) na maternidade apresentando perda abundante de líquido que o exame\nespecular confirma tratar-se de perda de líquido amniótico. As contrações estão ausentes, não há\nfebre ou taquicardia materna e a cardiotocografia demonstrou boa vitalidade fetal. A altura de fundo\nuterino é compatível com o tempo de gravidez e a ultrassonografia realizada na véspera mostrava\num feto em apresentação cefálica. A conduta adequada é:","options":{"A":"Internação para indução do parto. Recomendada profilaxia contra estreptococos do grupo B.","B":"Internação para conduta expectante. Prescrever corticoide para maturação pulmonar, vigilância\nda vitalidade fetal e controle de infecção, além\nde pesquisa de estreptococos do grupo B.","C":"Internação para tocólise. Recomendada profilaxia contra estreptococos do grupo B.","D":"Internação para cesariana. Não há recomendação para profilaxia contra estreptococos do grupo\nB.","E":"Internação, prescrever corticoide para maturação pulmonar, iniciar profilaxia contra\nestreptococos do grupo B e após 48 horas realizar indução do parto."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-172815","number":"172815","sourceNumber":"172815","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O risco de trabalho de parto prematuro aumenta conforme venha ocorrer alterações no\ncolo uterino observadas no exame ultrassonográfico. O sinal ecográfico chamado de afunilamento\nrepresenta:","options":{"A":"Herniação das membranas para o interior do orifício interno dilatado.","B":"Dilatação dos orifícios interno e externo do canal endocervical.","C":"Redução da espessura do colo aferida ao nível do orifício interno.","D":"Presença de vasos sanguíneos sobre as membranas que recobrem o orifício interno cervical."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-172771","number":"172771","sourceNumber":"172771","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Na assistência ao trabalho de parto pode-se realizar a manobra de McRoberts, que\nconsiste na hiperflexão e abdução das coxas, com o consequente deslocamento cranial da sínfise\npúbica e retificação da lordose lombar. Essa manobra é útil na seguinte situação:","options":{"A":"Situação transversa.","B":"Apresentação pélvica.","C":"Variedade occipito-posterior.","D":"Distocia de ombro."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-188036","number":"188036","sourceNumber":"188036","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Durante o trabalho de parto, a pressão do polo cefálico sobre o colo uterino, estimula as\nterminações nervosas, levando a liberação de ocitocina pelo Hipotálamo. Trata-se aqui de que\nreflexo?","options":{"A":"De Fergusson-Harris.","B":"Da ocitocina.","C":"Da prostaglandina.","D":"De Moro.","E":"De Woods."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-188037","number":"188037","sourceNumber":"188037","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A contratação uterina é resultado da interação de proteínas musculares actina e\nmiosina. O tríplice gradiente descendente que é de grande importância na propagação das\ncontrações uterinas, envolve:","options":{"A":"localizacão, frequência e duração;","B":"localização, duração e intensidade;","C":"frequência, propagação e intensidade;","D":"propagação, posição e frequência;","E":"posição, frequência e propagação."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-187488","number":"187488","sourceNumber":"187488","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Entre os itens abaixo, qual seria indicação absoluta de cesariana:","options":{"A":"Apresentação pélvica.","B":"Placenta prévia total.","C":"Condilomatose genital ativa.","D":"HIV.","E":"Descolamento prematuro da placenta."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-187430","number":"187430","sourceNumber":"187430","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Considera-se como boas práticas em obstetrícia:","options":{"A":"Amniotomia com dilatação de 9 cm em diante com intuito de acelerar o trabalho de parto e evitar\no sofrimento fetal.","B":"Utilização de água morna, técnicas de relaxamento e técnicas de relaxamento para alívio da dor\ne verticalização do trabalho de parto.","C":"Episiotomia nas primíparas.","D":"Analgesia de parto durante a fase ativa para todas as pacientes, no intuito de aliviar a dor da\nfase final do trabalho de parto.","E":"Utilização mandatória de partograma na fase ativa de trabalho de parto e toques vaginais\nrepetidos a cada hora em todas as pacientes durante a fase ativa."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-187460","number":"187460","sourceNumber":"187460","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Partograma mostrando colo uterino pérveo 4 cm, polo cefálico em -2 de deLee e 6\ncontrações em 10 minutos. BCF auscultado apresenta desacelerações iniciadas no final das\ncontrações, variando de 80 a 100 batimentos por minuto. O diagnóstico provável seria:","options":{"A":"Taquissistolia, com sofrimento fetal agudo;","B":"Taquissistolia com provável circular de cordão;","C":"Padrão habitual para fase ativa do trabalho de parto e desaceleração habitual durante as\ncontrações;","D":"Desproporção céfalopélvica, com sofrimento fetal agudo;","E":"Taquissistolia, com presença de líquido meconial;"},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-155382","number":"155382","sourceNumber":"155382","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Entre as indicações absolutas de cesariana pode ser citado:","options":{"A":"descolamento prematuro da placenta.","B":"vasa prévia.","C":"placenta prévia total.","D":"duas cesarianas anteriores.","E":"paraplegia."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-155417","number":"155417","sourceNumber":"155417","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Considera-se como boas práticas em obstetrícia durante o acompanhamento do\ntrabalho de parto:","options":{"A":"Episiotomia mandatória nas primíparas.","B":"Amniotomia de rotina em pacientes com mínimo de 7 cm de dilatação.","C":"Desestimular posições verticais e deambulação durante o trabalho de parto.","D":"Orientação de dieta zero pelo risco de aspiração em caso de cesariana de urgência.","E":"Uso de medidas não farmacológicas para alívio da dor."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-162535","number":"162535","sourceNumber":"162535","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Das assertivas abaixo: I-Herpes genital ativo; II- cesariana prévia; III- placenta prévia\ntotal; IV- macrossomia fetal; São indicações verdadeiras de cesariana:","options":{"A":"I, II e III.","B":"I e III.","C":"III e IV.","D":"I, III e IV.","E":"Todas as assertivas são corretas."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-162545","number":"162545","sourceNumber":"162545","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Considera-se boa prática em assistência obstétrica:","options":{"A":"Amniotomia de rotina com dilatação de 7 cm em diante com intuito de acelerar o trabalho de\nparto.","B":"Uso de ocitocina sintética para acelerar o período expulsivo e evitar o sofrimento fetal agudo.","C":"Analgesia de parto durante a fase ativa para todas as pacientes, no intuito de aliviar a dor da\nfase final do trabalho de parto.","D":"Utilização mandatória de partograma na fase ativa de trabalho de parto e toques vaginais\nrepetidos a cada hora em qualquer paciente em fase ativa.","E":"Utilização de métodos não farmacológicos de alívio da dor e verticalização do trabalho de parto."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-148600","number":"148600","sourceNumber":"148600","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Avalie o partograma abaixo. (VER IMAGEM). Qual a conduta a ser adotada neste\nmomento?","options":{"A":"Aguardar porque a evolução esta adequada.","B":"Indução com occitocina venosa.","C":"Indicar parto cesareana.","D":"Sala de parto e aplicar fórceps.","E":"Realizar embriotomia."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-137846","number":"137846","sourceNumber":"137846","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O diagnóstico de ruptura prematura de membranas significa:","options":{"A":"Ruptura espontânea das membranas fetais antes de 37 semanas.","B":"Ruptura espontânea das membranas fetais antes do inicio do trabalho de parto.","C":"Ruptura espontânea das membranas fetais antes de 34 semanas.","D":"Ruptura espontânea ou artificial das membranas fetais antes do inicio do trabalho de parto e\ncom menos de 37 semanas.","E":"Ruptura espontânea ou artificial das membranas fetais antes do inicio do trabalho de parto e\ncom menos de 34 semanas."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-127149","number":"127149","sourceNumber":"127149","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em uma gestação de 26 semanas, com rotura prematura das membranas e sinais\nclínicos e laboratoriais de corioamnionite, a melhor conduta é:","options":{"A":"Interrupção da gravidez com dilatação e curetagem.","B":"Tratamento com antibióticos e interrupção da gravidez.","C":"Repouso absoluto, corticóide e tocolíticos.","D":"Repouso absoluto, corticoide e antibioticoterapia.","E":"Antibioticoprofilaxia com Penicilina G cristalina, IV, 5 milhões de unidades, seguida de 2,5\nmilhões a cada 4 horas."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-126910","number":"126910","sourceNumber":"126910","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em relação à estática fetal é INCORRETO afirmar que:","options":{"A":"Na situação transversa a apresentação é córmica, sendo que a variedade mais frequente é a de\nombro.","B":"A identificação da linha facial é importante no diagnóstico da apresentação cefálica defletida de\n3° grau.","C":"A identificação da sutura sagital é importante no diagnóstico da apresentação cefálica defletida\nde 1° grau.","D":"O sulco interglúteo é fundamental no diagnóstico da apresentação pélvica."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-126920","number":"126920","sourceNumber":"126920","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em relação ao secundamento placentário, é CORRETO afirmar que:","options":{"A":"A placenta acreta ocorre como consequência da ausência da decídua basal e da deficiente\nformação da camada de Nitabuch.","B":"O encarceramento placentário ocorre devido à presença de anéis de constrição.","C":"A retenção de cotilédones surge com mais frequência na extração manual da placenta.","D":"A manobra de Credé é uma manobra importante no tratamento clínico das retenções de\ncotilédones."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-127193","number":"127193","sourceNumber":"127193","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O trabalho de parto é caracterizado por diversas mudanças e transformações que\nocorrem ao longo do tempo no organismo materno, identificados como fases ou estágios. Qual\nopção abaixo caracteriza o primeiro estágio clínico do trabalho de parto?","options":{"A":"Metrossístole com tríplice gradiente descendente.","B":"Apagamento e dilatação completa do colo.","C":"Coroamento e expulsão fetal.","D":"Separação e expulsão da placenta.","E":"Primeira hora após o parto."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-131687","number":"131687","sourceNumber":"131687","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em relação à ruptura prematura das membranas, analise as afirmativas:I - É a principal\ncausa de trabalho de parto pré-termo;II - É a ruptura das membranas antes de 37 semanas de\ngestação;III - O diagnóstico deve ser sempre confirmado através de ultrassonografia;IV - O uso de\nmisoprostol está contraindicado na indução do parto pelo risco de infecção;Estão corretas as\nafirmativas:","options":{"A":"I e II","B":"Apenas I;","C":"I, II e III;","D":"III e IV;","E":"I, II e IV;"},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-131672","number":"131672","sourceNumber":"131672","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A manobra de Tarnier (mobilização da apresentação) é utilizada para diagnóstico\nde qual situação:","options":{"A":"Distócia de ombros;","B":"Assinclitismo;","C":"Apresentação pélvica;","D":"Bolsa rota;","E":"Desproporção cefalopélvica;"},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-131671","number":"131671","sourceNumber":"131671","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Dos medicamentos abaixo, quando administrado durante o trabalho de parto\nprematuro, tem como principal objetivo a profilaxia da paralisia cerebral do\n\nrecém-nascido(neuroprotetor):","options":{"A":"Betametasona;","B":"Dexametasona;","C":"Nifedipina;","D":"Vitamina B;","E":"Sulfato de magnésio:"},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-100973","number":"100973","sourceNumber":"100973","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O número crescente de operações cesarianas no Brasil atingiu estatísticas alarmantes,\nprincipalmente pelo volume de cirurgias desnecessárias, indicando um despreparo das instituições\ne dos profissionais assistentes. A cesariana tem indicações absolutas e relativas. Assinale a\nsituação abaixo que não caracteriza uma indicação absoluta para cesariana:","options":{"A":"Desproporção cefalopélvica.","B":"Cicatriz uterina corporal prévia.","C":"Placenta prévia total.","D":"Morte materna com feto vivo.","E":"Feto não reativo na cardiotocografia."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-100983","number":"100983","sourceNumber":"100983","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Para uma gestante com 41 semanas e 6 dias, com índice de líquido amniótico de 8cm,\níndice de Bishop de 4 e cardiotocografia com feto ativo e reativo, a conduta obstétrica indicada é:","options":{"A":"Aguardar o trabalho de parto espontâneo.","B":"Fazer a maturação do colo com misoprostol, seguida de indução com ocitocina.","C":"Fazer a condução do trabalho de parto com misoprostol.","D":"Realizar a cesariana segmentar imediata.","E":"Aguardar 24 horas, se não entrar em trabalho de parto espontâneo, realizar a cesariana."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-102732","number":"102732","sourceNumber":"102732","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em relação aos estreitos pélvicos, assinale a alternativa INCORRETA.","options":{"A":"O estreito superior é formado pela união da 5ª vértebra lombar com a 1ª vértebra sacral.","B":"Limite anterior do estreito superior da bacia é a sínfise púbica.","C":"As paredes laterais da bacia são formadas pela união das asas do sacro, das articulações\nsacroilíacas, pelas linhas inominadas e pelas eminências iliopectíneas.","D":"O diâmetro anteroposterior representa a distância entre o promontório e a sínfise púbica e\nsubdividi-se em outros quatro diâmetros."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-106401","number":"106401","sourceNumber":"106401","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Sobre a assistência ao parto pélvico, a única opção INCORRETA seria:","options":{"A":"Na Manobra de Bracht, o parteiro deflete o dorso fetal em direção ao ventre materno;","B":"A Manobra de Deventher - Muller pode ser utilizada para desprendimento do polo cefálico;","C":"Na manobra de Mauriceau, o parteiro introduz os dedos indicador e médio na orofaringe fetal\nforçando a deflexão do polo cefálico;","D":"O fórcipe de Piper pode ser utilizado no encravamento do polo cefálico;","E":"A Manobra de Rojas pode ser utilizada para desprendimento das espáduas;"},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-106371","number":"106371","sourceNumber":"106371","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em relação à ruptura prematura das membranas, podemos afirmar que:","options":{"A":"o período de latência é definido como o período de tempo decorrido entre o início da perda de\nlíquido e a evolução do quadro clínico para corioamnionite;","B":"a inibição da contratilidade uterina deve sempre ser opção diante de trabalho de parto franco;","C":"o objetivo da antibioticoterapia é manter a gestação a termo;","D":"em casos de corioamnionite a resolução da gravidez deve ser urgente e via alta;","E":"o toque vaginal deve ser evitado, só sendo justificado nas gestações com indicação de\ninterrupção ou em trabalho de parto;"},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-106376","number":"106376","sourceNumber":"106376","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Partograma mostrando colo uterino pérveo para 9 cm há 2 horas e polo cefálico fetal\nem -2 de De Lee há 3 horas, com 5 metrossístoles em 10 minutos. Qual o diagnóstico provável?","options":{"A":"distócia de partes moles;","B":"desproporção cefalopélvica;","C":"distócia funcional;","D":"período prolongado da dilatação;","E":"distócia de ombros"},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-106379","number":"106379","sourceNumber":"106379","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em relação à corticoterapia antenatal, podemos afirmar, exceto:","options":{"A":"o corticoide induz o pneumócito tipo II a produzir surfactante;","B":"com o objetivo de promover a maturidade pulmonar fetal devemos utilizar os fluorcorticoides;","C":"está indicado para as gestantes de risco para parto prematuro;","D":"está relacionada com o aumento do risco de infecção neonatal e materna, não sendo indicado\nseu uso nos casos de ruptura prematura das\nmembranas;","E":"entre outros efeitos, reduz a incidência da mortalidade neonatal e da enterocolite necrotizante;"},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-106387","number":"106387","sourceNumber":"106387","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A prematuridade ainda é, nos dias atuais, um desafio na assistência obstétrica. Em\nrelação à tocólise, podemos afirmar:","options":{"A":"após tocólise, não há efeito benéfico do tratamento de manutenção rotineiramente;","B":"há fortes evidências favorecendo o uso profilático dos agentes tocolíticos;","C":"os betamiméticos devem ser preferidos em relação aos bloqueadores de canal de cálcio;","D":"os betamiméticos, apesar de não serem muito eficazes, apresentam poucos efeitos colaterais\nmaternos e fetais;","E":"o objetivo principal da inibição do trabalho de parto prematuro é permitir a transferência da\ngestante para um centro de assistência terciária."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-88873","number":"88873","sourceNumber":"88873","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Herpes genital ativo é considerado contraindicação absoluta ao parto: I. Vaginal. II.\nCesário. III. Instrumentado. Quais estão corretas?","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas I e II.","D":"Apenas I e III.","E":"I, II e III."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-77603","number":"77603","sourceNumber":"77603","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Sobre o uso de tocolíticos em obstetrícia, podemos afirmar:","options":{"A":"Indometacina é considerada o tocolítico de primeira escolha.","B":"Deve ser usado por 48 horas em concomitância com o corticoide para maturação pulmonar do\nfeto.","C":"Está indicado apenas para gestantes com idade gestacional superior a 28 semanas.","D":"A nifedipina, devido ao seu importante efeito hipotensor, não é considerada um tocolítico de\nprimeira escolha.","E":"Deve-se evitar o uso de tocolíticos quando a dilatação do colo uterino for maior que 2,5\ncentímetros."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-77485","number":"77485","sourceNumber":"77485","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente primigesta em trabalho de parto, apresenta feto em BEA. Podemos afirmar\nque o feto se encontra em:","options":{"A":"Situação longitudinal, apresentação cefálica fletida, com dorso à esquerda.","B":"Situação longitudinal, apresentação cefálica defletida de 1º grau, com dorso à direita.","C":"Situação longitudinal, apresentação cefálica fletida, com dorso à direita.","D":"Situação longitudinal, apresentação cefálica defletida 2º grau, com dorso à esquerda.","E":"Situação longitudinal, apresentação cefálica defletida 1º grau, com dorso à esquerda."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-77538","number":"77538","sourceNumber":"77538","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"São recomendações para a humanização do parto, exceto:","options":{"A":"Realizar tricotomia e enema de rotina.","B":"Permitir a presença de acompanhante da escolha da parturiente.","C":"Dar liberdade de escolha de posição e movimento.","D":"Alívio da dor por métodos não invasivos e farmacológicos.","E":"Contato cutâneo direto, precoce entre mãe e filho e apoio ao início da amamentação na primeira\nhora após o parto."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-59023","number":"59023","sourceNumber":"59023","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Marque a alternativa incorreta sobre varicela na gravidez.","options":{"A":"A varicela na gravidez antes de vinte semanas pode levar a malformações fetais.","B":"Pacientes que não tiveram contato com o vírus da varicela não devem ser vacinadas durante a\ngravidez.","C":"Indica-se imunoglobulina (VZIG) para recém-nascidos de mães que apresentarem quadro de\nvaricela nos últimos cinco dias de gestação até dois dias após o parto.","D":"A vacina para varicela é um vírus vivo atenuado.","E":"Não está indicado o uso de imunoglobulina (VZIG) na mãe susceptível que teve exposição a\ninfectados para prevenir doença no feto."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-44000","number":"44000","sourceNumber":"44000","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante com trinta e sete semanas, primigesta, dá entrada na maternidade do HUCAM\ncom vinte horas de rotura prematura das\nmembranas ovulares que foi confirmada ao exame\nespecular. Qual a conduta mais apropriada?","options":{"A":"Cultura para estreptococos de grupo B. Caso positivo, fazer penicilina cristalina e indução do\nparto.","B":"Indução do parto com profilaxia para estreptococo do grupo B.","C":"Indicação imediata de parto cesáreo sem profilaxia para estreptococo do grupo B.","D":"Aguardar trabalho de parto espontâneo sem penicilinina cristalina.","E":"Conduta expectante e pesquisa de sinais relacionados à infecção amniótica."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-32481","number":"32481","sourceNumber":"32481","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Parto é o mecanismo de expulsão de feto e placenta. O objetivo da assistência\nprestada nesse processo é de promover um\nnascimento seguro para mães e seus recém-nascidos.\nO conhecimento desse processo beneficia a família que nasce. Sobre o parto, é incorreto afirmar.","options":{"A":"Antes do início do trabalho de parto acontecem alterações fisiológicas preparatórias como a\ninsinuação, com abaixamento da região abdominal alta e aumento da pressão na pelve.","B":"Durante as últimas 04 semanas ocorrem contrações uterinas irregulares e geralmente indolores,\ncuja frequência aumenta lentamente.","C":"Nas semanas que antecedem o início do trabalho de parto, a cérvice pode começar a amolecer,\nafinar e dilatar.","D":"O início do trabalho de parto algumas vezes é marcado pela emissão de pequena quantidade de\nmuco cervical sanguinolento.","E":"A deflexão é essencial para o encaixe e descida e consequentemente sucesso no parto e\ninterfere nesse processo a configuração da pelve, o tamanho e a posição da apresentação."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-9412","number":"9412","sourceNumber":"9412","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A manobra de Mauriceau é utilizada para:","options":{"A":"Parto cesárea.","B":"Parto pélvico.","C":"Parto cefálico.","D":"Assinclitismo.","E":"Sinclitismo."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-8135","number":"8135","sourceNumber":"8135","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"São fatores predisponentes para trabalho de parto prematuro, exceto:","options":{"A":"Infecção do trato urinário, que evolui com pielonefrite.","B":"Placenta prévia parcial.","C":"Neoplasia intraepitelial cervical (NIC) com HPV presente.","D":"Pré-eclâmpsia grave.","E":"Ruptura de membranas com 32 semanas."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-9439","number":"9439","sourceNumber":"9439","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A terceira manobra de Leopold avalia:","options":{"A":"Pólo fetal.","B":"Situação fetal.","C":"Altura do pólo fetal.","D":"Assinclitismo.","E":"Fontanelas."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-9443","number":"9443","sourceNumber":"9443","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Na distócia de ombro deve-se fazer:","options":{"A":"Extração com fórceps.","B":"Extração com vácuo.","C":"Manobra de McRoberts.","D":"Extração usando a força.","E":"Aguardar saída espontânea."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-363901","number":"363901","sourceNumber":"363901","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"No trabalho de parto, as posições das pernas da parturiente modificam a amplitude da\nbacia. A flexão exagerada das pernas sobre as coxas e desta sobre o tronco aumenta o diâmetro\ndo","options":{"A":"estreito inferior, favorecendo o desprendimento fetal.","B":"estreito superior, dificultando a descida do polo cefálico.","C":"estreito superior, facilitando o encaixamento polo cefálico.","D":"estreito médio, melhorando a velocidade de descida do polo cefálico."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-363900","number":"363900","sourceNumber":"363900","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A clidotomia é uma manobra utilizada no trabalho de parto em situações quando se tem","options":{"A":"cabeça derradeira.","B":"distocia de colo.","C":"distocia de ombro.","D":"dificuldades na extração do feto por cesariana."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-363899","number":"363899","sourceNumber":"363899","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Mulher em gestação a termo chega à emergência em período expulsivo, com o feto em\napresentação pélvica completa, em plano +1 de De Lee. Nesta situação, a conduta inicial correta é","options":{"A":"o fórceps de Piper.","B":"a cesariana de urgência.","C":"a manobra de deventer-Müller.","D":"a episiotomia, com consentimento, e manobra de Bracht."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-363898","number":"363898","sourceNumber":"363898","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Nos casos de prematuridade, a droga utilizada para a neuroproteção do concepto é","options":{"A":"o sulfato de magnésio.","B":"a betametazona.","C":"a ritodrina.","D":"o atosiban."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-346419","number":"346419","sourceNumber":"346419","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente G3P2A0, idade gestacional (IG) = 33 semanas, comparece ao pronto\natendimento com queixa de dor abdominal,\nleucorreia fétida e febre aferida hoje, temperatura axilar\n\n= 38ºC. Exame: altura uterina (AU) = 30cm; dinâmica uterina (DU) = 2 contrações fortes em 10\nminutos; batimento cardíaco fetal = 140 batimentos/minuto. Saída de secreção purulenta pelo\norifício do colo. Toque vaginal: dilatação de 5cm, com colo fino, anterior. Cardiotocografia com\npadrão tranquilizador. Qual deve ser a conduta?","options":{"A":"Antibioticoterapia e assistência ao trabalho de parto, ao parto e ao puerpério;","B":"Internação, inibição de trabalho de parto e corticoterapia intravenosa materna;","C":"Resolução da gestação por via alta imediatamente, considerando a vitalidade fetal;","D":"Antibioticoterapia, inibição do trabalho de parto e início de corticoterapia materna."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-331988","number":"331988","sourceNumber":"331988","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Sobre a maturação (UFPB - do colo uterino, utiliza-se, frequentemente, o índice de\nBishop para a sua avaliação clínica. Fazem parte desta avaliação os itens abaixo, exceto:","options":{"A":"Dilatação cervical.","B":"Altura da apresentação fetal.","C":"Esvaecimento cervical.","D":"Linhas de orientação da apresentação fetal.","E":"Consistência cervical."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-339799","number":"339799","sourceNumber":"339799","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente 22 anos de idade, primigesta e na 41ª semana de gravidez. Veio para\nemergência obstétrica com queixa de dor em baixo\ndo ventre há 12h tipo cólica. Ao exame,\ndinâmica uterina de 4 contrações/10 minutos/55 segundos. Batimentos cardiofetais de 156 bpm.\nAltura de fundo uterino de 34cm. Toque vaginal com 6 cm de dilatação, bolsa das íntegras, cefálico\ne 80% de esvaecimento cervical. O trabalho de parto evoluiu de forma lenta e, durante o período\nexpulsivo, ocorreu o sinal da tartaruga. Assinale a alternativa que NÃO é fator de risco para o\ndiagnóstico do período expulsivo.","options":{"A":"Obesidade","B":"Termo tardio","C":"Macrossomia","D":"Parto vaginal assistido","E":"Lúpus eritematoso sistêmico"},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-339801","number":"339801","sourceNumber":"339801","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante na 41ª semana de gravidez, secundigesta, com uma cesariana anterior a\nFuchs Marshall e assintomática. Veio à\nemergência por estar passando do tempo. Ao exame\nobstétrico, dinâmica uterina ausente, batimentos cardiofetais de 144 bpm. Realizado toque vaginal\ncom o colo uterino fechado, longo (5cm), posterior, de consistência firme e feto alto e móvel (- 3\nde\nDe Lee). Qual o escore de Bishop modificado e a conduta CORRETA mais adequada?","options":{"A":"8 - Indução do trabalho de parto com ocitocina.","B":"0 - Indução do trabalho de parto com misoprostol.","C":"10 - Expectante até 41 s6d.","D":"0 - Indução do trabalho de parto com método mecânico.","E":"5 - Indução do trabalho de parto com Sonda de Foley."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-339814","number":"339814","sourceNumber":"339814","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Analise o partograma a seguir. Com base no partograma, o diagnóstico é de:","options":{"A":"período expulsivo prolongado.","B":"parada secundária da descida.","C":"parada secundária de dilatação.","D":"fase ativa prolongada."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-334164","number":"334164","sourceNumber":"334164","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Quando ocorre a passagem do maior diâmetro fetal da apresentação pelo estreito\nsuperior da vagina damos o nome de:","options":{"A":"Rotação interna.","B":"Descida.","C":"Insinuação.","D":"Flexão."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-334166","number":"334166","sourceNumber":"334166","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A linha de sutura que separa os parietais é a:","options":{"A":"Sagital.","B":"Metópica.","C":"Bregmática.","D":"Occipital."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-342668","number":"342668","sourceNumber":"342668","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Com relação ao trabalho de parto normal, considere as afirmativas a seguir: |- O parto é\no período que vai do início das contrações\nuterinas regulares até a expulsão da placenta. || - O\ntrabalho de parto é caracterizado por contrações uterinas que geram o apagamento e a dilatação\ndo colo. III - O 2º estágio do trabalho de parto começa quando a dilatação cervical está completa.\nIV\n\n- Na fase ativa do trabalho de parto, a velocidade esperada de dilatação do colo é, em média, de 1\ncm/h. Estão corretas:","options":{"A":"I,II","B":"I, IlI","C":"II, III","D":"I, II, III, IV"},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-300899","number":"300899","sourceNumber":"300899","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Segundo o CFM em Resolução 2144 de 2016, é permitido ao obstetra a realização de\n\"cesárea à pedido\", em gestação de risco habitual, desde que a mesma se encontre em pelo\nmenos:","options":{"A":"37 semanas.","B":"38 semanas.","C":"39 semanas.","D":"40 semanas."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-308215","number":"308215","sourceNumber":"308215","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"As contrações uterinas assumem tríplice gradiente descendente:","options":{"A":"Na fase puerperal.","B":"No início do trabalho de parto.","C":"Quando a dilatação do colo atinge 6 cm.","D":"No período expulsivo."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-308216","number":"308216","sourceNumber":"308216","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em apresentações cefálicas defletidas de 1º, 2º, 3º graus, os pontos de referência fetais\nsão respectivamente:","options":{"A":"Lambda, glabela e mento.","B":"Bregma, glabela e mento.","C":"Glabela, mento e bregma.","D":"Bregma, lambda e mento."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-300904","number":"300904","sourceNumber":"300904","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Uma gestante com idade gestacional de 35 semanas, dá entrada na maternidade com\nquadro de DHEG grave e síndrome HELLP. O obstetra de plantão opta por cesárea imediata. A\ncontagem de plaquetas é de 55.000/ml. A MELHOR opção anestésica nesse caso é:","options":{"A":"raquidiana.","B":"geral.","C":"combinada raqui/peridural.","D":"somente anestesia local."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-302857","number":"302857","sourceNumber":"302857","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Apresentação pélvica agripina corresponde à(ao):","options":{"A":"Completa.","B":"Pélvico-Podálica.","C":"Modo de pés.","D":"Modo de joelhos.","E":"Modo de nádega."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-317182","number":"317182","sourceNumber":"317182","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Considere as seguintes características da bacia: estreito superior arredondado,\ndiâmetro transverso máximo afastado do\npromontório e do pube (porção posterior da bacia\nespaçosa), diâmetro bi-isquiático grande. As características mencionadas se referem a qual tipo de\nbacia?","options":{"A":"Androide.","B":"Ginecoide.","C":"Antropoide.","D":"Platipeloide."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-314137","number":"314137","sourceNumber":"314137","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Analise o partograma a seguir. Com base no partograma, o diagnóstico é de:","options":{"A":"Período expulsivo prolongado.","B":"Parada secundária da descida.","C":"Parada secundária de dilatação.","D":"Fase ativa prolongada."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-317184","number":"317184","sourceNumber":"317184","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"\"Uma paciente grávida, saudável, que apresente atividade uterina em torno de 15 UM\n(Unidade Montevidéu), \"provavelmente estará em qual época da gravidez?","options":{"A":"Durante o parto.","B":"Em torno de 6 horas após o parto.","C":"Antes de 30 semanas de gestação.","D":"Após 30 semanas de gestação, no pré-parto."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-311933","number":"311933","sourceNumber":"311933","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante de 33 semanas procura o serviço de obstetrícia com queixa de dor em baixo\nventre e perda de líquido pela vagina há 6 horas. Ao examinar, percebe-se a dinâmica uterina de\numa contração de trinta segundos em dez minutos, batimentos cardíacos fetal de 150bpm, pressão\narterial de 120/80mmHG. Exame especular revela saída de líquido amniótico pelo colo uterino, que\nestá dilatado para dois centímetros. Qual a conduta para esse caso?","options":{"A":"Iniciar a condução da dinâmica uterina com ocitocina.","B":"Realizar a cesárea após a corticoterapia por 48 horas.","C":"Prescrever sulfato de magnésio para neuroproteção e inibir o trabalho de parto.","D":"Inibir o trabalho de parto por 48 horas e corticoterapia."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-317185","number":"317185","sourceNumber":"317185","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"\"Uma paciente com rotura prematura das membranas, em que a indução do parto está\nindicada, apresenta um Índice de Bishop de 6. \"Qual deve ser a conduta principal nessa paciente?","options":{"A":"Ocitocina.","B":"Misoprostol.","C":"Amniotomia.","D":"Estimulação dos mamilos."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-315810","number":"315810","sourceNumber":"315810","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A contratilidade uterina indolor que tem início em torno de 30 semanas de gestação\nleva o nome de:","options":{"A":"Bandeamento.","B":"Braxton-Hicks.","C":"Puxos vaginais.","D":"Hipercinesia."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-315812","number":"315812","sourceNumber":"315812","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O sinal ultrassonográfico de agregado espesso de partículas no liquido amniótico\npróximo ao orifício interno do colo uterino, que\npode ser usado como preditivo de prematuridade,\ntem o nome de:","options":{"A":"Sludge.","B":"Mecônio.","C":"Corpo lamelar.","D":"Vérnix."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-317192","number":"317192","sourceNumber":"317192","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em uma mulher sem acompanhamento pré-natal, em trabalho de parto com 38\nsemanas, o feto está na apresentação pélvica.\nÁ medida que as nádegas saem, observamos uma\nespinha bífida. A cabeça não nasce. Com essa história, a possibilidade mais provável é:","options":{"A":"Hidrocefalia","B":"Desproporção cefalopélvica","C":"Bócio fetal","D":"Trabalho de parto não detectado"},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-311945","number":"311945","sourceNumber":"311945","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A apresentação pélvica está presente em 4% das gestantes no termo. Constitui\ncondição de maior risco, tanto pelas dificuldades intrínsecas do parto pélvico quanto pelas\ncircunstâncias desfavoráveis. Sobre o parto pélvico podemos afirmar que:","options":{"A":"a manobra de Mauriceau tem como objetivo flexionar o polo cefálico do feto, na cabeça\nderradeira, utilizando um dedo introduzido na boca do feto para facilitar a flexão.","B":"o fórcipe mais adequado e utilizado na cabeça derradeira é o fórceps de Simpson.","C":"a apresentação pélvica simples é quando o feto apresenta as coxas e pernas fletidas, com os\npés junto às nádegas.","D":"a manobra de Rojas, constitui uma manobra rotacional do feto com objetivo de desprender a\ncabeça derradeira."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-316351","number":"316351","sourceNumber":"316351","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"No mecanismo do trabalho de parto, o maior diâmetro do crânio fetal é:","options":{"A":"Occipitofrontal.","B":"Suboccipitobregmático.","C":"Occipitomentoniano.","D":"Suboccipitofrontal."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-295401","number":"295401","sourceNumber":"295401","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O estreito superior da pelve é composto, dentre outras estruturas, por","options":{"A":"cóccix e borda superior do corpo e da sínfise pubiana.","B":"saliência do promontório e borda inferior do corpo e da sínfise pubiana.","C":"saliência do promontório e borda superior do corpo e da sínfise pubiana.","D":"cóccix e borda inferior do corpo e da sínfise pubiana."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-313246","number":"313246","sourceNumber":"313246","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Com relação às fases clínicas do parto, pode-se afirmar que:","options":{"A":"O 2° período começa com a dilatação total da cérvice e termina com a expulsão do feto.","B":"O 1° período consiste no período prodrômico.","C":"O secundamento ocorre no 2° período do parto.","D":"O 4° período caracteriza-se pelo descolamento, pela descida e pela expulsão da placenta e dos\nanexos."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-317989","number":"317989","sourceNumber":"317989","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Secundigesta com 24 semanas, 28 anos de idade, por volta do exame\nultrassonográfico para avaliação da\nmorfologia fetal, mostra colo com comprimento de 2,0 cm. Tem\nantecedentes de parto normal taquitócico, há cerca de dois anos, sem episiotomia e com\nsangramento pós-parto aumentado. Diante deste quadro, a conduta correta é a","options":{"A":"realização da cerclagem do colo uterino.","B":"utilização de atosiban até a 34ª semana.","C":"utilização de progesterona até a 34ª semana.","D":"utilização de atosiban e progesterona até a 32ª semana."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-317990","number":"317990","sourceNumber":"317990","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Sludge é um sinal ultrassonográfico associado","options":{"A":"à rotura prematura das membranas.","B":"à placenta prévia marginal.","C":"à vasa prévia.","D":"ao parto prematuro."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-313252","number":"313252","sourceNumber":"313252","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Uma parturiente se encontra com 6cm de dilatação. A apresentação está em OEA em\n\n-1 de DeLee. Diante dessas informações, assinale a alternativa correta:","options":{"A":"para ocorrer o parto, o feto deve rodar 90o e se colocar em OP","B":"o feto está insinuado, pois já está com 6cm de dilatação","C":"o ponto de referência é o bregma, e a linha de orientação é a sutura sagital","D":"para ocorrer o desprendimento do polo cefálico no expulsivo, a apresentação deve fazer um\nmovimento de deflexão"},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-274456","number":"274456","sourceNumber":"274456","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em apresentações cefálicas defletidas de 1°, 2° e 3° grau, os pontos de referência\nfetais são respectivamente:","options":{"A":"Lambda, glabela e mento.","B":"Bregma, glabela e mento.","C":"Glabela, mento e bregma.","D":"Bregma, lambda e mento."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-274457","number":"274457","sourceNumber":"274457","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"As contrações uterinas assumem o tríplice gradiente descendente:","options":{"A":"Na fase puerperal.","B":"No início do trabalho de parto.","C":"Quando a dilatação do colo atinge 6 cm.","D":"No período expulsivo."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-274784","number":"274784","sourceNumber":"274784","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Após 10 minutos do nascimento do recém-nascido de um parto vaginal com analgesia,\na placenta ainda não dequitou, e não tem\nsangramento. O que você deveria fazer?","options":{"A":"Realizar a manobra de inversão uterina.","B":"Tracionar vigorosamente o cordão umbilical.","C":"Realizar a manobra de Jacob-dublin.","D":"Realizar massagens uterinas com tração suave do cordão."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-274786","number":"274786","sourceNumber":"274786","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Após a dequitação da placenta é formado o globo de segurança de Pinnard que tem\ncomo função evitar uma hemorragia excessiva. Dentro dos mecanismos envoltos nesse processo,\nqual é o mais importante, por prevenir a principal causa de hemorragia pós-parto?","options":{"A":"Contração das fibras musculares uterinas sobre os vasos do leito placentário.","B":"Aumento dos fatores de coagulação no interior do vaso.","C":"Coagulação vascular intramiometrial por vasoconstrição.","D":"Aumento da agregação placentária durante do período de dequitação."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-277447","number":"277447","sourceNumber":"277447","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Uma gestante de 23 anos, G1P0, com 29 semanas de gestação, com queixas de dores\nabdominais intermitentes, nega perdas vaginais. O exame clínico era normal. Ao exame obstétrico,\ndetectaram-se contrações uterinas: 3/10?/40? toque vaginal com colo apagado 80%, dilatado 3cm\npolo cefálico no plano -1 de Delee batimentos cardiofetais = 136bpm. Assinale o diagnóstico e o\ntratamento adequados ao caso:","options":{"A":"Feto prematuro uso de corticoide","B":"Deslocamento prematuro da placenta cesárea","C":"Falso trabalho de parto observação","D":"Trabalho de parto prematuro tentativas de inibição específicas"},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-281306","number":"281306","sourceNumber":"281306","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A pesquisa de fibronectina fetal para predição de prematuridade deve ser realizada\nentre:","options":{"A":"10 e 12 semanas.","B":"14 e 16 semanas.","C":"22 e 24 semanas.","D":"34 e 36 semanas."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-281307","number":"281307","sourceNumber":"281307","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O segundo tempo do trabalho de parto é:","options":{"A":"O período de dilatação.","B":"O período da dilatação total até a expulsão fetal.","C":"O período da expulsão até a dequitação.","D":"A primeira hora do pós parto."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-281308","number":"281308","sourceNumber":"281308","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Para uma paciente com uma cesárea anterior há 4 anos por apresentação córmica,\natualmente com gestação de termo (40 semanas), que solicita indução do parto, o método\ncontraindicado é:","options":{"A":"Amniotomia.","B":"Prostaglandina.","C":"Ocitocina.","D":"Ruptura de membranas."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-273183","number":"273183","sourceNumber":"273183","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente gestante, 28 anos (G1P0), em primeira gestação, com 38 semanas completas\nde gravidez, em fase ativa de trabalho de parto,\ncom 4 cm de dilatação, alteração do colo de 4 para\n7 cm em 2 horas e contrações com intervalos de 7 a 10 minutos. Quanto ao trabalho de parto:","options":{"A":"Como ela é nulípara, a expectativa é de que o colo se dilataria em uma velocidade de pelo\nmenos 1,2 cm/h durante a fase ativa do\ntrabalho de parto, e ela não atendeu a esse critério, o que\nindica anormalidade do trabalho de parto.","B":"O padrão de contração uterina parece sub ótimo, o que indica a normalidade do trabalho de\nparto.","C":"É a alteração no colo por hora e não o padrão de contração uterina que indica a normalidade no\ntrabalho de parto, o que é constatado nesse caso.","D":"Como ela está apresentando um trabalho de parto anormal, o manejo adequado é proceder a\nintervenção."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-257763","number":"257763","sourceNumber":"257763","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A detecção da proteína PAMG-1 (alfa 1 microglobulina) humana por\nimunocromatografia é muito útil, em obstetrícia, para o diagnóstico de","options":{"A":"rotura prematura da placenta.","B":"infecção cervical por clamídia.","C":"predição do trabalho de parto prematuro.","D":"malformações cromossômicas fetais."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-273187","number":"273187","sourceNumber":"273187","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Fatores de risco, como ter sofrido um parto prematuro anteriormente e estar grávida de\ngêmeos, aumentam as chances para que um parto prematuro ocorra. Considerando o contexto, a\nalternativa que NÃO corresponde às técnicas aplicadas a fim de retardar o parto e aprimorar o\nbem-estar do feto é:","options":{"A":"Administração de corticosteroides entre 24 e 37 semanas de gestação.","B":"Hidratação intravenosa, a qual é utilizada como uma abordagem inicial, uma vez que há a\nocorrência de desidratação.","C":"Monitoração fetal, que poderá ser interrompida caso o TPPT se resolva.","D":"Via de parto para a apresentação cefálica, quando a gestante se encontrar com mais de 26\nsemanas."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-273188","number":"273188","sourceNumber":"273188","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A cesariana consiste em uma cirurgia pélvica para a retirada do bebê, assim como o\nparto induzido. NÃO é pré-requisito para a realização de tal procedimento:","options":{"A":"Obstrução do trato genital inferior da gestante.","B":"A existência de gêmeos unidos.","C":"Cerclagem abdominal.","D":"Histórico de lesão leve no soalho pélvico."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-273189","number":"273189","sourceNumber":"273189","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A indução de parto é uma alternativa em forçar e acelerar o trabalho de parto, fazendo\ncom que ele se inicie mais rápido. É um\nmétodo seguro, contudo, utilizado somente se necessário.\nQuanto à indução do parto, é CORRETO afirmar:","options":{"A":"É indicada devido às induções eletivas para idade gestacional menor que 39 semanas.","B":"Deve-se utilizar alta dose de ocitocina, que pode ser usada com ou sem dilatadores mecânicos.","C":"É necessário cuidado no uso de prostaglandina E2 em gestantes com insuficiência hepática\ngrave.","D":"É indicada quando há prolapso do cordão umbilical."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-273193","number":"273193","sourceNumber":"273193","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Inúmeras técnicas e procedimentos para alívio da dor durante o parto são\naconselhadas, escolhidas e aplicadas, uma vez que\no trabalho de parto costuma ser um momento\nde dor intensa para a gestante. Considerando o contexto, é INCORRETO afirmar:","options":{"A":"A anestesia geral deixa a paciente consciente e incapaz de participar do momento do\nnascimento.","B":"No parto cesariano, a escolha da anestesia é determinada pela urgência do procedimento.","C":"O bloqueio das vias nociceptivas e a preservação da função motora caracteriza o objetivo da\nanestesia nos partos vaginais.","D":"No primeiro estágio do trabalho de parto, a dor visceral é aliviada mediante o uso da anestesia\nespinal."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-258226","number":"258226","sourceNumber":"258226","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Sobre as manobras de Leopold:","options":{"A":"No primeiro tempo (ou primeira manobra), o examinador consegue palpar o polo pélvico quando\no feto está em apresentação transversa.","B":"No segundo tempo (ou segunda manobra), o examinador poderá identificar o dorso fetal assim\ncomo partes fetais.","C":"No terceiro tempo (ou terceira manobra), o examinador poderá apreender o polo cefálico, caso o\nfeto esteja em apresentação pélvica.","D":"No quarto tempo (ou quarta manobra), o examinador poderá palpar o polo pélvico, caso o feto\nesteja em situação cefálica."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-252737","number":"252737","sourceNumber":"252737","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Primigesta de 20 anos, sem doenças, é admitida em centro obstétrico com 38 semanas\nde gestação, em trabalho de parto e queixa de\nperda de líquido pela vagina há 1 hora. Ao exame\nfísico: altura uterina = 33cm; dinâmica uterina = 3 contrações moderadas em 10 minutos; toque =\ncolo médio anterior com 4 cm de dilatação, bolsa rota, apresentação em ODP, com ápice na altura\ndas espinhas ciáticas; sem demais alterações. Vitalidade fetal normal. Neste momento, foi\nsolicitada analgesia pela dor da paciente. Após 3 horas, em novo exame, constata-se: dinâmica\nuterina = 3 contrações moderadas em 10 minutos; toque = colo médio, anterior, dilatado para 6 cm,\nsem alteração na variedade de posição nem altura da apresentação. Considerando vitalidade fetal\npreservada, o diagnóstico e respectiva conduta são:","options":{"A":"Trabalho de parto eutócico; reavaliar em 1 hora.","B":"Distocia funcional; introdução de ocitocina (EV).","C":"Desproporção cefalopélvica; cesárea.","D":"Distocia de rotação; cesárea."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-231956","number":"231956","sourceNumber":"231956","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Uma gestante com 35,1 semanas chega à maternidade referindo dor no baixo-ventre.\nAo exame, bom estado geral, FC = 118 bpm e Tax =\n38°C. No exame obstétrico, constatam-se\naltura uterina de 28cm, BCF = 176bpm, presença de 3 contrações útero nas moderadas em 10\nminutos e colo uterino dilatado para 3cm. No exame especular, observa-se corrimento\n\namarelo-esverdeado bolhoso, sem perda líquida. O exame de ultrassonografia mostra feto único,\ncefálico, com peso de 1.370g (P5), placenta posterior grau II - III e líquido amniótico diminuído.\n\nNeste caso, a melhor conduta seria:","options":{"A":"inibir o trabalho de parto e realizar corticoterapia em ciclo único, para maturidade pulmonar\nfetal","B":"inibir o trabalho de parto e introduzir antibioticoterapia para aumentar o período de latência","C":"acompanhar o trabalho de parto com monitorização da vitalidade fetal e introduzir ampicilina\npara a profilaxia de Strepto-coccus do grupo B","D":"inibir o trabalho de parto por 48 horas para efeito terapêutico adequado do corticosteroide na\nsíndrome do desconforto respiratório do recém-nascido","E":"indicar parto cesárea em função da prematuridade, do peso fetal e da cervicodilatação"},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-231957","number":"231957","sourceNumber":"231957","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"No puerpério, quando da execução da manobra de pressão do útero para baixo,\nseguida da sua elevação com a extremidade do\ncordão pinçada, pode-se observar a elevação da\npinça, acompanhando o órgão. Nesse caso, o diagnóstico é de:","options":{"A":"atonia uterina","B":"placenta aderida","C":"placenta prévia total","D":"restos placentários","E":"inversão uterina aguda"},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-231959","number":"231959","sourceNumber":"231959","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Com relação aos mecanismos do parto na apresentação cefálica, assinale a alternativa\ncorreta:","options":{"A":"o desprendimento do ombro posterior do feto ocorre primeiro","B":"a posição do encaixamento do feto mais frequente é a occipitopúbica","C":"a flexão da cabeça fetal propicia a exposição de seu menor diâmetro à bacia materna","D":"a rotação externa ocorre para o lado contrário da posição em que o feto se encontrava dentro da\nbacia materna","E":"a cabeça fetal atinge o estreito inferior da bacia materna geralmente na posição occipitoilíaca\nesquerda transversa"},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-231960","number":"231960","sourceNumber":"231960","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"No que se refere à conduta adequada em casos de ruptura prematura de membranas\nno parto a termo, assinale a alternativa\nCORRETA, à luz das recentes Diretrizes Nacionais de\nAssistência ao Parto Normal do Ministério da Saúde:","options":{"A":"Na ausência de contrações, deve-se realizar toque vaginal caso haja dúvida em relação ao\ndiagnóstico de ruptura das membranas.","B":"Deve-se informar à gestante que mais da metade das mulheres com ruptura precoce de\nmembranas no termo entrará em trabalho de parto em até 24 horas.","C":"Deve-se induzir o trabalho de parto até 48 horas após a ruptura precoce das membranas.","D":"Deve-se aconselhar a mulher a aguardar em domicílio, por até 24 horas, para a prevenção de\ninfecção hospitalar.","E":"Deve-se indicar cesárea se o trabalho de parto não se inicia em até 72 horas após a ruptura\nprecoce das membranas."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-247428","number":"247428","sourceNumber":"247428","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Durante o trabalho de parto observou-se a parada secundária da dilatação. Afirma-se\nsobre o exame físico e avaliação da pelve\nque:","options":{"A":"é possível medir a conjugata vera anatômica no exame físico.","B":"a pelvimetria externa, por ser menos invasiva, é amplamente utilizada na prática clínica.","C":"não é possível medir a conjugata exitus através do exame físico.","D":"é possível medir no exame físico a conjugata diagonalis para estimar a conjugata vera\nanatômica."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-248942","number":"248942","sourceNumber":"248942","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Analise as condutas a seguir na presença de risco de parto pré-termo: l- Corticoterapia\ndurante a tocólise em gestação com 30 semanas;\nII - Uso de progesterona vaginal em gestante\ncom colo curto e história prévia de parto pré-termo; III - Neuroproteção fetal com sulfato de\nmagnésio no trabalho de parto em gestação com 30 semanas; Apresenta(m) impacto na redução\nda morbimortalidade perinatal:","options":{"A":"apenas I","B":"apenas II","C":"apenas lll","D":"l,ll, lll"},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-247435","number":"247435","sourceNumber":"247435","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A distócia biacromial apesar de não frequente é uma condição grave que aumenta a\nmorbidade e mortalidade materna e perinatal. Sobre essa condição afirma-se que:","options":{"A":"a manobra de Zavanelli é a manobra mais utilizada e consiste na realização de cesariana de\nurgência.","B":"a primeira manobra a ser utilizada é a tração do polo cefálico para baixo, com o intuito de\ndesprender o ombro anterior.","C":"por se tratar de uma distócia de partes moles, apenas a realização de episiotomia já tem bons\nresultados.","D":"as manobras de primeira linha McRoberts e pressão suprapúbica resolvem 90% dessa\nintercorrência."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-249885","number":"249885","sourceNumber":"249885","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A inibição do trabalho de parto prematuro é fator de risco para","options":{"A":"o oligoâmnio.","B":"a infecção puerperal.","C":"a hipotonia uterina.","D":"a depressão pós-parto."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-248946","number":"248946","sourceNumber":"248946","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A linha de orientação na apresentação cefálica fletida é:","options":{"A":"lambda","B":"bregma","C":"sutura metópica","D":"sutura sagital"},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-249887","number":"249887","sourceNumber":"249887","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Analise a figura abaixo. De acordo com este partograma, o diagnóstico do trabalho de\nparto é de:","options":{"A":"fase latente prolongada.","B":"período pélvico prolongado.","C":"fase ativa prolongada.","D":"evolução normal do trabalho de parto."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-254258","number":"254258","sourceNumber":"254258","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente de 39 semanas é admitida com queixa de dor em baixo ventre. Ao exame,\nobservam-se 5 contrações em 10 minutos, colo dilatado 9 cm, apresentação cefálica em OEA,\nplano +1 de De Lee. Podemos afirmar que","options":{"A":"o dorso fetal encontra-se a esquerda.","B":"o feto apresenta deflexão de 1 grau.","C":"paciente está em período expulsivo.","D":"a insinuação ainda não ocorreu."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-241745","number":"241745","sourceNumber":"241745","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Durante o parto, após a saída do polo cefálico, foi feito o diagnóstico de distócia de\nombro. Dentre as seguintes manobras, qual é\nbastante eficaz e está entre as primeiras medidas a\nserem tomadas?","options":{"A":"Sinfisiotomia.","B":"Manobra de Zavanelli.","C":"Hiperflexão e abdução das coxas.","D":"Fratura de clavícula.","E":"Compressão do fundo uterino e tração do polo cefálico."},"answer":"C","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-241746","number":"241746","sourceNumber":"241746","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Sobre a indução do parto, assinale a alternativa CORRETA.","options":{"A":"O índice de Bishop tem como alguns dos parâmetros avaliados a dilatação cervical, o\napagamento do colo e a frequência das contrações uterinas.","B":"Na indução do parto de paciente com cicatriz uterina prévia, devemos utilizar metade da dose\nusual de misoprostol.","C":"Taquissistolia consiste na ocorrência de contração uterina superior a 90 segundos.","D":"A dose usual de misoprostol para indução do parto com feto vivo a termo é de 100 a 200\nmicrogramas a cada 4 a 6 horas.","E":"A utilização transcervical do cateter de Foley, com o balão inflado, é uma técnica eficaz e de\nbaixo risco para maturação do colo, sendo bastante útil na gestante com uma cesariana anterior."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-241748","number":"241748","sourceNumber":"241748","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Uma paciente com história de duas gestações anteriores, um abortamento de primeiro\ntrimestre e um parto vaginal, apresenta-se com gestação de 41 semanas e 3 dias, ausência de\ncontrações, colo grosso, posterior, 1 cm de dilatação, BCF 136 bpm. Qual a melhor conduta?","options":{"A":"Indicar cesárea por colo desfavorável para indução.","B":"Misoprostol vaginal 25 microgramas a cada 4-6 horas para preparo do colo.","C":"Misoprostol vaginal 200 microgramas a cada 4-6 horas para preparo do colo.","D":"Indução com ocitocina venosa, utilizando-se solução com concentração de 10 mUl/mL.","E":"Amniotomia, antibiótico e ocitocina, iniciando-se indução com infusão de 2 mUl/mL."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-246585","number":"246585","sourceNumber":"246585","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Gestante de 32 anos, G4PC3A0, idade gestacional de 34 semanas e 5 dias confirmada\npor ultrassom de primeiro trimestre, comparece ao\npronto-atendimento com queixa de perda de\nlíquido via vaginal iniciada há duas horas, associada a contrações. Ao exame, apresenta 3\ncontrações de 20 segundos em 10 minutos, tônus uterino normal, batimentos cardíacos fetais de\n146 bpm, exame especular evidenciando grande quantidade de líquido em fundo de saco vaginal,\ntoque vaginal com colo uterino com 6 cm de dilatação, apagamento de 70%, feto em apresentação\ncefálica, plano -2 de De Lee. Qual a melhor conduta para o caso?","options":{"A":"Prescrição de nifedipino para tocólise, associado a corticoide IM para maturação pulmonar fetal.","B":"Hidratação venosa, observação clínica e realização de propedêutica infecciosa.","C":"Medidas gerais para aguardar o parto por via vaginal.","D":"Prescrever duas doses de betametasona IM, com intervalo de 24h entre elas, para programação\nde cesariana.","E":"Parto imediato por cesariana."},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-241753","number":"241753","sourceNumber":"241753","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Em caso de parada cardiorrespiratória materna, em gestações com mais de 26\nsemanas, está indicada a cesárea perimortem quanto tempo após o início das manobras de\nressuscitação?","options":{"A":"De 4 a 6 minutos.","B":"De 10 a 15 minutos.","C":"Após 20 minutos.","D":"Após 30 minutos.","E":"Imediatamente, em caso de assístolia, ou após 12 minutos em caso de fibrilação ventricular."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-246591","number":"246591","sourceNumber":"246591","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Quanto ao \"manejo ativo do trabalho de parto\", julgue os itens a seguir. I. Amniotomia e\ninfusão de ocitocina devem ser realizadas de rotina em pacientes com 5 cm ou mais de dilatação.\n\nII. A amniotomia diminui significativamente a incidência de cesarianas por falta de progressão do\ntrabalho de parto. III. Paciente em fase ativa do trabalho de parto, sem progresso de dilatação,\ndeve ser submetida rotineiramente à amniotomia. IV. O partograma é fundamental para indicar\nmomentos de intervenções durante a fase ativa do trabalho de parto. Pode-se afirmar que apenas:","options":{"A":"o item IV está certo.","B":"os itens I e II estão certos.","C":"os itens I e IV estão certos.","D":"os itens II e IV estão certos.","E":"o item III está certo."},"answer":"A","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-234380","number":"234380","sourceNumber":"234380","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente com gestação de 39 semanas e em trabalho de parto. Durante o toque, o\nexaminador constata que o polo cefálico está no plano 0 de DeLee. Isto significa que o polo cefálico\nencontra-se ao nível de:","options":{"A":"Borda superior da sínfise púbica.","B":"Cóccix.","C":"Borda inferior da sínfise púbica.","D":"Espinhas isquiáticas."},"answer":"D","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-229906","number":"229906","sourceNumber":"229906","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"A apresentação, na estática fetal, corresponde \"a região fetal que se loca na área do\nestreito superior, ocupando-a em seu todo, ai tende a insinuar-se e, durante o trabalho de parto, é\nsede de mecanismo bem determinado.\" (REZENDE, 2013). Na apresentação fetal cefálica fletida\n(vértice ou occipital), o ponto de referência e a linha de orientação respectivamente, são","options":{"A":"acrômio e dorso fetal.","B":"lambda e sutura sagital.","C":"bregma e sutura sagitometópica.","D":"glabela e linha metópica."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-214151","number":"214151","sourceNumber":"214151","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"Paciente sem patologia prévia diagnosticada, submetida a parto vaginal a termo, após\ndez minutos do nascimento do Recém-nascido,\nnão ocorreu a dequitação placentária. A conduta\nindicada para o caso é","options":{"A":"administração de derivados do ergot intramuscular.","B":"aguardar pelo menos mais 20 minutos para iniciar as manobras.","C":"laparotomia por suspeita de acretismo placentário.","D":"extração manual da placenta com antibioticoprofilaxia."},"answer":"B","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-obstetricia-obs-2-201927","number":"201927","sourceNumber":"201927","collectionBlock":"medcurso:medcurso-obstetricia-obs-2","collectionLabel":"Medcurso · OBS 2","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"OBS 2","subtopic":"","stem":"O maior diâmetro da cabeça fetal normal é o:","options":{"A":"biparietal","B":"bitemporal","C":"occipitofrontal","D":"suboccipitobregmático","E":"occipitomentoniano"},"answer":"E","source":"Obstetricia/OBS 2/OBS 2.txt","sourceLabel":"Medcurso · OBS 2","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","OBS 2","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
